package main

import (
	"errors"
	"net/http"
	"time"
)

func (s *server) handleMe(w http.ResponseWriter, r *http.Request) {
	u := authOf(r).u
	var docs int
	var size int64
	if err := s.db.QueryRowContext(r.Context(), `SELECT count(*),COALESCE(sum(size),0) FROM docs WHERE user_id=?`, u.ID).Scan(&docs, &size); err != nil {
		serverError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"usage":                map[string]any{"docs": docs, "bytes": size, "max_docs": maxDocsPerUser, "max_bytes": maxBytesPerUser},
		"id":                   u.ID,
		"username":             u.Username,
		"role":                 u.Role,
		"must_change_password": u.MustChange,
		"version":              version,
	})
}

// verifyOwnPassword checks a password typed into a signed-in session. It shares
// the per-account failure budget with login, so a stolen cookie can't be used
// to guess the password here without limit.
func (s *server) verifyOwnPassword(w http.ResponseWriter, r *http.Request, u *user, pw string) bool {
	giveBack, ok := s.userLimit.take(u.Username) // counted as it starts, like a sign-in: see handleLogin
	if !ok {
		jsonError(w, http.StatusTooManyRequests, "Too many wrong passwords. Wait 15 minutes, then try again.")
		return false
	}
	hash, err := s.passwordHash(r.Context(), u.ID)
	if err != nil {
		giveBack()
		serverError(w, r, err)
		return false
	}
	good, err := s.checkHash(hash, pw)
	if err != nil {
		giveBack()
		jsonError(w, http.StatusServiceUnavailable, "Busy right now. Try again in a moment.")
		return false
	}
	if !good {
		s.audit(r.Context(), u.Username, "password_check_failed", u.Username, r.Method+" "+r.URL.Path, s.clientIP(r))
		jsonError(w, http.StatusForbidden, "That isn't your current password.")
		return false
	}
	giveBack()
	authOf(r).verified = append([]byte(nil), hash...)
	return true
}

func (s *server) handleChangePassword(w http.ResponseWriter, r *http.Request) {
	a := authOf(r)
	var in struct {
		Current string `json:"current"`
		New     string `json:"new"`
	}
	if !readJSON(w, r, &in) {
		return
	}
	if !s.verifyOwnPassword(w, r, a.u, in.Current) {
		return
	}
	if err := checkPassword(in.New, a.u.Username); err != nil {
		jsonError(w, http.StatusBadRequest, err.Error())
		return
	}
	if in.New == in.Current {
		jsonError(w, http.StatusBadRequest, "Choose a different password from the current one.")
		return
	}
	hash, err := s.hashPassword(in.New)
	if err != nil {
		jsonError(w, http.StatusServiceUnavailable, "Busy right now. Try again in a moment.")
		return
	}
	token, exp, err := s.changePassword(r.Context(), a, hash, s.clientIP(r), r.UserAgent())
	if errors.Is(err, errStaleAuthorization) {
		jsonError(w, 409, "Your account or session changed. Sign in again.")
		return
	}
	if err != nil {
		serverError(w, r, err)
		return
	}
	s.userLimit.reset(a.u.Username)
	s.audit(r.Context(), a.u.Username, "password_changed", a.u.Username, "all old sessions replaced", s.clientIP(r))
	s.setSessionCookie(w, token, exp)
	w.WriteHeader(http.StatusNoContent)
}

type sessionOut struct {
	ID         string `json:"id"`
	CreatedAt  int64  `json:"created_at"`
	LastSeenAt int64  `json:"last_seen_at"`
	IP         string `json:"ip"`
	UserAgent  string `json:"user_agent"`
	Current    bool   `json:"current"`
}

func (s *server) listSessions(w http.ResponseWriter, r *http.Request) {
	a := authOf(r)
	rows, err := s.db.QueryContext(r.Context(), `SELECT sid, created_at, last_seen_at, ip, user_agent FROM sessions
		WHERE user_id = ? AND expires_at > ? ORDER BY last_seen_at DESC`, a.u.ID, time.Now().Unix())
	if err != nil {
		serverError(w, r, err)
		return
	}
	defer rows.Close()
	out := []sessionOut{}
	for rows.Next() {
		var so sessionOut
		if err := rows.Scan(&so.ID, &so.CreatedAt, &so.LastSeenAt, &so.IP, &so.UserAgent); err != nil {
			serverError(w, r, err)
			return
		}
		so.Current = so.ID == a.sid
		out = append(out, so)
	}
	if err := rows.Err(); err != nil {
		serverError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, out)
}

// revokeSession signs out one of the caller's own sessions (never someone else's).
func (s *server) revokeSession(w http.ResponseWriter, r *http.Request) {
	a := authOf(r)
	sid := r.PathValue("sid")
	res, err := s.db.ExecContext(r.Context(), "DELETE FROM sessions WHERE user_id = ? AND sid = ?", a.u.ID, sid)
	if err != nil {
		serverError(w, r, err)
		return
	}
	if sid == a.sid {
		s.clearSessionCookie(w)
	}
	if n, _ := res.RowsAffected(); n > 0 { // revoking what isn't there changes nothing, so it isn't an event
		s.audit(r.Context(), a.u.Username, "session_revoked", a.u.Username, "", s.clientIP(r))
	}
	w.WriteHeader(http.StatusNoContent)
}

func (s *server) revokeOtherSessions(w http.ResponseWriter, r *http.Request) {
	a := authOf(r)
	n, err := s.revokeSessions(r.Context(), a.u.ID, a.sid)
	if err != nil {
		serverError(w, r, err)
		return
	}
	if n > 0 {
		s.audit(r.Context(), a.u.Username, "sessions_revoked", a.u.Username, "other devices", s.clientIP(r))
	}
	writeJSON(w, http.StatusOK, map[string]int64{"revoked": n})
}

func (s *server) revokeAllSessions(w http.ResponseWriter, r *http.Request) {
	a := authOf(r)
	n, err := s.revokeSessions(r.Context(), a.u.ID, "")
	if err != nil {
		serverError(w, r, err)
		return
	}
	s.clearSessionCookie(w)
	if n > 0 {
		s.audit(r.Context(), a.u.Username, "sessions_revoked", a.u.Username, "everywhere", s.clientIP(r))
	}
	writeJSON(w, http.StatusOK, map[string]int64{"revoked": n})
}

// deleteSelf removes the caller's account and every doc in it.
func (s *server) deleteSelf(w http.ResponseWriter, r *http.Request) {
	a := authOf(r)
	var in struct {
		Password string `json:"password"`
	}
	if !readJSON(w, r, &in) {
		return
	}
	if !s.verifyOwnPassword(w, r, a.u, in.Password) {
		return
	}
	if err := s.deleteUser(r.Context(), a.u.ID); err != nil {
		if errors.Is(err, errLastAdmin) {
			jsonError(w, http.StatusConflict, "You're the only admin. Make someone else an admin first.")
			return
		}
		serverError(w, r, err)
		return
	}
	s.audit(r.Context(), a.u.Username, "account_deleted", a.u.Username, "by the account holder", s.clientIP(r))
	s.clearSessionCookie(w)
	w.WriteHeader(http.StatusNoContent)
}

package main

import (
	"strings"
	"testing"
)

func TestSessionListAndRevoke(t *testing.T) {
	e := newTestServer(t)
	phone, pw := e.addUser("alice", roleUser)
	laptop := e.newClient()
	laptop.login("alice", pw, "User-Agent", "Mozilla/5.0 (X11; Linux)\tFirefox/130.0\tinjected")

	var list []sessionOut
	laptop.getJSON("/api/me/sessions", &list)
	if len(list) != 2 {
		t.Fatalf("sessions = %+v", list)
	}
	var cur, other sessionOut
	for _, s := range list {
		if s.Current {
			cur = s
		} else {
			other = s
		}
	}
	if cur.ID == "" || other.ID == "" || cur.ID == other.ID || len(cur.ID) != 16 {
		t.Fatalf("current %+v other %+v", cur, other)
	}
	if cur.UserAgent != "Mozilla/5.0 (X11; Linux)Firefox/130.0injected" {
		t.Errorf("user agent = %q (control characters must be stripped)", cur.UserAgent)
	}
	if cur.IP != "127.0.0.1" || cur.CreatedAt == 0 || cur.LastSeenAt == 0 {
		t.Errorf("current = %+v", cur)
	}
	if strings.Contains(strings.ToLower(laptop.mustBody("GET", "/api/me/sessions")), "token") {
		t.Error("the session list must not expose token material")
	}

	// Sign out the phone from the laptop.
	if st := laptop.do("DELETE", "/api/me/sessions/"+other.ID, nil); st != 204 {
		t.Errorf("revoke = %d", st)
	}
	if st := phone.do("GET", "/api/me", nil); st != 401 {
		t.Errorf("revoked session still works: %d", st)
	}
	if st := laptop.do("GET", "/api/me", nil); st != 200 {
		t.Errorf("the revoking session was signed out too: %d", st)
	}
}

func TestSignOutOtherDevicesAndEverywhere(t *testing.T) {
	e := newTestServer(t)
	a, pw := e.addUser("alice", roleUser)
	b, c := e.newClient(), e.newClient()
	b.mustLogin("alice", pw)
	c.mustLogin("alice", pw)

	resp, body := a.req("POST", "/api/me/sessions/revoke-others", nil)
	if resp.StatusCode != 200 || !strings.Contains(string(body), `"revoked":2`) {
		t.Fatalf("revoke-others = %d %s", resp.StatusCode, body)
	}
	if a.do("GET", "/api/me", nil) != 200 || b.do("GET", "/api/me", nil) != 401 || c.do("GET", "/api/me", nil) != 401 {
		t.Error("revoke-others should keep only the caller")
	}

	resp, _ = a.req("POST", "/api/me/sessions/revoke-all", nil)
	if resp.StatusCode != 200 {
		t.Fatalf("revoke-all = %d", resp.StatusCode)
	}
	cleared := false
	for _, ck := range resp.Cookies() {
		if ck.Name == cookieName && ck.MaxAge < 0 {
			cleared = true
		}
	}
	if !cleared {
		t.Error("revoke-all should clear the cookie")
	}
	if st := a.do("GET", "/api/me", nil); st != 401 {
		t.Errorf("after revoke-all: %d", st)
	}
	if loc := e.newClient().login("alice", pw); loc != "/" {
		t.Error("revoking sessions must not stop signing in again")
	}
}

func TestRevokingYourOwnCurrentSession(t *testing.T) {
	e := newTestServer(t)
	a, _ := e.addUser("alice", roleUser)
	var list []sessionOut
	a.getJSON("/api/me/sessions", &list)
	resp, _ := a.req("DELETE", "/api/me/sessions/"+list[0].ID, nil)
	if resp.StatusCode != 204 {
		t.Fatalf("= %d", resp.StatusCode)
	}
	if st := a.do("GET", "/api/me", nil); st != 401 {
		t.Errorf("= %d, want 401", st)
	}
}

func TestDeleteOwnAccount(t *testing.T) {
	e := newTestServer(t)
	alice, pw := e.addUser("alice", roleUser)
	alice.putDoc("d-2026-10-01", `{"status":"red"}`)
	bob, _ := e.addUser("bob", roleUser)
	bob.putDoc("d-2026-10-01", `{"status":"green"}`)

	if st := alice.do("DELETE", "/api/me", map[string]string{"password": "not-my-password"}); st != 403 {
		t.Errorf("wrong password = %d, want 403", st)
	}
	if st := alice.do("DELETE", "/api/me", map[string]string{}); st != 403 {
		t.Errorf("no password = %d, want 403", st)
	}
	if st := alice.do("GET", "/api/me", nil); st != 200 {
		t.Fatal("a refused delete must leave the account alone")
	}
	resp, _ := alice.req("DELETE", "/api/me", map[string]string{"password": pw})
	if resp.StatusCode != 204 {
		t.Fatalf("delete = %d", resp.StatusCode)
	}
	if n := countRows(t, e, "SELECT count(*) FROM users WHERE username = 'alice'"); n != 0 {
		t.Error("account still exists")
	}
	if n := countRows(t, e, "SELECT count(*) FROM docs WHERE user_id NOT IN (SELECT id FROM users)"); n != 0 {
		t.Error("orphaned docs")
	}
	if loc := e.newClient().login("alice", pw); loc != "/login?e=bad" {
		t.Errorf("a deleted account can sign in: %q", loc)
	}
	if got := bob.docs(); len(got) != 1 {
		t.Errorf("bob's data changed: %v", got)
	}
	if n := countRows(t, e, "SELECT count(*) FROM audit_log WHERE action = 'account_deleted' AND actor = 'alice'"); n != 1 {
		t.Error("self-deletion is not audited")
	}
}

