	if st := c.do("POST", "/logout", nil); st >= 400 {
		t.Fatalf("logout = %d", st)
	}
	c.hc.Jar.SetCookies(u, saved)
	if st := c.do("GET", "/api/me", nil); st != 401 {
		t.Fatalf("revoked cookie = %d, want 401", st)
