	re := regexp.MustCompile(`^[a-zA-Z2-9]{4}(-[a-zA-Z2-9]{4}){3}$`)
	seen := map[string]bool{}
	for i := 0; i < 200; i++ {
		pw, err := tempPassword()
		if err != nil {
			t.Fatal(err)
		}
		if !re.MatchString(pw) || strings.ContainsAny(pw, "0O1lI") {
			t.Fatalf("%q is not in the expected format", pw)
		}
		if err := checkPassword(pw, "someone"); err != nil {
			t.Fatalf("a temporary password must satisfy our own policy: %v", err)
		}
		if seen[pw] {
			t.Fatalf("%q repeated", pw)
		}
		seen[pw] = true
	}
}

func TestLimiter(t *testing.T) {
	l := newLoginLimiter(3, 40*time.Millisecond)
	for i := 0; i < 3; i++ {
		if _, ok := l.take("k"); !ok {
			t.Fatalf("blocked after %d attempts", i)
		}
	}
	if _, ok := l.take("k"); ok {
		t.Error("should block at the limit")
	}
	if _, ok := l.take("other"); !ok {
		t.Error("keys are independent")
	}
	l.reset("k")
	if _, ok := l.take("k"); !ok {
		t.Error("reset should clear")
	}
	for i := 0; i < 2; i++ {
		l.take("k")
	}
	time.Sleep(60 * time.Millisecond)
	if _, ok := l.take("k"); !ok {
		t.Error("attempts should age out of the window")
	}
	l.take("stale")
	time.Sleep(60 * time.Millisecond)
	l.sweep()
	l.mu.Lock()
	n := len(l.fails)
	l.mu.Unlock()
	if n != 0 {
		t.Errorf("sweep left %d aged-out keys", n)
	}
}

func TestLimiterGivesBackOnlyTheAttemptItWasHanded(t *testing.T) {
	l := newLoginLimiter(3, time.Hour)
	_, _ = l.take("k")
	back, _ := l.take("k")
	_, _ = l.take("k")
	if _, ok := l.take("k"); ok {
		t.Fatal("three attempts are taken")
	}
	back()
	back() // giving the same one back twice must not free a second slot
	if _, ok := l.take("k"); !ok {
		t.Error("the slot that was given back should be usable")
	}
	if _, ok := l.take("k"); ok {
		t.Error("only one slot was given back")
	}
	l.mu.Lock()
	n := len(l.fails["k"])
	l.mu.Unlock()
	if n != 3 {
		t.Errorf("%d attempts recorded, want 3", n)
	}
}

func TestLimiterStopsGrowingWhenFull(t *testing.T) {
	l := newLoginLimiter(3, time.Hour)
	for i := 0; i < limiterMaxKeys; i++ {
		l.take(fmt.Sprint("k", i))
	}
	if _, ok := l.take("one-too-many"); !ok {
		t.Error("a newcomer is let through untracked, not refused")
	}
	l.mu.Lock()
	n, tracked := len(l.fails), l.fails["one-too-many"] != nil
	l.mu.Unlock()
	if n != limiterMaxKeys || tracked {
		t.Errorf("limiter grew to %d keys (new key tracked: %v)", n, tracked)
	}
	l.take("k0") // an existing key still counts
	l.mu.Lock()
	got := len(l.fails["k0"])
	l.mu.Unlock()
	if got != 2 {
		t.Errorf("existing key has %d attempts, want 2", got)
	}
}

// createViaAPI has an admin create an account and returns its temporary password.
func createViaAPI(t *testing.T, admin *client, name, role string) string {
	t.Helper()
	resp, b := admin.req("POST", "/api/admin/users", map[string]string{"username": name, "role": role})
	if resp.StatusCode != 201 {
		t.Fatalf("create %s: %d %s", name, resp.StatusCode, b)
	}
	var out struct {
		TempPassword string `json:"temp_password"`
	}
	if err := json.Unmarshal(b, &out); err != nil || out.TempPassword == "" {
		t.Fatalf("create %s: %s", name, b)
	}
	return out.TempPassword
}

// A limiter that is full of live keys lets a new key through untracked rather than grow without bound: refusing
// it would hand an attacker a way to lock everyone out by spraying names.
func TestALimiterFullOfLiveKeysLetsNewOnesThrough(t *testing.T) {
	l := newLoginLimiter(1, time.Hour)
	for i := 0; i < limiterMaxKeys; i++ {
		if _, ok := l.take(strconv.Itoa(i)); !ok {
			t.Fatalf("key %d was refused before the map was full", i)
		}
	}
	give, ok := l.take("one-more")
	if !ok {
		t.Fatal("a new key was refused while the limiter was full of live entries")
	}
	give()
	l.mu.Lock()
	_, recorded := l.fails["one-more"]
	l.mu.Unlock()
	if recorded {
		t.Fatal("an untracked attempt was recorded")
	}
}

