func TestCLIRestore(t *testing.T) {
	// A database with some history, backed up; then more happens; then it is restored.
	e := newTestServer(t)
	admin := e.signedInAdmin()
	admin.putDoc("d-2026-10-01", `{"status":"green"}`)
	t.Setenv("APP_DB", e.dbPath)
	good := filepath.Join(t.TempDir(), "good.db")
	if _, _, _, err := cli(t, "", "backup", good); err != nil {
		t.Fatal(err)
	}
	admin.putDoc("d-2026-10-02", `{"status":"red"}`)
	e.ts.Close()
	e.s.db.Close() // the server is stopped, as the command requires

	if _, _, _, err := cli(t, "", "restore", good); err == nil || !strings.Contains(err.Error(), "--yes") {
		t.Errorf("without --yes: %v (it must say what it would do and not do it)", err)
	}
	if got := scalar(t, e.dbPath, "SELECT count(*) FROM docs"); got != 2 {
		t.Fatalf("a refused restore changed the database: %d docs", got)
	}
	// Leftover WAL/SHM files from the old database must not be applied to the restored one.
	os.WriteFile(e.dbPath+"-wal", []byte("stale"), 0o600)
	os.WriteFile(e.dbPath+"-shm", []byte("stale"), 0o600)

	out, errOut, _, err := cli(t, "", "restore", good, "--yes")
	if err != nil || !strings.Contains(out, "Restored") || !strings.Contains(errOut, "pre-restore-") {
		t.Fatalf("restore: %q %q %v", out, errOut, err)
	}
	if got := scalar(t, e.dbPath, "SELECT count(*) FROM docs"); got != 1 {
		t.Errorf("restored database has %d docs, want the backup's 1", got)
	}
	for _, f := range []string{e.dbPath + "-wal", e.dbPath + "-shm", e.dbPath + ".restoring"} {
		if _, err := os.Stat(f); !os.IsNotExist(err) {
			t.Errorf("%s should be gone", f)
		}
	}
	kept, _ := filepath.Glob(filepath.Join(backupDir(e.dbPath), "pre-restore-*.db"))
	if len(kept) != 1 || scalar(t, kept[0], "SELECT count(*) FROM docs") != 2 {
		t.Errorf("the replaced database should be kept intact: %v", kept)
	}
	// And the restored database is the real thing: it opens, and the admin can sign in.
	db, err := openDB(e.dbPath, nil)
	if err != nil {
		t.Fatal(err)
	}
	s, _ := newServer(config{}, db)
	defer db.Close()
	if u, err := s.userByName(t.Context(), adminName); err != nil || u.Role != roleAdmin {
		t.Errorf("admin after restore: %+v %v", u, err)
	}
}

func TestCLIRestoreRefusesBadFiles(t *testing.T) {
	e := newTestServer(t)
	t.Setenv("APP_DB", e.dbPath)
	dir := t.TempDir()
	write := func(name string, data []byte) string {
		p := filepath.Join(dir, name)
		if err := os.WriteFile(p, data, 0o600); err != nil {
			t.Fatal(err)
		}
		return p
	}
	newer := filepath.Join(dir, "newer.db")
	if err := snapshot(e.s.db, newer); err != nil {
		t.Fatal(err)
	}
	if db, _ := openRaw(newer); db != nil {
		db.Exec("PRAGMA user_version = 99")
		db.Close()
	}
	other := filepath.Join(dir, "other.db") // a real SQLite file that isn't ours
	if db, _ := openRaw(other); db != nil {
		db.Exec("CREATE TABLE notes(x)")
		db.Close()
	}
	before := scalar(t, e.dbPath, "SELECT count(*) FROM users")
	for name, c := range map[string]struct{ path, want string }{
		"missing":                 {filepath.Join(dir, "nope.db"), "can't read"},
		"not a database":          {write("junk.db", []byte("this is not sqlite at all, just text that is long enough to look like a file")), "isn't a Jiggered database"},
		"empty file":              {write("empty.db", nil), "isn't a Jiggered database"},
		"from a newer Jiggered":   {newer, "newer Jiggered"},
		"someone else's database": {other, "no docs table"},
	} {
		_, _, _, err := cli(t, "", "restore", c.path, "--yes")
		if err == nil || !strings.Contains(err.Error(), c.want) {
			t.Errorf("%s: %v, want it to mention %q", name, err, c.want)
		}
	}
	if got := scalar(t, e.dbPath, "SELECT count(*) FROM users"); got != before {
		t.Error("a refused restore must leave the database alone")
	}
	if kept, _ := filepath.Glob(filepath.Join(backupDir(e.dbPath), "pre-restore-*.db")); len(kept) != 0 {
		t.Errorf("nothing was replaced, so nothing should have been set aside: %v", kept)
	}
	for _, args := range [][]string{{"restore"}, {"restore", "a", "b", "c"}, {"restore", "a", "--force"}} {
		if _, _, _, err := cli(t, "", args...); err == nil || !strings.Contains(err.Error(), "usage") {
			t.Errorf("%v: %v, want a usage message", args, err)
		}
	}
	// The user's own file is untouched by validation: no -wal/-shm beside it, same bytes.
	if _, err := os.Stat(newer + "-wal"); !os.IsNotExist(err) {
		t.Error("checking a backup must not create files next to it")
	}
}

package main

import (
	"bytes"
	"compress/gzip"
	"crypto/sha256"
	"encoding/hex"
	"mime"
	"net/http"
	"path"
	"strconv"
	"strings"
	"sync"
)

// Public text (scripts, styles, pages) is compressed once and served compressed to browsers that accept it. Nothing
// private is: API responses and anything built from a person's data stay as they are, because compressing a response
// that mixes secrets with text an attacker can influence can leak the secret through its size. Fonts and images are
// already compressed and are left alone.

// acceptsGzip reports whether the request's Accept-Encoding allows gzip (an explicit q=0 refuses it).
func acceptsGzip(r *http.Request) bool {
	for _, part := range strings.Split(strings.Join(r.Header.Values("Accept-Encoding"), ","), ",") {
		name, params, _ := strings.Cut(strings.TrimSpace(part), ";")
		if !strings.EqualFold(strings.TrimSpace(name), "gzip") {
			continue
		}
		if q, ok := strings.CutPrefix(strings.ReplaceAll(strings.ToLower(params), " ", ""), "q="); ok {
			if v, err := strconv.ParseFloat(q, 64); err == nil && v <= 0 {
				return false
			}
		}
		return true
	}
	return false
}

// compressibleFile says whether a static file is text worth compressing.
func compressibleFile(name string) bool {
	switch strings.ToLower(path.Ext(name)) {
	case ".js", ".css", ".html", ".json", ".svg", ".webmanifest":
		return true
	}
	return false
}

// gzipCache keeps each compressed body, keyed by what it was made from, for the life of the process. Public files
// are few and small, so this is a fixed, tiny amount of memory and the work happens once per file.
type gzipCache struct{ m sync.Map }

func (c *gzipCache) get(key string, raw func() ([]byte, error)) []byte {
	if v, ok := c.m.Load(key); ok {
		return v.([]byte)
	}
	b, err := raw()
	if err != nil {
		return nil
	}
	var buf bytes.Buffer
	zw, _ := gzip.NewWriterLevel(&buf, gzip.BestCompression)
	zw.Write(b)
	if zw.Close() != nil || buf.Len() >= len(b) { // not worth sending
		c.m.Store(key, []byte(nil))
		return nil
	}
	c.m.Store(key, buf.Bytes())
	return buf.Bytes()
}

// serveCompressed writes body in gzip form with its own validator, and answers a matching If-None-Match with 304.
// etag is the identity representation's tag; the compressed one is a different representation and gets a different tag.
func serveCompressed(w http.ResponseWriter, r *http.Request, contentType, etag string, body []byte) {
	h := w.Header()
	h.Set("Content-Type", contentType)
	h.Set("Content-Encoding", "gzip")
	if etag != "" {
		tag := strings.TrimSuffix(etag, `"`) + `-gzip"`
		h.Set("ETag", tag)
		if inm := r.Header.Get("If-None-Match"); inm != "" && tagMatches(inm, tag) {
			w.WriteHeader(http.StatusNotModified)
			return
		}
	}
	h.Set("Content-Length", strconv.Itoa(len(body)))
	if r.Method == http.MethodHead {
		return
	}
	w.Write(body)
}

func contentTypeOf(name string) string {
	if strings.HasSuffix(name, ".webmanifest") {
		return "application/manifest+json"
	}
	if t := mime.TypeByExtension(path.Ext(name)); t != "" {
		return t
	}
	return "application/octet-stream"
}

// pageTag is a strong tag for a generated page, derived from its exact bytes.
func pageTag(page []byte) string {
	sum := sha256.Sum256(page)
	return `"` + hex.EncodeToString(sum[:8]) + `"`
}

package main

import (
	"bytes"
	"compress/gzip"
	"io"
	"net/http"
	"regexp"
	"strings"
	"testing"
)

func gunzip(t *testing.T, b []byte) []byte {
	t.Helper()
	zr, err := gzip.NewReader(bytes.NewReader(b))
	if err != nil {
		t.Fatalf("not gzip: %v", err)
	}
	out, err := io.ReadAll(zr)
	if err != nil {
		t.Fatal(err)
	}
	return out
}

func versionOf(t *testing.T, e *testEnv) string {
	t.Helper()
	m := regexp.MustCompile(`/v/([0-9a-f]{12})/style\.css`).FindStringSubmatch(e.newClient().mustBody("GET", "/login"))
	if m == nil {
		t.Fatal("no versioned stylesheet on the login page")
	}
	return m[1]
}

func TestPublicTextIsCompressedForBrowsersThatAcceptIt(t *testing.T) {
	e := newTestServer(t)
	anon, signedIn := e.newClient(), e.signedInAdmin()
	ver := versionOf(t, e)
	for _, file := range []string{"/style.css", "/login.js", "/early-nav.js", "/app.js", "/model.js"} {
		anon := anon
		if file != "/style.css" && file != "/login.js" {
			anon = signedIn // the rest of the app sits behind sign-in
		}
		path := "/v/" + ver + file
		plainResp, plain := anon.req("GET", path, nil, "Accept-Encoding", "identity")
		if plainResp.StatusCode != 200 || plainResp.Header.Get("Content-Encoding") != "" {
			t.Fatalf("%s identity = %d %q", file, plainResp.StatusCode, plainResp.Header.Get("Content-Encoding"))
		}
		resp, body := anon.req("GET", path, nil, "Accept-Encoding", "gzip, deflate, br")
		if resp.StatusCode != 200 || resp.Header.Get("Content-Encoding") != "gzip" {
			t.Fatalf("%s gzip = %d %q", file, resp.StatusCode, resp.Header.Get("Content-Encoding"))
		}
		if !bytes.Equal(gunzip(t, body), plain) {
			t.Errorf("%s: the compressed body does not decode to the plain one", file)
		}
		if len(body) >= len(plain) {
			t.Errorf("%s: compressed %d bytes is not smaller than %d", file, len(body), len(plain))
		}
		if resp.Header.Get("Content-Length") == "" || resp.Header.Get("Vary") == "" || !strings.Contains(resp.Header.Get("Vary"), "Accept-Encoding") {
			t.Errorf("%s: headers = %v, want Content-Length and Vary: Accept-Encoding", file, resp.Header)
		}
		if plainResp.Header.Get("Vary") == "" || !strings.Contains(plainResp.Header.Get("Vary"), "Accept-Encoding") {
			t.Errorf("%s: the plain answer must also say Vary: Accept-Encoding, or a cache could mix the two", file)
		}
		if ct := resp.Header.Get("Content-Type"); ct != plainResp.Header.Get("Content-Type") {
			t.Errorf("%s: type %q differs from the plain answer's %q", file, ct, plainResp.Header.Get("Content-Type"))
		}
		if resp.Header.Get("Cache-Control") != plainResp.Header.Get("Cache-Control") {
			t.Errorf("%s: cache rules changed with compression", file)
		}
	}
}

func TestCompressedRepresentationHasItsOwnTagAndRevalidates(t *testing.T) {
	e := newTestServer(t)
	anon := e.newClient()
	path := "/v/" + versionOf(t, e) + "/style.css"
	plain, _ := anon.req("GET", path, nil, "Accept-Encoding", "identity")
	gz, _ := anon.req("GET", path, nil, "Accept-Encoding", "gzip")
	if gz.Header.Get("ETag") == "" || gz.Header.Get("ETag") == plain.Header.Get("ETag") {
		t.Fatalf("the two representations share a tag: %q and %q", plain.Header.Get("ETag"), gz.Header.Get("ETag"))
	}
	if resp, body := anon.req("GET", path, nil, "Accept-Encoding", "gzip", "If-None-Match", gz.Header.Get("ETag")); resp.StatusCode != 304 || len(body) != 0 {
		t.Errorf("its own tag = %d with %d bytes, want 304", resp.StatusCode, len(body))
	}
	if resp, _ := anon.req("GET", path, nil, "Accept-Encoding", "gzip", "If-None-Match", plain.Header.Get("ETag")); resp.StatusCode != 200 {
		t.Errorf("the plain tag against the compressed form = %d, want 200 (a different representation)", resp.StatusCode)
	}
	if resp, _ := anon.req("GET", path, nil, "Accept-Encoding", "identity", "If-None-Match", plain.Header.Get("ETag")); resp.StatusCode != 304 {
		t.Errorf("the plain tag against the plain form = %d, want 304", resp.StatusCode)
	}
	if resp, body := anon.req("HEAD", path, nil, "Accept-Encoding", "gzip"); resp.StatusCode != 200 || len(body) != 0 || resp.Header.Get("Content-Encoding") != "gzip" {
		t.Errorf("HEAD = %d, %d body bytes, encoding %q", resp.StatusCode, len(body), resp.Header.Get("Content-Encoding"))
	}
}

func TestGeneratedPagesAreCompressedToo(t *testing.T) {
	e := newTestServer(t)
	for _, page := range []string{"/login", "/"} {
		c := e.newClient()
		if page == "/" {
			c = e.signedInAdmin()
		}
		_, plain := c.req("GET", page, nil, "Accept-Encoding", "identity")
		resp, body := c.req("GET", page, nil, "Accept-Encoding", "gzip")
		if resp.Header.Get("Content-Encoding") != "gzip" || !bytes.Equal(gunzip(t, body), plain) || len(body) >= len(plain) {
			t.Errorf("%s: encoding %q, decodes equal: %v, %d vs %d bytes", page, resp.Header.Get("Content-Encoding"), bytes.Equal(gunzip(t, body), plain), len(body), len(plain))
		}
		if resp.Header.Get("Cache-Control") != "no-store" || !strings.Contains(resp.Header.Get("Vary"), "Accept-Encoding") {
			t.Errorf("%s: headers = %v", page, resp.Header)
		}
	}
}

func TestCompressionIsOnlyForPublicTextAndOnlyWhenAsked(t *testing.T) {
	e := newTestServer(t)
	anon := e.newClient()
	ver := versionOf(t, e)
	for _, ae := range []string{"", "identity", "gzip;q=0", "gzip; q=0.0", "br, deflate"} {
		resp, _ := anon.req("GET", "/v/"+ver+"/style.css", nil, "Accept-Encoding", ae)
		if resp.Header.Get("Content-Encoding") != "" {
			t.Errorf("Accept-Encoding %q still got %q", ae, resp.Header.Get("Content-Encoding"))
		}
	}
	if resp, _ := anon.req("GET", "/v/"+ver+"/style.css", nil, "Accept-Encoding", "deflate, gzip;q=0.5"); resp.Header.Get("Content-Encoding") != "gzip" {
		t.Error("gzip with a lower but non-zero q should be used")
	}
	// Fonts are already compressed.
	if resp, _ := anon.req("GET", "/fonts/atkinson-400-latin-ext.woff2", nil, "Accept-Encoding", "gzip"); resp.StatusCode != 200 || resp.Header.Get("Content-Encoding") != "" {
		t.Errorf("font = %d, encoding %q", resp.StatusCode, resp.Header.Get("Content-Encoding"))
	}
	// Nothing a person's data goes into is compressed: API answers and the database download stay as they are.
	c := e.signedInAdmin()
	c.putDoc("d-2026-10-01", `{"status":"green"}`)
	for _, p := range []string{"/api/docs", "/api/me", "/api/export"} {
		if resp, _ := c.req("GET", p, nil, "Accept-Encoding", "gzip"); resp.Header.Get("Content-Encoding") != "" {
			t.Errorf("%s was compressed (%q)", p, resp.Header.Get("Content-Encoding"))
		}
	}
	if resp, _ := c.req("POST", "/api/admin/backup", map[string]any{"password": adminPass}, "Accept-Encoding", "gzip"); resp.Header.Get("Content-Encoding") != "" {
		t.Error("the backup download was compressed")
	}
}

func TestAcceptsGzip(t *testing.T) {
	for header, want := range map[string]bool{
		"": false, "gzip": true, "GZIP": true, "gzip, deflate, br": true, "br;q=1.0, gzip;q=0.8": true,
		"gzip;q=0": false, "gzip; q=0.0": false, "identity": false, "gzipped": false, "x-gzip": false,
	} {
		r, _ := newGet(header)
		if got := acceptsGzip(r); got != want {
			t.Errorf("acceptsGzip(%q) = %v, want %v", header, got, want)
		}
	}
}

func newGet(acceptEncoding string) (*http.Request, error) {
	r, err := http.NewRequest("GET", "/", nil)
	if acceptEncoding != "" {
		r.Header.Set("Accept-Encoding", acceptEncoding)
	}
	return r, err
}

package main

import (
	"database/sql"
	"errors"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// seedAdmin is the account made from APP_USERNAME / APP_PASSWORD(_HASH). It is
// only used while the database has no accounts, and it adopts any data that
// predates accounts.
type seedAdmin struct{ name, hash string }

var errNeedFirstAdmin = errors.New("this database holds data from before Jiggered had accounts; set APP_USERNAME and APP_PASSWORD_HASH (or APP_PASSWORD) so that account can take it over")

// versionAccounts is the schema version that introduced accounts, and with them the need for a first admin.
const versionAccounts = 2

// temp_store(2) keeps SQLite's scratch space in memory: the shipped container has a read-only root and no /tmp, so
// a big upgrade (dropping a 20 MB table) otherwise fails with "unable to open database file". secure_delete(ON)
// overwrites deleted rows, so a deleted account's data doesn't linger in the file.
const dsnPragmas = "?_pragma=busy_timeout(5000)&_pragma=foreign_keys(ON)&_pragma=temp_store(2)&_pragma=secure_delete(ON)&_txlock=immediate"

// sqliteURI turns a file path into the file: URI SQLite wants. A path may hold %, ? and #, which would otherwise
// change which file is opened ("my#data.db" became "my").
func sqliteURI(path string) string {
	return "file:" + strings.NewReplacer("%", "%25", "?", "%3f", "#", "%23").Replace(path)
}

// openRaw opens the database without touching its schema.
func openRaw(path string) (*sql.DB, error) {
	// Everything in it is private. SQLite gives -wal and -shm the mode of the main file, so make that 0600 first.
	if f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o600); err == nil {
		f.Close()
		os.Chmod(path, 0o600)
	}
	db, err := sql.Open("sqlite", sqliteURI(path)+dsnPragmas)
	if err != nil {
		return nil, err
	}
	db.SetMaxOpenConns(1)
	if err := enableWAL(db); err != nil {
		db.Close()
		return nil, err
	}
	return db, nil
}

func enableWAL(db *sql.DB) error {
	deadline := time.Now().Add(5 * time.Second)
	for {
		var mode string
		err := db.QueryRow("PRAGMA journal_mode=WAL").Scan(&mode)
		if err == nil {
			if mode != "wal" {
				return fmt.Errorf("enabling WAL mode: SQLite selected %q", mode)
			}
			return nil
		}
		var sqliteErr interface{ Code() int }
		if !errors.As(err, &sqliteErr) || sqliteErr.Code() != 5 || !time.Now().Before(deadline) {
			return fmt.Errorf("enabling WAL mode: %w", err)
		}
		time.Sleep(25 * time.Millisecond)
	}
}

// openDB opens the database and brings its schema up to date.
func openDB(path string, first *seedAdmin) (*sql.DB, error) {
	db, err := openRaw(path)
	if err != nil {
		return nil, err
	}
	if err := migrate(db, path, first); err != nil {
		db.Close()
		return nil, err
	}
	return db, nil
}

// migrations run in order, each in its own transaction. Never edit one that
// has shipped; append a new one.
var migrations = []func(tx *sql.Tx, first *seedAdmin) error{migrateBaseline, migrateAccounts, migrateSettings, migrateDocRevs, migrateSecurityAccounts, migrateProductImprovements}

func migrate(db *sql.DB, path string, first *seedAdmin) error {
	var cur int
	if err := db.QueryRow("PRAGMA user_version").Scan(&cur); err != nil {
		return err
	}
	if cur > len(migrations) {
		return fmt.Errorf("database schema is v%d but this build only knows up to v%d; refusing to open it (run a newer Jiggered)", cur, len(migrations))
	}
	if cur == len(migrations) {
		return nil
	}
	// A database from before accounts needs someone to take it over. Say so before taking a snapshot: nothing
	// changes when this is refused, and a container that restarts on a missing APP_USERNAME would otherwise
	// leave a full copy of the database behind on every try.
	if cur < versionAccounts && first == nil {
		n, err := legacyDocs(db)
		if err != nil {
			return err
		}
		if n > 0 {
			return fmt.Errorf("upgrading database to schema v%d: %w", versionAccounts, errNeedFirstAdmin)
		}
	}
	if err := snapshotBeforeMigrating(db, path, cur); err != nil {
		return err
	}
	for v := cur; v < len(migrations); v++ {
		tx, err := db.Begin()
		if err != nil {
			return err
		}
		// Another process (the CLI, say) may have migrated while we waited for the lock.
		var now int
		if err := tx.QueryRow("PRAGMA user_version").Scan(&now); err != nil || now > v {
			tx.Rollback()
			if err != nil {
				return err
			}
			continue
		}
		if err := migrations[v](tx, first); err != nil {
			tx.Rollback()
			return fmt.Errorf("upgrading database to schema v%d: %w", v+1, err)
		}
		if _, err := tx.Exec(fmt.Sprintf("PRAGMA user_version = %d", v+1)); err != nil {
			tx.Rollback()
			return err
		}
		if err := tx.Commit(); err != nil {
			return err
		}
	}
	return nil
}

// legacyDocs counts the docs in a database from before accounts existed: zero if it holds none, or isn't one.
func legacyDocs(db *sql.DB) (int, error) {
	var tables int
	if err := db.QueryRow("SELECT count(*) FROM sqlite_master WHERE type = 'table' AND name = 'docs'").Scan(&tables); err != nil || tables == 0 {
		return 0, err
	}
	var n int
	err := db.QueryRow("SELECT count(*) FROM docs").Scan(&n)
	return n, err
}

// snapshotBeforeMigrating keeps a copy of any existing database before its
// schema changes, so a bad upgrade is never the only copy of someone's data.
func snapshotBeforeMigrating(db *sql.DB, path string, from int) error {
	var tables int
	if err := db.QueryRow("SELECT count(*) FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%'").Scan(&tables); err != nil {
		return err
	}
	if tables == 0 {
		return nil
	}
	dir := filepath.Join(filepath.Dir(path), "backups")
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return fmt.Errorf("creating backup directory: %w", err)
	}
	dest := filepath.Join(dir, fmt.Sprintf("pre-upgrade-v%d-%s.db", from, time.Now().Format("20060102-150405")))
	if err := snapshot(db, dest); err != nil {
		return fmt.Errorf("backing up before upgrade: %w", err)
	}
	log.Printf("saved a copy of the database to %s before upgrading its schema", dest)
	return nil
}

// snapshot writes a consistent copy of a live database. Copying the .db file
// alone is not enough in WAL mode: recent writes live in the -wal file.
func snapshot(db *sql.DB, dest string) error {
	if dest == "" || dest == ":memory:" || strings.HasPrefix(dest, "file:") {
		return fmt.Errorf("%q isn't a file name SQLite would write a file for", dest) // it would "succeed" and write nothing
	}
	if _, err := db.Exec("VACUUM INTO ?", dest); err != nil {
		os.Remove(dest) // a partial copy is worse than none
		return err
	}
	if st, err := os.Stat(dest); err != nil || st.Size() == 0 {
		return fmt.Errorf("the copy at %s wasn't written", dest)
	}
	return os.Chmod(dest, 0o600)
}

// v1: the original single-user schema.
func migrateBaseline(tx *sql.Tx, _ *seedAdmin) error {
	_, err := tx.Exec(`
CREATE TABLE IF NOT EXISTS docs (
  id         TEXT PRIMARY KEY,
  body       TEXT NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS sessions (
  token_hash TEXT PRIMARY KEY,
  expires_at INTEGER NOT NULL
);`)
	return err
}

const schemaAccounts = `
CREATE TABLE users (
  id                   INTEGER PRIMARY KEY AUTOINCREMENT,
  username             TEXT NOT NULL UNIQUE COLLATE NOCASE,
  password_hash        TEXT NOT NULL,
  role                 TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('admin', 'user')),
  disabled             INTEGER NOT NULL DEFAULT 0,
  must_change_password INTEGER NOT NULL DEFAULT 0,
  created_at           INTEGER NOT NULL,
  last_login_at        INTEGER
);
CREATE TABLE docs (
  user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  id         TEXT NOT NULL,
  body       TEXT NOT NULL,
  rev        INTEGER NOT NULL DEFAULT 1,
  size       INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  PRIMARY KEY (user_id, id)
);
CREATE TABLE sessions (
  token_hash   TEXT PRIMARY KEY,
  sid          TEXT NOT NULL UNIQUE,
  user_id      INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at   INTEGER NOT NULL,
  last_seen_at INTEGER NOT NULL,
  expires_at   INTEGER NOT NULL,
  ip           TEXT NOT NULL DEFAULT '',
  user_agent   TEXT NOT NULL DEFAULT ''
);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE audit_log (
  id     INTEGER PRIMARY KEY AUTOINCREMENT,
  at     INTEGER NOT NULL,
  actor  TEXT NOT NULL DEFAULT '',
  action TEXT NOT NULL,
  target TEXT NOT NULL DEFAULT '',
  detail TEXT NOT NULL DEFAULT '',
  ip     TEXT NOT NULL DEFAULT ''
);`

// v2: accounts. Docs and sessions gain an owner; whatever the single-user
// version stored is adopted by the first admin in the same transaction.
func migrateAccounts(tx *sql.Tx, first *seedAdmin) error {
	var docs, sessions int
	if err := tx.QueryRow("SELECT (SELECT count(*) FROM docs), (SELECT count(*) FROM sessions)").Scan(&docs, &sessions); err != nil {
		return err
	}
	if docs > 0 && first == nil {
		return errNeedFirstAdmin
	}
	for _, q := range []string{
		"ALTER TABLE docs RENAME TO docs_v0",
		"ALTER TABLE sessions RENAME TO sessions_v0",
		schemaAccounts,
	} {
		if _, err := tx.Exec(q); err != nil {
			return err
		}
	}
	if first != nil && (docs > 0 || sessions > 0) {
		now := time.Now().Unix()
		res, err := tx.Exec("INSERT INTO users(username, password_hash, role, created_at) VALUES(?, ?, 'admin', ?)", first.name, first.hash, now)
		if err != nil {
			return err
		}
		uid, err := res.LastInsertId()
		if err != nil {
			return err
		}
		if _, err := tx.Exec(`INSERT INTO docs(user_id, id, body, rev, size, updated_at)
			SELECT ?, id, body, 1, length(CAST(body AS BLOB)), updated_at FROM docs_v0`, uid); err != nil {
			return err
		}
		ttl := int64(sessionTTL / time.Second)
		if _, err := tx.Exec(`INSERT INTO sessions(token_hash, sid, user_id, created_at, last_seen_at, expires_at)
			SELECT token_hash, lower(hex(randomblob(8))), ?, expires_at - ?, expires_at - ?, expires_at FROM sessions_v0 WHERE expires_at > ?`,
			uid, ttl, ttl, now); err != nil {
			return err
		}
		if _, err := tx.Exec("INSERT INTO audit_log(at, actor, action, target, detail) VALUES(?, 'system', 'migrated', ?, ?)",
			now, first.name, fmt.Sprintf("%d existing docs adopted", docs)); err != nil {
			return err
		}
	}
	for _, q := range []string{"DROP TABLE docs_v0", "DROP TABLE sessions_v0"} {
		if _, err := tx.Exec(q); err != nil {
			return err
		}
	}
	return nil
}

// v3: instance settings (secure cookies, reverse proxy) move from the environment into the database.
func migrateSettings(tx *sql.Tx, _ *seedAdmin) error {
	_, err := tx.Exec(`CREATE TABLE instance_settings (
  key        TEXT PRIMARY KEY,
  value      TEXT NOT NULL,
  updated_at INTEGER NOT NULL
)`)
	return err
}

// v4: the last revision of a deleted document survives the delete, so recreating it carries on counting instead of
// starting again at 1, where a device still holding the old revision 1 could overwrite the replacement.
func migrateDocRevs(tx *sql.Tx, _ *seedAdmin) error {
	_, err := tx.Exec(`CREATE TABLE doc_revs (
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  id      TEXT NOT NULL,
  rev     INTEGER NOT NULL,
  PRIMARY KEY (user_id, id)
) WITHOUT ROWID`)
	return err
}

package main

import (
	"crypto/sha256"
	"database/sql"
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
	"time"
	"unicode/utf8"
)

type productDefaults struct {
	Budget       int `json:"budget"`
	SleepPenalty int `json:"sleepPenalty"`
	// Points an amber or red check-in takes off the day. Absent means the app's own defaults.
	AmberPenalty *int   `json:"amberPenalty,omitempty"`
	RedPenalty   *int   `json:"redPenalty,omitempty"`
	Locale       string `json:"locale"`
	Activities   []struct {
		ID string `json:"id,omitempty"`
		A  string `json:"a"`
		C  int    `json:"c"`
		G  string `json:"g,omitempty"`
	} `json:"activities"`
	Symptoms []string `json:"symptoms"`
	Triggers []string `json:"triggers"`
	// Optional group for a symptom or trigger, by name. Lists stay plain strings so every stored episode still matches.
	SymptomGroups map[string]string `json:"symptomGroups"`
	TriggerGroups map[string]string `json:"triggerGroups"`
}

// pruneGroups drops groups for names that are no longer in the list (renamed or removed), and never returns nil.
func pruneGroups(groups map[string]string, names []string) map[string]string {
	known := map[string]bool{}
	for _, n := range names {
		known[n] = true
	}
	out := map[string]string{}
	for name, g := range groups {
		if known[name] {
			out[name] = g
		}
	}
	return out
}

func validGroups(groups map[string]string, names []string) error {
	known := map[string]bool{}
	for _, n := range names {
		known[n] = true
	}
	for name, g := range groups {
		if !known[name] {
			return fmt.Errorf("A group was set for %q, which is not in the list", name)
		}
		if g == "" || strings.TrimSpace(g) != g || utf8.RuneCountInString(g) > 30 {
			return fmt.Errorf("Group names have 1–30 characters and no surrounding spaces")
		}
	}
	return nil
}

func (d productDefaults) validate() error {
	if d.Budget < 1 || d.Budget > 30 || d.SleepPenalty < 0 || d.SleepPenalty > d.Budget {
		return fmt.Errorf("Budget must be 1–30 and poor sleep costs 0–budget")
	}
	for _, p := range []*int{d.AmberPenalty, d.RedPenalty} {
		if p != nil && (*p < 0 || *p > d.Budget) {
			return fmt.Errorf("Amber and red days cost 0–budget points")
		}
	}
	if !map[string]bool{"": true, "en-GB": true, "en-US": true, "en-AU": true, "en-CA": true, "de-DE": true, "fr-FR": true, "es-ES": true, "nl-NL": true}[d.Locale] {
		return fmt.Errorf("Choose a supported date format")
	}
	if d.Activities == nil {
		return fmt.Errorf("Activities must be a list")
	}
	activities := make([]string, len(d.Activities))
	ids := map[string]bool{}
	for i, a := range d.Activities {
		activities[i] = a.A
		if a.ID != "" {
			if len(a.ID) > 512 || ids[a.ID] {
				return fmt.Errorf("Activity identities must be unique and under 512 bytes")
			}
			ids[a.ID] = true
		}
		if a.C < -10 || a.C > 10 {
			return fmt.Errorf("Activity points must be −10 to 10")
		}
		if g := strings.TrimSpace(a.G); g != a.G || utf8.RuneCountInString(g) > 30 {
			return fmt.Errorf("Group names have at most 30 characters and no surrounding spaces")
		}
	}
	for _, list := range [][]string{activities, d.Symptoms, d.Triggers} {
		if list == nil || len(list) > 200 {
			return fmt.Errorf("Each list must contain at most 200 items")
		}
		seen := map[string]bool{}
		for _, name := range list {
			trimmed := strings.TrimSpace(name)
			if trimmed != name || trimmed == "" || utf8.RuneCountInString(name) > 60 {
				return fmt.Errorf("Names must have 1–60 characters with no surrounding spaces")
			}
			key := strings.ToLower(name)
			if seen[key] {
				return fmt.Errorf("Names in each list must be distinct")
			}
			seen[key] = true
		}
	}
	if err := validGroups(d.SymptomGroups, d.Symptoms); err != nil {
		return err
	}
	return validGroups(d.TriggerGroups, d.Triggers)
}
func defaultsTag(raw string) string { return fmt.Sprintf(`"%x"`, sha256.Sum256([]byte(raw))) }
func (s *server) getDefaults(r *http.Request) (string, bool, error) {
	var value string
	err := s.db.QueryRowContext(r.Context(), "SELECT value FROM instance_settings WHERE key = 'product_defaults'").Scan(&value)
	if err == sql.ErrNoRows {
		b, e := webFS.ReadFile("web/defaults.json")
		return string(b), false, e
	}
	return value, true, err
}
func (s *server) productGetDefaults(w http.ResponseWriter, r *http.Request) {
	raw, _, err := s.getDefaults(r)
	if err != nil {
		serverError(w, r, err)
		return
	}
	w.Header().Set("ETag", defaultsTag(raw))
	w.Header().Set("Cache-Control", "no-store")
	var stored productDefaults
	if json.Unmarshal([]byte(raw), &stored) != nil || stored.validate() != nil {
		// Keep the stored-value ETag so an admin can repair damaged defaults through the normal editor.
		fallback, err := webFS.ReadFile("web/defaults.json")
		if err != nil {
			serverError(w, r, err)
			return
		}
		raw = string(fallback)
		w.Header().Set("X-Jiggered-Defaults-Fallback", "true")
	}
	writeJSON(w, http.StatusOK, json.RawMessage(raw))
}
func (s *server) productPutDefaults(w http.ResponseWriter, r *http.Request) {
	var in productDefaults
	if !readJSON(w, r, &in) {
		return
	}
	in.SymptomGroups = pruneGroups(in.SymptomGroups, in.Symptoms)
	in.TriggerGroups = pruneGroups(in.TriggerGroups, in.Triggers)
	if err := in.validate(); err != nil {
		jsonError(w, 400, err.Error())
		return
	}
	old, exists, err := s.getDefaults(r)
	if err != nil {
		serverError(w, r, err)
		return
	}
	if r.Header.Get("If-Match") != defaultsTag(old) {
		jsonError(w, 409, "Defaults changed elsewhere. Reload them before saving; your draft is kept.")
		return
	}
	// pruneGroups above made both maps non-nil, so they are stored even when empty: an absent map means
	// "use the factory groups", an empty one means none.
	b, err := json.Marshal(in)
	if err != nil {
		serverError(w, r, err)
		return
	}
	tx, err := s.db.BeginTx(r.Context(), nil)
	if err != nil {
		serverError(w, r, err)
		return
	}
	defer tx.Rollback()
	if err := guardMutation(r.Context(), tx); err != nil {
		s.adminFail(w, r, err)
		return
	}
	var result sql.Result
	if exists {
		result, err = tx.ExecContext(r.Context(), "UPDATE instance_settings SET value=?,updated_at=? WHERE key='product_defaults' AND value=?", string(b), time.Now().Unix(), old)
	} else {
		result, err = tx.ExecContext(r.Context(), "INSERT OR IGNORE INTO instance_settings(key,value,updated_at) VALUES('product_defaults',?,?)", string(b), time.Now().Unix())
	}
	if err != nil {
		serverError(w, r, err)
		return
	}
	n, err := result.RowsAffected()
	if err != nil {
		serverError(w, r, err)
		return
	}
	if n != 1 {
		jsonError(w, 409, "Defaults changed elsewhere. Reload before saving.")
		return
	}
	if err := tx.Commit(); err != nil {
		serverError(w, r, err)
		return
	}
	s.audit(r.Context(), authOf(r).u.Username, "defaults_changed", "", "Updated shared product defaults", s.clientIP(r))
	w.Header().Set("ETag", defaultsTag(string(b)))
	writeJSON(w, 200, in)
}

