// fakeS3 is a well-behaved stand-in. This endpoint verifies every SigV4 signature and the uploaded payload digest.
func fakeS3(t *testing.T) (*httptest.Server, *sync.Mutex, map[string][]byte) {
	t.Helper()
	return fakeS3With(t, "")
}

// fakeS3With is fakeS3 with one bad behaviour: "tamper" (a probe or backup comes back changed), "nodelete"
// (deletes are refused) or "nolist" (listings fail).
func fakeS3With(t *testing.T, behaviour string) (*httptest.Server, *sync.Mutex, map[string][]byte) {
	t.Helper()
	objects := map[string][]byte{}
	mu := &sync.Mutex{}
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		parsed, err := time.Parse("20060102T150405Z", r.Header.Get("X-Amz-Date"))
		if err != nil {
			http.Error(w, "date", 403)
			return
		}
		expected := r.Clone(r.Context())
		u := *r.URL
		u.Host = r.Host
		u.Scheme = "http"
		expected.URL = &u
		c := &s3Client{accessKey: "test-access", secretKey: "test-secret", region: "us-east-1", now: func() time.Time { return parsed }}
		got := r.Header.Get("Authorization")
		c.sign(expected, r.Header.Get("X-Amz-Content-Sha256"), r.ContentLength)
		if got != expected.Header.Get("Authorization") {
			http.Error(w, "signature", 403)
			return
		}
		key := strings.TrimPrefix(r.URL.Path, "/backups/")
		mu.Lock()
		defer mu.Unlock()
		if r.URL.Query().Get("list-type") == "2" {
			if behaviour == "nolist" {
				http.Error(w, "listing broken", 500)
				return
			}
			result := listResult{}
			for k, v := range objects {
				if strings.HasPrefix(k, r.URL.Query().Get("prefix")) {
					result.Contents = append(result.Contents, struct {
						Key          string    `xml:"Key"`
						Size         int64     `xml:"Size"`
						LastModified time.Time `xml:"LastModified"`
						ETag         string    `xml:"ETag"`
					}{k, int64(len(v)), time.Now(), "tag"})
				}
			}
			b, _ := xml.Marshal(result)
			w.Write(b)
			return
		}
		switch r.Method {
		case "PUT":
			b, _ := io.ReadAll(r.Body)
			sum := sha256.Sum256(b)
			if hex.EncodeToString(sum[:]) != r.Header.Get("X-Amz-Content-Sha256") {
				http.Error(w, "checksum", 400)
				return
			}
			objects[key] = b
			w.WriteHeader(200)
		case "GET":
			b, ok := objects[key]
			if !ok {
				w.WriteHeader(404)
				return
			}
			if behaviour == "tamper" {
				b = []byte("changed in transit")
			}
			w.Header().Set("Content-Length", strconv.Itoa(len(b)))
			w.Write(b)
		case "DELETE":
			if behaviour == "nodelete" {
				http.Error(w, "denied", 403)
				return
			}
			delete(objects, key)
			w.WriteHeader(204)
		default:
			w.WriteHeader(400)
		}
	}))
	t.Cleanup(ts.Close)
	return ts, mu, objects
}
func fakeSMTP(t *testing.T) (emailSettings, <-chan string) {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { ln.Close() })
	messages := make(chan string, 20)
	go func() {
		for {
			conn, err := ln.Accept()
			if err != nil {
				return
			}
			go func() {
				defer conn.Close()
				conn.SetDeadline(time.Now().Add(5 * time.Second))
				reader := bufio.NewReader(conn)
				fmt.Fprint(conn, "220 local test SMTP\r\n")
				for {
					line, err := reader.ReadString('\n')
					if err != nil {
						return
					}
					switch {
					case strings.HasPrefix(line, "EHLO"), strings.HasPrefix(line, "HELO"):
						fmt.Fprint(conn, "250 localhost\r\n")
					case strings.HasPrefix(line, "MAIL"), strings.HasPrefix(line, "RCPT"):
						fmt.Fprint(conn, "250 ok\r\n")
					case strings.HasPrefix(line, "DATA"):
						fmt.Fprint(conn, "354 send data\r\n")
						var body strings.Builder
						for {
							line, err = reader.ReadString('\n')
							if err != nil {
								return
							}
							if line == ".\r\n" {
								break
							}
							body.WriteString(line)
						}
						messages <- body.String()
						fmt.Fprint(conn, "250 queued\r\n")
					case strings.HasPrefix(line, "QUIT"):
						fmt.Fprint(conn, "221 bye\r\n")
						return
					default:
						fmt.Fprint(conn, "500 no\r\n")
					}
				}
			}()
		}
	}()
	host, port, _ := net.SplitHostPort(ln.Addr().String())
	n, _ := strconv.Atoi(port)
	return emailSettings{Enabled: true, Host: host, Port: n, TLS: "none", From: "server@example.com", To: []string{"admin@example.com"}, OnSuccess: true, OnFailure: true}, messages
}
