		t.Fatal("token replay", st)
	}
	if where := c.login("newperson", "newpassword1"); where != "/" {
		t.Fatal(where)
	}
	if st := c.do("POST", "/api/auth/forgot-password", map[string]string{"email": "person@example.com"}); st != 200 {
		t.Fatal(st)
	}
	reset := tokenFromMail(t, mails, "reset")
