  // ---------------- phone: one day, a grip to move blocks, and a page that still scrolls ----------------
  {
    const { page, context, docs, errors } = await openApp({
      viewport: { width: 375, height: 812 },
      isMobile: true,
      hasTouch: true,
    });
    assert.equal(
      await page.locator("#plan-board [data-cal-col]").count(),
