    // Shortening from the top edge halves them.
    await reveal();
    b = await box(block(page, "log:l1", T));
    await drag(
      page,
      { x: b.x + b.width / 2, y: b.y + 2 },
      { x: b.x + b.width / 2, y: b.y + 2 + 28 },
