    assert.match(
      await page.locator("#entry-length-hint").textContent(),
      /−2 for 1 h, so −4 for 2 h/,
    );
    await page.locator("#entry-cost").fill("5");
    await page.locator("#entry-dur").fill("90");
    await page.locator("#entry-dur").press("Tab");
    assert.equal(
      await page.locator("#entry-cost").inputValue(),
      "5",
      "typed points are left alone",
    );
    await page.locator("#entry-cancel").click();
    assert.equal(find("l1").c, 2, "cancelling saves nothing");

    // Pick an activity, then a time: the other way to place one, which needs no dragging.
    await reveal();
    await chip("Quiet break").click();
    assert.equal(await page.locator("#today-placing").isVisible(), true);
    assert.equal(await chip("Quiet break").getAttribute("aria-pressed"), "true");
    await page.keyboard.press("Escape");
    assert.equal(await page.locator("#today-placing").isVisible(), false, "Escape lets go of it");
    assert.equal(await chip("Quiet break").getAttribute("aria-pressed"), "false");
    await chip("Quiet break").click();
    const free = await slot(page, today, 14 * 60 + 20, T);
    await page.mouse.click(free.x, free.y);
    await until(
      () => logged().some((e) => e.a === "Quiet break" && e.t === "14:15"),
      "placed at the time chosen",
    );
    assert.equal(await page.locator("#today-placing").isVisible(), false);
    await undo(page);
    await until(() => !logged().some((e) => e.a === "Quiet break"), "undone");
    // Or log it now instead.
    await chip("Quiet break").click();
    await page.locator("#today-placing-now").click();
    await until(() => logged().some((e) => e.a === "Quiet break"), "logged now");
    assert.match(logged().find((e) => e.a === "Quiet break").t, /^\d\d:\d\d$/);
    await undo(page);

    // Logging something at a time through the form returns you to the timeline when you are done.
    await reveal();
    const y0 = await page.evaluate(() => scrollY);
    const gap = await slot(page, today, 14 * 60 + 20, T);
    await page.mouse.click(gap.x, gap.y);
    assert.equal(await page.locator("#entry-form").isVisible(), true);
    // The editor floats over the timeline as a sheet: the page does not move and the form is on screen.
    assert.equal(await page.locator("#entry-form.is-sheet").count(), 1, "the form is a sheet");
    assert.ok(
      Math.abs((await page.evaluate(() => scrollY)) - y0) <= 3,
      "the page stays where it was",
    );
    const sheetBox = await box(page.locator("#entry-form"));
    assert.ok(
      sheetBox.y >= 0 && sheetBox.y + sheetBox.height <= (await page.evaluate(() => innerHeight)),
      "the whole form is on screen",
    );
    await page.keyboard.press("Escape");
    assert.equal(await page.locator("#entry-form").isVisible(), false, "Escape closes it");
    assert.equal(await page.locator("#entry-form.is-sheet").count(), 0);
    await page.mouse.click(gap.x, gap.y);
    await page.locator("#entry-cancel").click();
    assert.ok(
      Math.abs((await page.evaluate(() => scrollY)) - y0) <= 3,
      "and cancelling leaves the page where it was",
    );

    // Carrying an activity up from the list further down the page scrolls the page towards the timeline.
    await page.setViewportSize({ width: 1440, height: 700 });
    await page
      .locator("#acts button.act")
      .first()
      .evaluate((e) => e.scrollIntoView({ block: "center" }));
    const startY = await page.evaluate(() => scrollY);
    // Count the grid's own scrolling of the page, apart from anything the browser does by itself during a drag.
    await page.evaluate(() => {
      const scrollBy = window.scrollBy.bind(window);
      window.__pageScrolls = 0;
      window.scrollBy = (...args) => {
        window.__pageScrolls++;
        return scrollBy(...args);
      };
    });
    const tile = await box(page.locator("#acts button.act").first());
    const count = logged().length;
    await page.mouse.move(tile.x + 30, tile.y + 10);
    await page.mouse.down();
    await page.mouse.move(tile.x + 30, 8, { steps: 10 });
    await page.waitForTimeout(700);
    assert.ok(
      startY - (await page.evaluate(() => scrollY)) > 150,
      "the page scrolled while it was carried",
    );
    assert.ok(
      (await page.evaluate(() => window.__pageScrolls)) > 5,
      "the grid scrolled it, not only the browser",
    );
    await page.mouse.up();
    await page.waitForTimeout(250);
    assert.equal(logged().length, count, "letting go off the timeline logs nothing");
    assert.deepEqual(errors, []);
    await context.close();
  }

  // ---------------- Today on a phone ----------------
  {
    const T = "#today-board";
    const { page, context, docs, errors } = await openApp(
      { viewport: { width: 375, height: 812 }, isMobile: true, hasTouch: true },
      "today",
      loggedDay(),
    );
    // Open to begin with, with what it needs to place something: the activities, and a short window onto the day.
    assert.equal(await page.locator("#today-timeline-panel").evaluate((d) => d.open), true);
    assert.match(
      await page.locator("#today-timeline-help").textContent(),
      /Tap an activity, then a time/,
    );
    assert.ok(
      (await page.locator("#today-palette .cal-preset").count()) > 5,
      "the activities are listed",
    );
    assert.ok(
      (await box(page.locator(`${T} .cal-scroll`))).height <= 430,
      "a window, not the whole day",
    );
    assert.equal(await page.locator(`${T} [data-cal-col]`).count(), 1);
    assert.equal(
      await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth),
      true,
    );
    const place = () =>
      page.evaluate(() => {
        document.querySelector("#today-board .cal-scroll").scrollTop = 56;
        const b = document.querySelector('#today-board .cal-block[data-id="log:l1"]');
        window.scrollBy(0, b.getBoundingClientRect().top - 250);
      });
    await place();
    // Tapping an empty space opens the form for that time.
    const empty = await slot(page, today, 9 * 60 + 20, T);
    await page.touchscreen.tap(empty.x, empty.y);
    assert.equal(await page.locator("#entry-form").isVisible(), true);
    assert.equal(await page.locator("#entry-time").inputValue(), "09:15");
    await page.locator("#entry-cancel").click();
    // The grip moves a logged block: 72px is an hour at the touch scale.
    await place();
    const cdp = await context.newCDPSession(page);
    const touch = (type, x, y) =>
      cdp.send("Input.dispatchTouchEvent", {
        type,
        touchPoints: type === "touchEnd" ? [] : [{ x, y }],
      });
    const grip = await box(page.locator(`${T} .cal-block[data-id="log:l1"] .cal-grip`));
    await touch("touchStart", grip.x + grip.width / 2, grip.y + grip.height / 2);
    for (let i = 1; i <= 10; i++)
      await touch("touchMove", grip.x + grip.width / 2, grip.y + grip.height / 2 + (72 * i) / 10);
    await touch("touchEnd");
    await until(
      () => docs["d-" + today].body.entries.find((e) => e.id === "l1").t === "10:30",
      "the grip moves it an hour",
    );
    // Tap an activity, then tap a time: it is logged there with the length its name gives. (A click straight after a
    // drag is ignored for a moment, so the tap waits for the drag to be over, as a person would.)
    await page.waitForTimeout(300);
    await page.locator("#today-palette .cal-preset", { hasText: "Deep focus (2 hours)" }).tap();
    assert.equal(await page.locator("#today-placing").isVisible(), true);
    await place();
    const spot = await slot(page, today, 9 * 60 + 20, T);
    await page.touchscreen.tap(spot.x, spot.y);
    await until(
      () => docs["d-" + today].body.entries.some((e) => e.a === "Deep focus (2 hours)"),
      "tap an activity, then a time",
    );
    const placed = docs["d-" + today].body.entries.find((e) => e.a === "Deep focus (2 hours)");
    assert.deepEqual([placed.t, placed.dur], ["09:15", 120]);
    assert.equal(
      await page.locator("#today-placing").isVisible(),
      false,
      "one placement at a time",
    );
    // Dragging the bottom handle changes how long it took, and the points follow: an hour more is twice the points.
    await place();
    const handle = await box(
      page.locator(`${T} .cal-block[data-id="log:l1"] .cal-resize[data-edge="bottom"]`),
    );
    // A swipe that starts on the edge is a scroll, not a resize: nothing changes.
    const before = docs["d-" + today].body.entries.find((e) => e.id === "l1").dur;
    await touch("touchStart", handle.x + handle.width / 2, handle.y + handle.height / 2);
    for (let i = 1; i <= 10; i++)
      await touch(
        "touchMove",
        handle.x + handle.width / 2,
        handle.y + handle.height / 2 + (72 * i) / 10,
      );
    await touch("touchEnd");
    await page.waitForTimeout(500);
    assert.equal(
      docs["d-" + today].body.entries.find((e) => e.id === "l1").dur,
      before,
      "a swipe from the edge does not resize",
    );
    // Pressing and holding the edge, then dragging, does. (The swipe above scrolled the page, so find the edge again.)
    await page
      .locator(`${T} .cal-block[data-id="log:l1"]`)
      .evaluate((el) => el.scrollIntoView({ block: "center" }));
    const held = await box(
      page.locator(`${T} .cal-block[data-id="log:l1"] .cal-resize[data-edge="bottom"]`),
    );
    await touch("touchStart", held.x + held.width / 2, held.y + held.height / 2);
    await page.waitForTimeout(450);
    for (let i = 1; i <= 10; i++)
      await touch("touchMove", held.x + held.width / 2, held.y + held.height / 2 + (72 * i) / 10);
    await touch("touchEnd");
    await until(
      () => docs["d-" + today].body.entries.find((e) => e.id === "l1").dur === 120,
      "the handle lengthens it",
    );
    assert.equal(docs["d-" + today].body.entries.find((e) => e.id === "l1").c, 4);
    assert.deepEqual(errors, []);
    await context.close();
  }

  // ---------------- History on a phone: the glance calendar stays touch-sized ----------------
  {
    const { page, context, errors } = await openApp(
      { viewport: { width: 375, height: 812 }, isMobile: true, hasTouch: true },
      "history",
      loggedDay(),
    );
    const cell = await box(page.locator(".matrix-cell").first());
    assert.ok(
      cell.width >= 44 && cell.height >= 44,
      `month cells are touch-sized (${cell.width}x${cell.height})`,
    );
    assert.equal(
      await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth),
      true,
    );
    assert.deepEqual(errors, []);
    await context.close();
  }
});

// Real app and Chromium, with an in-memory API fixture. No database or server writes.
const { runBrowser } = require("./support/browser.cjs");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const root = path.resolve(__dirname, "../web");
const defaults = JSON.parse(fs.readFileSync(path.join(root, "defaults.json"), "utf8"));
const date = new Date().toISOString().slice(0, 10);
const docs = {
  settings: {
    rev: 1,
    body: {
      ...defaults,
      profile: { displayName: "Alex", theme: "light" },
      onboarding: { dismissed: true },
      activities: [
        { id: "a", a: "Review points", c: 2 },
        { id: "b", a: "Rest", c: -1 },
      ],
    },
  },
};
for (let i = 0; i < 4; i++) {
  const day = new Date(date + "T12:00:00Z");
  day.setUTCDate(day.getUTCDate() - i);
  const key = day.toISOString().slice(0, 10);
  docs["d-" + key] = {
    rev: 1,
    body: {
      date: key,
      status: "green",
      budget: 10,
      poorSleep: false,
      entries: [{ id: "entry", a: "Review points", c: 2 }],
    },
  };
}
const originalDays = JSON.stringify(
  Object.fromEntries(Object.entries(docs).filter(([id]) => id !== "settings")),
);
runBrowser({ name: "energy-theme", startServer: false }, async (harness) => {
  const browser = await harness.launchBrowser();
  const errors = [];
  async function open(viewport) {
    const context = await browser.newContext({
      viewport,
      timezoneId: "UTC",
      serviceWorkers: "block",
    });
    await context.route("http://localhost:18758/**", async (route) => {
      const request = route.request(),
        url = new URL(request.url()),
        pathname = url.pathname;
      const json = (body) =>
        route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(body) });
      if (pathname === "/api/me")
        return json({ id: 1, username: "alex", role: "user", must_change_password: false });
      if (pathname === "/api/defaults") return json(defaults);
      if (pathname === "/api/docs") return json(docs);
      if (pathname.startsWith("/api/docs/") && request.method() === "PUT") {
        const id = decodeURIComponent(pathname.slice("/api/docs/".length));
        docs[id] = { rev: (docs[id]?.rev || 0) + 1, body: request.postDataJSON() };
        return json({ rev: docs[id].rev });
      }
      if (pathname === "/api/me/sessions") return json([]);
      if (pathname === "/api/me/security")
        return json({ two_factor: false, email_available: false });
      if (pathname.startsWith("/api/")) return json({});
      const file = path.join(root, pathname === "/" ? "index.html" : pathname);
      if (!file.startsWith(root) || !fs.existsSync(file)) return route.fulfill({ status: 404 });
      const types = {
        ".js": "text/javascript",
        ".css": "text/css",
        ".html": "text/html",
        ".svg": "image/svg+xml",
        ".woff2": "font/woff2",
        ".png": "image/png",
      };
      return route.fulfill({
        contentType: types[path.extname(file)] || "application/octet-stream",
        body: fs.readFileSync(file),
      });
    });
    const page = await context.newPage();
    page.on("pageerror", (e) => errors.push(e.message));
    await page.goto("http://localhost:18758/");
    await page.locator("#acts button.act").first().waitFor();
    await page.waitForFunction(() => document.querySelector("#sync").dataset.state === "saved");
    return { context, page };
  }
  const { context, page } = await open({ width: 1280, height: 1000 });
  assert.equal(await page.locator("#balance-label").textContent(), "Points left today");
  const balance = await page.locator("#left").textContent();
  await page.locator("#t-account").click();
  await page.locator("#account-tab-profile").click();
  assert.equal(await page.locator("input[name=energyTheme][value=points]").isChecked(), true);
  // Native radio arrow keys change the preview without applying an unfinished draft.
  await page.locator("input[name=energyTheme][value=points]").focus();
  await page.keyboard.press("ArrowRight");
  assert.equal(await page.locator("input[name=energyTheme][value=spoons]").isChecked(), true);
  assert.equal(await page.locator("#energy-theme-preview").textContent(), "8 spoons left today");
  assert.equal(await page.locator("html").getAttribute("data-energy-theme"), "points");
  // The draft is written to the device store in the background; reloading before that lands loses it, as a slow
  // runner showed. Wait for it to be stored, which is what "survives a reload" depends on.
  await page.waitForFunction(
    () =>
      new Promise((resolve) => {
        const request = indexedDB.open("jiggered-device");
        request.onerror = () => resolve(false);
        request.onsuccess = () => {
          const db = request.result,
            tx = db.transaction("items", "readonly"),
            keys = tx.objectStore("items").getAllKeys();
          tx.oncomplete = () => {
            db.close();
            resolve(
              keys.result.some(
                (k) => String(k).includes(":drafts:") && String(k).endsWith(":profile"),
              ),
            );
          };
          tx.onerror = () => {
            db.close();
            resolve(false);
          };
        };
      }),
  );
  await page.reload();
  await page.locator("#profile-save").waitFor();
  assert.equal(
    await page.locator("input[name=energyTheme][value=spoons]").isChecked(),
    true,
    "device draft survives reload",
  );
  const spoonPreferenceSaved = page.waitForResponse(
    (response) =>
      response.request().method() === "PUT" && docs.settings.body.profile.energyTheme === "spoons",
  );
  await page.locator("#profile-save").click();
  await page.waitForFunction(() => document.documentElement.dataset.energyTheme === "spoons");
  await spoonPreferenceSaved;
  assert.equal(docs.settings.body.profile.energyTheme, "spoons");
  assert.equal(docs.settings.body.profile.theme, "light");
  assert.equal(await page.locator("#set-budget").locator("..").innerText(), "Spoons per day");
  assert.equal(
    await page.locator("#set-acts .order-cost").first().getAttribute("aria-label"),
    "Spoons it costs",
  );
  await page.locator("#t-today").click();
  assert.equal(await page.locator("#left").textContent(), balance);
  assert.equal(await page.locator("#balance-label").textContent(), "Spoons left today");
  assert.equal(await page.locator("#cells svg").count(), 10);
  assert.equal(await page.locator(".energy-spoon").isVisible(), true);
  assert.match(await page.locator("#energy-activity-pills").textContent(), /Review points/);
  await page.locator(".energy-panel").screenshot({ path: "/tmp/jiggered-spoons-today.png" });
  await page.locator("#t-history").click();
  assert.match(await page.locator("#history-charts").textContent(), /Net spoons/);
  assert.equal(
    await page.locator("[data-matrix-mode] option[value=used]").textContent(),
    "Activity spoons used",
  );
  assert.match(await page.locator('[data-chart="combined"]').textContent(), /Net spoons/);
  assert.match(await page.locator(".energy-report").textContent(), /spoons used before recovery/);
  assert.match(await page.locator("#history-charts").textContent(), /One point per day/);
  await page.locator("#history-prepare").click();
  assert.match(await page.locator("#summary-preview").textContent(), /Net spoons used/);
  await page.locator("header [data-help]").click();
  await page.locator("#help-search").fill("spoon");
  assert.ok(await page.locator("#help-spoons").isVisible());
  assert.match(await page.locator("#help-spoons").textContent(), /One spoon represents one point/);
  await page.locator("#help-spoons summary").click();
  await page.locator("#help-spoons [data-settings=profile-panel]").click();
  assert.equal(
    await page
      .locator("input[name=energyTheme][value=points]")
      .evaluate((el) => el === document.activeElement),
    true,
  );
  await page.locator("#profile-theme").selectOption("dark");
  await page.locator("#profile-save").click();
  await page.waitForFunction(() => document.documentElement.dataset.theme === "dark");
  await harness.screenshot(page, "energy-desktop.png");
  await page.setViewportSize({ width: 390, height: 900 });
  await harness.screenshot(page, "energy-mobile.png");
  assert.equal(
    await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth),
    true,
    "no horizontal overflow",
  );
  const second = await open({ width: 390, height: 900 });
  assert.equal(
    await second.page.locator("#balance-label").textContent(),
    "Spoons left today",
    "saved preference follows another device",
  );
  await second.page.locator("#t-account").click();
  await second.page.locator("#account-tab-profile").click();
  await second.page.locator("input[name=energyTheme][value=points]").check();
  const pointsPreferenceSaved = second.page.waitForResponse(
    (response) =>
      response.request().method() === "PUT" && docs.settings.body.profile.energyTheme === "points",
  );
  await second.page.locator("#profile-save").click();
  await pointsPreferenceSaved;
  await second.page.waitForFunction(
    () => document.documentElement.dataset.energyTheme === "points",
  );
  await second.page.locator("#t-today").click();
  assert.equal(await second.page.locator("#cells svg").count(), 0);
  assert.equal(await second.page.locator(".energy-spoon").isVisible(), false);
  assert.equal(await second.page.locator("#left").textContent(), balance);
  assert.equal(
    JSON.stringify(Object.fromEntries(Object.entries(docs).filter(([id]) => id !== "settings"))),
    originalDays,
  );
  assert.deepEqual(errors, []);
  await second.context.close();
  await context.close();
  console.log(
    "Energy theme: keyboard preview, draft reload, save, history/print, dark/mobile layout, cross-device and switch-back passed.",
  );
}).catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { fileURLToPath } from "node:url";
import { waitForHealth } from "./support/browser.cjs";

const execute = promisify(execFile);
const harnessPath = fileURLToPath(new URL("./support/browser.cjs", import.meta.url));

test("browser readiness rejects exited servers and bounded health failures", async (t) => {
  await assert.rejects(
    waitForHealth("http://unused", { exitCode: 2, signalCode: null }, () => null),
    /Server exited.*2/,
  );
  t.mock.method(globalThis, "fetch", async () => new Response("not ready", { status: 503 }));
  await assert.rejects(
    waitForHealth("http://unused", { exitCode: null, signalCode: null }, () => null, 10),
    /did not become healthy/,
  );
});

test("browser harness cleans temporary data after an executable fails to start", async (t) => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "jiggered-harness-test-"));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  const source = `require(${JSON.stringify(harnessPath)}).runBrowser({name:'missing'},()=>{}).catch(e=>{console.error(e.message);process.exitCode=1})`;
  await assert.rejects(
    execute(process.execPath, ["-e", source], {
      env: {
        ...process.env,
        TMPDIR: dir,
        JIGGERED_TEST_BINARY: path.join(dir, "missing-binary"),
        JIGGERED_TEST_PORT: "",
        JIGGERED_ARTIFACT_DIR: "",
      },
      timeout: 10000,
    }),
    (error) => error.code === 1 && /ENOENT/.test(error.stderr),
  );
  assert.deepEqual(fs.readdirSync(dir), []);
});

test("browser harness stops its server and removes the database after a scenario fails", async (t) => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "jiggered-harness-test-"));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  const fixture = path.join(dir, "server.cjs"),
    pid = path.join(dir, "pid");
  fs.writeFileSync(
    fixture,
    `#!/usr/bin/env node
const fs=require('node:fs'),http=require('node:http');
fs.writeFileSync(process.env.APP_DB,'disposable fixture');
fs.writeFileSync(${JSON.stringify(pid)},String(process.pid));
const addr=process.env.APP_ADDR.split(':');
http.createServer((req,res)=>res.end('ok')).listen(Number(addr[1]),addr[0]);
`,
  );
  fs.chmodSync(fixture, 0o700);
  const source = `require(${JSON.stringify(harnessPath)}).runBrowser({name:'failure'},()=>{throw Error('intentional scenario failure')}).catch(e=>{console.error(e.message);process.exitCode=1})`;
  await assert.rejects(
    execute(process.execPath, ["-e", source], {
      env: {
        ...process.env,
        TMPDIR: dir,
        JIGGERED_TEST_BINARY: fixture,
        JIGGERED_TEST_PORT: "",
        JIGGERED_ARTIFACT_DIR: "",
      },
      timeout: 10000,
    }),
    (error) => error.code === 1 && /intentional scenario failure/.test(error.stderr),
  );
  assert.throws(() => process.kill(Number(fs.readFileSync(pid, "utf8")), 0), { code: "ESRCH" });
  assert.deepEqual(fs.readdirSync(dir).sort(), ["pid", "server.cjs"]);
});

// Real-browser check of History search on a large account: typing a word updates the view once (after a short pause),
// says so while it waits, ends with the right results, and the other filters still react at once.
// Needs Playwright (see the README); run with `node test/browser-history.cjs`. It builds a temporary binary and database.
const assert = require("node:assert/strict");
const { runBrowser } = require("./support/browser.cjs");
const DAYS = 600; // every day has a check-in; even-numbered days also log "Walk"
const EPISODES = 900;

runBrowser({ name: "history", portEnv: "JIGGERED_HISTORY_PORT" }, async (harness) => {
  const browser = await harness.launchBrowser();
  const { base } = harness;
  const page = await (
    await browser.newContext({ viewport: { width: 1100, height: 900 } })
  ).newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(e.message));

  await page.goto(base + "/login");
  await page.locator("#username").fill("tester");
  await page.locator("#password").fill("local-preview-password");
  await page.getByRole("button", { name: "Sign in", exact: true }).click();
  await page.locator("#t-history").waitFor();

  // Seed through the real API, then reload so the page loads the whole account as a snapshot.
  const seeded = await page.evaluate(
    async ([days, episodes]) => {
      const headers = {
        "Content-Type": "application/json",
        "X-Requested-With": "jiggered",
        "If-None-Match": "*",
      };
      const jobs = [];
      for (let i = 0; i < days; i++) {
        const date = new Date(Date.UTC(2024, 0, 1) + i * 86400000).toISOString().slice(0, 10);
        jobs.push([
          "d-" + date,
          {
            date,
            status: ["green", "amber", "red"][i % 3],
            poorSleep: i % 4 === 0,
            entries:
              i % 2 === 0
                ? [
                    { id: "w" + i, a: "Walk", c: -2, t: "09:00" },
                    { id: "k" + i, a: "Work", c: 3, t: "11:00" },
                  ]
                : [{ id: "k" + i, a: "Work", c: 3, t: "11:00" }],
          },
        ]);
      }
      for (let i = 0; i < episodes; i++) {
        const date = new Date(Date.UTC(2024, 0, 1) + (i % days) * 86400000)
          .toISOString()
          .slice(0, 10);
        jobs.push([
          "e-" + (1700000000000 + i * 1000),
          {
            when: date + "T09:00",
            symptoms: ["Headache"],
            before: ["Poor sleep"],
            notes: "n".repeat(1500),
          },
        ]);
      }
      const assertSeed = (status, id) => {
        if (status !== 200) throw new Error(`Seed ${id} failed: HTTP ${status}`);
      };
      let ok = 0;
      for (let i = 0; i < jobs.length; i += 25) {
        const results = await Promise.all(
          jobs.slice(i, i + 25).map(async ([id, body]) => {
            const response = await fetch("/api/docs/" + id, {
              method: "PUT",
              headers,
              body: JSON.stringify(body),
            });
            await response.arrayBuffer();
            assertSeed(response.status, id);
            return response.status;
          }),
        );
        ok += results.filter((status) => status === 200).length;
      }
      return ok;
    },
    [DAYS, EPISODES],
  );
  assert.equal(seeded, DAYS + EPISODES, "every seeded document was accepted");
  await page.reload();
  await page.waitForFunction(() => document.querySelector("#sync")?.dataset.state === "saved");

  await page.locator("#t-history").click();
  await page.setViewportSize({ width: 390, height: 900 });
  for (const range of [7, 30, 90, 180, 365]) {
    await page.locator("#history-range").selectOption(String(range));
    for (const mode of ["checkin", "used", "points", "sleep", "episodes"]) {
      await page.locator("[data-matrix-mode]").selectOption(mode);
      assert.equal(
        await page.locator("[data-matrix-grid] button").count(),
        Math.min(range, 35),
        "a phone shows five weeks of the chosen range at a time, so every day stays tappable",
      );
      const sizes = await page.locator(".matrix-calendar").evaluate((el) => ({
        width: el.getBoundingClientRect().width,
        parent: el.closest(".matrix-overview").getBoundingClientRect().width,
        slots: el.querySelector("[data-matrix-grid]").children.length,
      }));
      assert.ok(sizes.width <= sizes.parent + 1, "calendar stays within its panel");
      assert.equal(sizes.slots % 7, 0, "both partial weeks have complete rows");
    }
  }
  await page.setViewportSize({ width: 1100, height: 900 });
  // On a desktop the days fill their card, whatever the period, rather than a small grid in a wide panel; the card
  // sits level with the selected day beside it; and a closed section is only its heading.
  for (const [range, layout] of [
    [7, "list"],
    [30, "calendar"],
    [90, "heatmap"],
    [180, "heatmap"],
    [365, "heatmap"],
  ]) {
    await page.locator("#history-range").selectOption(String(range));
    const fit = await page.evaluate(() => {
      const card = document.querySelector(".matrix-overview").getBoundingClientRect(),
        reading = document.querySelector(".matrix-reading").getBoundingClientRect(),
        grid = document.querySelector("[data-matrix-grid]").getBoundingClientRect();
      return {
        layout: document.querySelector("[data-matrix-calendar]").dataset.layout,
        share: grid.width / card.width,
        height: Math.abs(card.height - reading.height),
        top: Math.abs(card.top - reading.top),
        overflow: document.documentElement.scrollWidth - innerWidth,
      };
    });
    assert.equal(fit.layout, layout, `${range} days are laid out as a ${layout}`);
    assert.ok(fit.share > 0.8, `${range} days fill their card (${Math.round(fit.share * 100)}%)`);
    assert.ok(
      fit.height <= 1 && fit.top <= 1,
      `the calendar and the day are level at ${range} days`,
    );
    assert.ok(fit.overflow <= 0, `no sideways scrolling at ${range} days`);
  }
  assert.ok(
    (await page.locator("#history-share").boundingBox()).height < 70,
    "a closed section is only its heading",
  );
  // Arrow keys follow what is on screen: down a list, along a calendar's row, down a heatmap's column.
  for (const [range, keys] of [
    [7, { ArrowDown: 1, ArrowUp: -1 }],
    [30, { ArrowRight: 1, ArrowLeft: -1, ArrowDown: 7, ArrowUp: -7 }],
    [90, { ArrowDown: 1, ArrowUp: -1, ArrowRight: 7, ArrowLeft: -7 }],
  ]) {
    await page.locator("#history-range").selectOption(String(range));
    const middle = page.locator(`[data-matrix-grid] [data-cell="${Math.floor(range / 2)}"]`);
    for (const [key, step] of Object.entries(keys)) {
      await middle.click();
      await middle.press(key);
      assert.equal(
        await page.evaluate(() => Number(document.activeElement.dataset.cell)),
        Math.floor(range / 2) + step,
        `${key} moves ${step} in the ${range}-day view`,
      );
    }
  }
  await page.locator("#history-range").selectOption("all");
  await page.locator("#history-explore > summary").click();
  await page.waitForFunction(
    ([d, e]) =>
      new RegExp(`${d} days? and ${e} episodes?`).test(
        document.getElementById("history-count").textContent,
      ),
    [DAYS, EPISODES],
  );

  assert.equal(await page.locator('[data-chart="combined"] svg').count(), 1);
  assert.match(
    await page.locator(".energy-report").textContent(),
    /1800 points used before recovery.*600 recovered.*1200 net/,
  );
  await page.locator("#chart-combined-select").selectOption("0");
  assert.match(
    await page.locator('[data-chart="combined"] [data-detail]').textContent(),
    /Used points 3/,
  );
  for (const width of [800, 1100]) {
    await page.setViewportSize({ width, height: 900 });
    for (const selector of [
      ".label-row",
      ".history-chart",
      ".chart-legend",
      ".chart-inspector",
      ".chart-data",
    ]) {
      const positions = await page.evaluate(
        (selector) =>
          ["energy", "episodes"].map(
            (kind) =>
              document.querySelector(`[data-chart="${kind}"] ${selector}`).getBoundingClientRect()
                .top,
          ),
        selector,
      );
      assert.ok(Math.abs(positions[0] - positions[1]) < 1, `${selector} aligns at ${width}px`);
    }
  }
  for (const width of [320, 390]) {
    await page.setViewportSize({ width, height: 900 });
    await page.locator('[data-chart="combined"] .chart-data').evaluate((el) => {
      el.open = true;
    });
    assert.ok(
      await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth),
      `no horizontal overflow at ${width}px`,
    );
    // On a phone the chart is drawn narrower so its labels are not shrunk to a few pixels.
    const axis = await page.evaluate(() => {
      const svg = document.querySelector('[data-chart="energy"] svg.history-chart'),
        label = svg.querySelector("text.chart-axis");
      return {
        viewBox: svg.getAttribute("viewBox"),
        px:
          (svg.getBoundingClientRect().width / svg.viewBox.baseVal.width) *
          parseFloat(getComputedStyle(label).fontSize),
      };
    });
    assert.match(axis.viewBox, /^0 0 320 /, `phone chart uses the narrow drawing at ${width}px`);
    assert.ok(axis.px >= 10, `chart labels render at ${axis.px.toFixed(1)}px at ${width}px`);
    // "Prepare summary" says why it is unavailable, or nothing; the preview is read as cards, not a wide table.
    await page.locator("#history-prepare").click();
    const cards = await page.evaluate(() => {
      const row = document.querySelector("#summary-preview tbody tr");
      return row
        ? {
            display: getComputedStyle(row).display,
            wider:
              document.getElementById("summary-preview").scrollWidth >
              document.getElementById("summary-preview").clientWidth,
            label: getComputedStyle(row.querySelector("td"), "::before").content,
          }
        : null;
    });
    assert.ok(cards, "the preview has rows");
    assert.equal(cards.display, "block", `preview rows are cards at ${width}px`);
    assert.equal(cards.wider, false, `the preview needs no sideways scrolling at ${width}px`);
    assert.match(cards.label, /\w/, "each cell carries its label");
  }
  await page.setViewportSize({ width: 800, height: 900 });
  await page.locator('[data-chart="combined"] .chart-data').evaluate((el) => {
    el.open = false;
  });
  if (process.env.JIGGERED_HISTORY_SCREENSHOT)
    await page
      .locator("#history-graphs")
      .screenshot({ path: process.env.JIGGERED_HISTORY_SCREENSHOT });
  await page.setViewportSize({ width: 1100, height: 900 });

  // One word, typed quickly, is one update: count how many times the charts are rebuilt while it is typed.
  await page.evaluate(() => {
    window.__rebuilds = 0;
    new MutationObserver(() => {
      window.__rebuilds++;
    }).observe(document.getElementById("history-charts"), { childList: true });
  });
  await page.evaluate(() => {
    document.getElementById("history-filter-panel").open = true;
  });
  await page.locator("#hist-query").click();
  await page.keyboard.type("walk", { delay: 40 });
  assert.equal(
    (await page.locator("#history-count").textContent()).trim(),
    "Updating…",
    "it says it is working while it waits for a pause",
  );
  const expectedDays = Math.ceil(DAYS / 2);
  await page.waitForFunction(
    (n) =>
      new RegExp(`^${n} days? and 0 episodes?`).test(
        document.getElementById("history-count").textContent.trim(),
      ),
    expectedDays,
  );
  const rebuilds = await page.evaluate(() => window.__rebuilds);
  assert.ok(
    rebuilds >= 1 && rebuilds <= 2,
    `typing "walk" rebuilt the charts ${rebuilds} times; once (at most twice for the markup swap) is expected, not once per letter`,
  );
  assert.equal((await page.locator("#days li").count()) > 0, true, "matching days are listed");
  assert.match(await page.locator("#days").first().textContent(), /\d/, "the list shows days");

  // Enter does not wait for the pause.
  await page.locator("#hist-query").fill("");
  await page.waitForFunction(
    ([d, e]) =>
      new RegExp(`^${d} days? and ${e} episodes?`).test(
        document.getElementById("history-count").textContent.trim(),
      ),
    [DAYS, EPISODES],
  );
  await page.locator("#hist-query").pressSequentially("headache");
  await page.keyboard.press("Enter");
  await page.waitForFunction(
    (n) =>
      new RegExp(`^0 days and ${n} episodes?`).test(
        document.getElementById("history-count").textContent.trim(),
      ),
    EPISODES,
  );

  // Other filters react at once, and the search still applies on top of them.
  await page.locator("#hist-query").fill("");
  await page.waitForFunction(
    ([d, e]) =>
      new RegExp(`^${d} days? and ${e} episodes?`).test(
        document.getElementById("history-count").textContent.trim(),
      ),
    [DAYS, EPISODES],
  );
  // Changing the select and reading the count in the same tick: only a synchronous update can have changed it.
  const right = await page.evaluate(() => {
    const select = document.getElementById("hist-status");
    select.value = "red";
    select.dispatchEvent(new Event("input", { bubbles: true }));
    return document.getElementById("history-count").textContent.trim();
  });
  assert.match(
    right,
    new RegExp(`^${Math.floor(DAYS / 3)} days? and`),
    "a select changes the view at once, without the search pause",
  );

  assert.deepEqual(errors, []);
  console.log(
    `PASS: History search on ${DAYS} days and ${EPISODES} episodes: one update per typed word with "Updating…" shown, correct results, Enter and selects immediate`,
  );
}).catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

import assert from "node:assert/strict";
import { readFileSync, readdirSync } from "node:fs";
import path from "node:path";
import test from "node:test";

// The browser runner lists its scenarios by hand: a new test/browser-*.cjs that is forgotten there silently
// never runs, and nothing else fails. browser-public.cjs is the one deliberate exception (CI runs it on its own
// against the same fixture, outside the private-app scenarios).
test("every browser scenario is listed in the runner", () => {
  const runner = readFileSync(path.join(import.meta.dirname, "support", "run-browser.cjs"), "utf8");
  const listed = [...runner.matchAll(/"(browser-[a-z-]+)"/g)].map((m) => m[1]).sort();
  const onDisk = readdirSync(import.meta.dirname)
    .filter((f) => /^browser-.*\.cjs$/.test(f) && f !== "browser-public.cjs")
    .map((f) => f.replace(/\.cjs$/, ""))
    .sort();
  assert.ok(onDisk.length > 0, "no browser scenarios found");
  assert.deepEqual(
    listed,
    onDisk,
    "test/support/run-browser.cjs and the test/browser-*.cjs files disagree; keep the scenario list in step",
  );
});

// Real-browser checks at phone width. Account: the page is short until a list is opened, a shortcut opens exactly the
// list it names, collapsing keeps what was typed, and a validation error opens the list it is in. History: with almost
// no data the calendar remains available, optional sections keep filters in place, and Prepare summary moves focus
// clear of the sticky tab bar. Episodes: an offline save that is recovered across a reload still ends with
// a truthful confirmation and reaches the server.
// Needs Playwright (see the README); run with `node test/browser-mobile.cjs`. It builds a temporary binary and database.
const assert = require("node:assert/strict");
const { runBrowser } = require("./support/browser.cjs");
const saved = (page) =>
  page.waitForFunction(() => document.querySelector("#sync")?.dataset.state === "saved");
const section = (page, key) => page.locator(`#settings-panel details[data-section="${key}"]`);
const openKeys = (page) =>
  page.evaluate(() =>
    [...document.querySelectorAll("#settings-panel details[data-section]")]
      .filter((d) => d.open)
      .map((d) => d.dataset.section),
  );

runBrowser({ name: "mobile", portEnv: "JIGGERED_MOBILE_PORT" }, async (harness) => {
  const browser = await harness.launchBrowser();
  const { base } = harness;
  const page = await (
    await browser.newContext({
      viewport: { width: 375, height: 812 },
      isMobile: true,
      hasTouch: true,
    })
  ).newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(e.message));

  await page.goto(base + "/login");
  await page.locator("#username").fill("tester");
  await page.locator("#password").fill("local-preview-password");
  await page.getByRole("button", { name: "Sign in", exact: true }).click();
  await page.locator("#t-account").waitFor();
  await saved(page);

  // 1. The page is short with every list closed (it was about 20,000 px with the default lists open), with counts.
  await page.locator("#t-account").click();
  await section(page, "acts").waitFor();
  assert.deepEqual(await openKeys(page), [], "every list starts closed");
  const height = await page.evaluate(() => document.documentElement.scrollHeight);
  assert.ok(
    height < 8000,
    `the Account page is ${height}px tall at phone width; it should be well under the old ~20,000px`,
  );
  for (const key of ["acts", "sym", "trig"]) {
    const rows = await page.locator(`#set-${key} [data-row]`).count();
    assert.match(
      (await section(page, key).locator("summary [data-count]").textContent()).trim(),
      new RegExp(`^\\(${rows}\\)$`),
      `the ${key} summary shows its ${rows} items`,
    );
  }

  // 2. A shortcut from Today opens the list it names and no other, with focus inside it.
  await page.locator("#t-today").click();
  await page.locator('#today-panel [data-settings="set-acts"]:visible').first().click();
  await page.waitForFunction(
    () => document.querySelector('#settings-panel details[data-section="acts"]')?.open,
  );
  assert.deepEqual(await openKeys(page), ["acts"], "only Activities opened");
  assert.equal(
    await page.evaluate(() => !!document.activeElement?.closest('details[data-section="acts"]')),
    true,
    "focus is inside the Activities list",
  );

  // 3. Collapsing keeps what was typed, and it saves and survives a reload.
  const firstName = page.locator("#set-acts [data-row] input[type=text]:not(.order-group)").first();
  await firstName.fill("Renamed first activity");
  await section(page, "acts").locator("summary").click();
  assert.equal(await section(page, "acts").evaluate((d) => d.open), false, "collapsed");
  await section(page, "acts").locator("summary").click();
  assert.equal(
    await firstName.inputValue(),
    "Renamed first activity",
    "the typed name is still there after collapsing and reopening",
  );
  await page.locator("#setform [type=submit]").click();
  await page.locator("#set-msg").filter({ hasText: "Saved." }).waitFor();
  await saved(page);
  await page.reload();
  await page.locator("#t-account").click();
  await section(page, "acts").locator("summary").click();
  assert.equal(
    await page
      .locator("#set-acts [data-row] input[type=text]:not(.order-group)")
      .first()
      .inputValue(),
    "Renamed first activity",
    "saved and reloaded",
  );

  // 4. A validation error inside a closed list opens that list instead of failing out of sight.
  const names = page.locator("#set-acts [data-row] input[type=text]:not(.order-group)");
  await names.nth(1).fill(await names.first().inputValue()); // two activities with the same name
  await section(page, "acts").locator("summary").click();
  assert.equal(await section(page, "acts").evaluate((d) => d.open), false);
  await page.locator("#setform [type=submit]").click();
  await page.waitForFunction(
    () => document.querySelector('#settings-panel details[data-section="acts"]')?.open,
  );
  assert.equal(await page.locator("#set-msg.err, #set-msg").first().isVisible(), true);
  assert.equal(
    await page.evaluate(() => !!document.activeElement?.closest('details[data-section="acts"]')),
    true,
    "focus moves to the problem inside the opened list",
  );

  assert.equal(
    await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth),
    false,
    "no horizontal overflow at phone width",
  );

  // 5. History with one day and one episode: calendar, optional detail and a summary using the current search.
  await page.evaluate(async () => {
    const today = new Date(),
      pad = (n) => String(n).padStart(2, "0"),
      date = `${today.getFullYear()}-${pad(today.getMonth() + 1)}-${pad(today.getDate())}`;
    const headers = {
      "Content-Type": "application/json",
      "X-Requested-With": "jiggered",
      "If-None-Match": "*",
    };
    await fetch("/api/docs/d-" + date, {
      method: "PUT",
      headers,
      body: JSON.stringify({
        date,
        status: "green",
        entries: [{ id: "a1", a: "Walk", c: -1, t: "09:00" }],
      }),
    });
    await fetch("/api/docs/e-1790000000000", {
      method: "PUT",
      headers,
      body: JSON.stringify({
        when: date + "T09:00",
        symptoms: ["Headache"],
        before: [],
        notes: "",
      }),
    });
  });
  await page.reload();
  await saved(page);
  await page.locator("#t-history").click();
  await page.waitForFunction(() =>
    /1 day and 1 episode/.test(document.getElementById("history-count").textContent),
  );
  assert.match(
    await page.locator("#history-insights").textContent(),
    /Patterns need at least a few/,
    "a nearly empty history shows the short note, not the full insight cards",
  );
  const historyHeight = await page.evaluate(() => document.documentElement.scrollHeight);

  await page.evaluate(() => {
    document.getElementById("history-filter-panel").open = true;
  });
  await page.locator("#hist-query").fill("walk");
  await page.waitForFunction(
    () => !/Updating/.test(document.getElementById("history-count").textContent),
  );
  // Optional detail is reachable by a native summary or the primary action, with the search intact.
  for (const id of ["history-records", "history-explore"]) {
    await page.locator(`#${id} > summary`).click();
    assert.equal(await page.locator(`#${id}`).getAttribute("open"), "");
    assert.equal(
      await page.locator(`#${id} > summary`).evaluate((el) => el === document.activeElement),
      true,
    );
    assert.equal(await page.locator("#hist-query").inputValue(), "walk");
    await page.locator(`#${id} > summary`).click();
  }
  await page.locator("#history-prepare").click();
  await page.waitForFunction(() => {
    const heading = document.querySelector("#history-share > summary h2").getBoundingClientRect();
    const nav = document.querySelector("nav").getBoundingClientRect();
    return (
      heading.top >= (nav.top > innerHeight / 2 ? 0 : nav.bottom) && heading.top < innerHeight - 100
    );
  });
  assert.equal(
    await page
      .locator("#history-share > summary h2")
      .evaluate((el) => el === document.activeElement),
    true,
  );
  assert.equal(await page.locator("#summary-preview").isVisible(), true);
  assert.equal(await page.locator("#hist-query").inputValue(), "walk");
  assert.equal(
    await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth),
    false,
    "no horizontal overflow on History",
  );

  // 6. An offline episode save, then the connection returns while the page reloads: the save may finish before the
  // form has restored its draft, and it must still end with a confirmation (and the note must reach the server).
  const context = page.context();
  await page.locator("#t-episode").click();
  await page.locator("#ep-notes").fill("Saved while offline, confirmed after reload");
  await context.setOffline(true);
  await page.locator("#ep-save").click();
  await page.locator("#eptoast").filter({ hasText: "queued on this device" }).waitFor();
  assert.ok(
    !(await page.locator("#eptoast").textContent()).includes("Saved."),
    "queued is not claimed as saved",
  );
  await context.setOffline(false);
  await page.reload();
  await page.locator("#t-episode").click();
  await page.waitForFunction(() => document.querySelector("#sync")?.dataset.state === "saved");
  await page.locator("#eptoast").filter({ hasText: "Saved." }).waitFor({ timeout: 10000 });
  assert.equal(
    await page.locator("#ep-notes").inputValue(),
    "",
    "the form is clear once the save is confirmed",
  );
  const exported = await (await context.request.get(base + "/api/export")).json();
  assert.ok(
    Object.values(exported).some((d) => d.notes === "Saved while offline, confirmed after reload"),
    "the note reached the server",
  );
  assert.deepEqual(errors, []);
  console.log(
    `PASS: Account lists (${height}px tall when closed): counts, one list per shortcut, values survive collapsing, an error opens its list. History (${historyHeight}px with one day and one episode): calendar, optional sections and Prepare summary keep the search and clear the tab bar. Offline episode save recovered across a reload ends with Saved.`,
  );
}).catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

// The real application with a private in-memory API fixture; no user data.
