const { chromium } = require("playwright");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const { spawn, execFileSync } = require("node:child_process");

const dir = fs.mkdtempSync(path.join(os.tmpdir(), "jiggered-public-"));
const binary = process.env.JIGGERED_TEST_BINARY || path.join(dir, "jiggered");
if (!process.env.JIGGERED_TEST_BINARY)
  execFileSync(process.env.GO_BINARY || "go", ["build", "-o", binary, "."]);
const port = process.env.JIGGERED_TEST_PORT || "18796";
const base = "http://127.0.0.1:" + port;
const server = spawn(binary, [], {
  env: {
    ...process.env,
    APP_DB: path.join(dir, "jiggered.db"),
    APP_ADDR: "127.0.0.1:" + port,
    APP_PUBLIC_ORIGIN: base,
    APP_PUBLIC_INDEXING: "true",
    APP_PASSWORD: "",
    APP_PASSWORD_HASH: "",
  },
  stdio: ["ignore", "ignore", "pipe"],
});
let diagnostics = "";
server.stderr.on("data", (chunk) => (diagnostics += chunk.toString()));
process.on("exit", () => server.kill());

(async () => {
  let browser;
  try {
    let ready = false;
    for (let i = 0; i < 100; i++) {
      try {
        if ((await fetch(base + "/healthz")).ok) {
          ready = true;
          break;
        }
      } catch {}
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
    assert.ok(ready, "server did not start: " + diagnostics);
    const sitemap = await (await fetch(base + "/sitemap.xml")).text();
    const routes = [...sitemap.matchAll(/<loc>([^<]+)<\/loc>/g)].map(
      (match) => new URL(match[1]).pathname,
    );
    assert.equal(routes.length, 9);
    browser = await chromium.launch({
      headless: true,
      ...(process.env.JIGGERED_BROWSER_PATH
        ? { executablePath: process.env.JIGGERED_BROWSER_PATH }
        : {}),
      args: JSON.parse(process.env.JIGGERED_BROWSER_ARGS || "[]"),
    });
    const summaries = [];
    for (const javaScriptEnabled of [false, true]) {
      for (const width of [1440, 390, 320]) {
        const context = await browser.newContext({
          javaScriptEnabled,
          viewport: { width, height: 900 },
        });
        const page = await context.newPage();
        const errors = [];
        page.on("pageerror", (e) => errors.push(e.message));
        page.on("console", (msg) => {
          if (msg.type() === "error") errors.push(msg.text());
        });
        for (const route of routes) {
          const response = await page.goto(base + route);
          await page.locator("h1").waitFor();
          if (javaScriptEnabled) await page.evaluate(() => document.fonts.ready);
          assert.equal(response.status(), 200, route);
          assert.equal(response.headers()["x-robots-tag"], "index, follow");
          assert.equal(await page.locator("h1").count(), 1, route);
          assert.equal(
            await page.locator("link[rel=canonical]").getAttribute("href"),
            base + route,
          );
          assert.equal(await page.locator("meta[name=description]").count(), 1);
          assert.equal(
            await page.evaluate(() => document.documentElement.scrollWidth > innerWidth),
            false,
            `${route} overflows at ${width}px`,
          );
          assert.ok(
            (await page.locator("main").innerText()).length > 700,
            route + " lacks useful initial content",
          );
          assert.ok(await page.locator(".public-nav").isVisible(), "mobile navigation hidden");
          for (const href of await page
            .locator("a[href]")
            .evaluateAll((links) => links.map((link) => link.getAttribute("href")))) {
            if (href.startsWith("/"))
              assert.ok(
                routes.includes(href) || ["/login", "/register"].includes(href),
                "unknown internal link: " + href,
              );
          }
          assert.ok(await page.locator('.nav-actions .secondary[href="/login"]').isVisible());
          assert.equal(
            await page.locator('.public-footer a[href="https://eyup.io"]').innerText(),
            "EyUp.io",
          );
          if (route === "/welcome") {
            assert.match(await page.locator(".hero-availability").innerText(), /currently closed/);
            assert.equal(
              await page.locator(".hero-actions [data-register-link]").getAttribute("href"),
              "/login",
            );
          }
          if (route === "/guides/spoon-theory")
            assert.ok(
              await page
                .getByRole("link", { name: /Christine Miserandino's original Spoon Theory essay/ })
                .count(),
            );
          if (
            process.env.JIGGERED_SCREENSHOT_DIR &&
            ["/welcome", "/guides/spoon-theory"].includes(route)
          ) {
            fs.mkdirSync(process.env.JIGGERED_SCREENSHOT_DIR, { recursive: true });
            await page.screenshot({
              path: path.join(
                process.env.JIGGERED_SCREENSHOT_DIR,
                `${route.slice(1).replaceAll("/", "-")}-${width}-${javaScriptEnabled}.png`,
              ),
              fullPage: true,
            });
          }
          summaries.push({ route, width, javaScriptEnabled });
        }
        assert.deepEqual(errors, [], "public page script/resource/CSP errors");
        await context.close();
      }
    }
    // The public pages and the sign-in page follow the visitor's light or dark setting, and print stays light.
    const luminance = (rgb) => {
      const [r, g, b] = rgb
        .match(/\d+(\.\d+)?/g)
        .slice(0, 3)
        .map(Number);
      return (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
    };
    for (const scheme of ["light", "dark"]) {
      const themed = await browser.newContext({
        colorScheme: scheme,
        viewport: { width: 375, height: 800 },
      });
      const themedPage = await themed.newPage();
      for (const route of ["/welcome", "/features/energy-tracking", "/login"]) {
        await themedPage.goto(base + route);
        const { back, ink } = await themedPage.evaluate(() => ({
          back: getComputedStyle(document.body).backgroundColor,
          ink: getComputedStyle(document.querySelector("h1")).color,
        }));
        assert.equal(luminance(back) < 0.4, scheme === "dark", `${route} background in ${scheme}`);
        assert.ok(
          Math.abs(luminance(back) - luminance(ink)) > 0.5,
          `${route} text is readable in ${scheme}`,
        );
        if (route !== "/login") {
          // One compact header on a phone: the logo row and one row of links.
          const header = await themedPage.locator("header.site-header").boundingBox();
          assert.ok(header.height <= 130, `${route} header is ${header.height}px tall`);
        }
        if (scheme === "dark") {
          await themedPage.emulateMedia({ media: "print" });
          const printed = await themedPage.evaluate(
            () => getComputedStyle(document.body).backgroundColor,
          );
          assert.ok(luminance(printed) > 0.9, `${route} prints on a light page`);
          await themedPage.emulateMedia({ media: "screen" });
        }
      }
      await themed.close();
    }
    // Browser enhancement must track changes in availability in either direction.
    const context = await browser.newContext({ viewport: { width: 320, height: 900 } });
    const page = await context.newPage();
    await page.route("**/api/auth/options", (route) =>
      route.fulfill({
        contentType: "application/json",
        body: '{"registration":true,"recovery":false}',
      }),
    );
    await page.goto(base + "/welcome");
    await page
      .locator("#registration-status")
      .filter({ hasText: "OPEN FOR REGISTRATION" })
      .waitFor();
    assert.equal(
      await page.locator(".hero-actions [data-register-link]").getAttribute("href"),
      "/register",
    );
    assert.match(await page.locator(".hero-availability").innerText(), /confirm your address/);
    assert.ok(await page.locator('.nav-actions .secondary[href="/login"]').isVisible());
    assert.ok(await page.locator('.nav-actions a[href="/register"]').isVisible());
    assert.equal(
      await page.evaluate(() => document.documentElement.scrollWidth > innerWidth),
      false,
    );
    assert.match(
      await (await fetch(base + "/welcome")).text(),
      /REGISTRATION CLOSED/,
      "mock must not alter server source",
    );
    await context.close();
    console.log(
      `PASS: ${summaries.length} public-page checks with JavaScript on/off, metadata, privacy headers, links, mobile layout and signup enhancement.`,
    );
  } finally {
    if (browser) await browser.close();
    server.kill();
  }
})().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

// Local-only security regression: real IndexedDB, two tabs, copied cookie and admin step-up.
const assert = require("node:assert/strict");
const { request } = require("playwright");
const { runBrowser } = require("./support/browser.cjs");
runBrowser({ name: "security", portEnv: "JIGGERED_SECURITY_PORT" }, async (harness) => {
  const { base } = harness;
  const browser = await harness.launchBrowser();
  const context = await browser.newContext();
  const page = await context.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(e.message));
  await page.goto(base + "/login");
  await page.locator("#username").fill("tester");
  await page.locator("#password").fill("local-preview-password");
  await page.getByRole("button", { name: "Sign in", exact: true }).click();
  await page.locator("#t-admin").waitFor();
  await page.waitForFunction(() => document.querySelector("#sync")?.dataset.state === "saved");
  const headers = { "X-Requested-With": "jiggered" };
  const denied = await context.request.post(base + "/api/admin/users", {
    headers,
    data: { username: "intruder", role: "admin" },
  });
  assert.equal(denied.status(), 403);
  await page.locator("#t-admin").click();
  await page.locator("#new-name").fill("safeuser");
  await page.locator("#admin-confirm-pw").fill("local-preview-password");
  await page.locator("#adduser [type=submit]").click();
  await page.locator("#adduser-msg").filter({ hasText: "Created safeuser." }).waitFor();
  await page.locator("#reveal-hide").click(); // the temporary password is in a dialog
  assert.equal(await page.locator("#admin-confirm-pw").inputValue(), "");
  const stolen = await request.newContext({ storageState: await context.storageState() });
  const changed = await context.request.post(base + "/api/me/password", {
    headers,
    data: { current: "local-preview-password", new: "changed-owner-password" },
  });
  assert.equal(changed.status(), 204);
  assert.equal((await stolen.get(base + "/api/docs")).status(), 401);
  assert.equal((await context.request.get(base + "/api/docs")).status(), 200);
  await stolen.dispose();
  // Put private acknowledged and unsent copies on the writer, then sign out from its reader.
  await page.locator("#t-today").click();
  await page.locator("#checkin [data-s=amber]").click();
  await page.waitForFunction(() => document.querySelector("#sync")?.dataset.state === "saved");
  await page.route("**/api/docs/*", (route) =>
    route.fulfill({ status: 503, body: "{}", contentType: "application/json" }),
  );
  await page.locator("#acts button.act").first().click();
  const reader = await context.newPage();
  reader.on("pageerror", (e) => errors.push(e.message));
  await reader.goto(base);
  await reader.locator("#tab-reload").waitFor();
  reader.on("dialog", (d) => d.accept());
  await reader.locator("#signout").evaluate((form) => form.requestSubmit());
  await reader.waitForURL("**/login");
  await page.waitForURL("**/login");
  const state = await reader.evaluate(async () => ({
    me: localStorage.getItem("jiggered:me"),
    keys: Object.keys(localStorage).filter(
      (k) => k.startsWith("jiggered:") && k !== "jiggered:purge-generation",
    ),
    items: await new Promise((resolve, reject) => {
      const req = indexedDB.open("jiggered-device");
      req.onsuccess = () => {
        const db = req.result,
          tx = db.transaction("items", "readonly"),
          r = tx.objectStore("items").getAll();
        tx.oncomplete = () => {
          db.close();
          resolve(r.result);
        };
        tx.onerror = () => reject(tx.error);
      };
      req.onerror = () => reject(req.error);
    }),
  }));
  assert.equal(state.me, null);
  assert.deepEqual(state.keys, []);
  assert.deepEqual(state.items, []);
  assert.deepEqual(errors, []);
  // A revoked session also removes identity and device copies, rather than reopening offline.
  await reader.locator("#username").fill("tester");
  await reader.locator("#password").fill("changed-owner-password");
  await reader.getByRole("button", { name: "Sign in", exact: true }).click();
  await reader.locator("#t-today").waitFor();
  await reader.waitForFunction(() => document.querySelector("#sync")?.dataset.state === "saved");
  assert.equal(
    (await context.request.post(base + "/api/me/sessions/revoke-all", { headers })).status(),
    200,
  );
  await reader.evaluate(() => window.dispatchEvent(new Event("online")));
  await reader.waitForURL("**/login?e=expired");
  // A session that was ended elsewhere says so, instead of dropping the person on a bare sign-in page.
  await reader.locator("#err").filter({ hasText: "You were signed out" }).waitFor();
  assert.equal(await reader.evaluate(() => localStorage.getItem("jiggered:me")), null);
  console.log(
    "PASS: admin changes require fresh password, cookie rotation kills copied token, reader logout purges IndexedDB and fences writer, revoked sessions purge identity",
  );
}).catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

// Real-browser check of Today: the first-run checklist, the check-in that collapses to one line with Undo, and the
// activity picker: groups start open so a new list shows buttons, a logged activity turns green with a count
// and -/+ buttons in place, and groups the person opens stay open.
// Needs Playwright (see the README); run with `node test/browser-today.cjs`. It builds a temporary binary and database.
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const { runBrowser } = require("./support/browser.cjs");
const saved = (page) =>
  page.waitForFunction(() => document.querySelector("#sync")?.dataset.state === "saved");
const groups = (page) =>
  page.evaluate(() => [...document.querySelectorAll("#acts details.act-group")].map((d) => d.open));

runBrowser({ name: "today", portEnv: "JIGGERED_TODAY_PORT" }, async (harness) => {
  const { base } = harness;
  const browser = await harness.launchBrowser();
  const page = await (
    await browser.newContext({ viewport: { width: 390, height: 900 } })
  ).newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(e.message));

  await page.goto(base + "/login");
  await page.locator("#username").fill("tester");
  await page.locator("#password").fill("local-preview-password");
  await page.getByRole("button", { name: "Sign in", exact: true }).click();
  await page.locator("#acts details.act-group").first().waitFor();
  await saved(page);

  // A new account gets the first-run checklist, with nothing ticked yet.
  await page.locator("#onboarding").waitFor();
  assert.equal(
    await page.locator("#onboarding li.done").count(),
    0,
    "nothing is ticked before anything is logged",
  );

  // The optional wording step switches the whole app between points and spoons, and back.
  await page.locator('#onboarding [data-wording="spoons"]').click();
  await page.waitForFunction(() => document.documentElement.dataset.energyTheme === "spoons");
  assert.equal(
    await page.locator('#onboarding [data-wording="spoons"]').getAttribute("aria-pressed"),
    "true",
  );
  await page.locator('#onboarding [data-wording="points"]').click();
  await page.waitForFunction(() => document.documentElement.dataset.energyTheme === "points");
  await saved(page);

  // The check-in collapses to one line once chosen; changing or clearing it offers Undo.
  await page.locator('#checkin [data-s="amber"]').click();
  await saved(page);
  assert.ok(await page.locator("#checkin-done").isVisible(), "a chosen check-in becomes one line");
  assert.equal(await page.locator("#checkin").isVisible(), false);
  assert.match(await page.locator("#checkin-done-text").textContent(), /Amber/);
  assert.ok(await page.locator("#step-checkin.done").count(), "the check-in step ticks itself");
  await page.locator("#checkin-change").click();
  await page.locator('#checkin [data-s="amber"]').click(); // tapping the chosen one clears it
  await saved(page);
  assert.match(await page.locator("#advice").textContent(), /Pick one/);
  await page.locator("#toastbar button", { hasText: "Undo" }).click();
  await saved(page);
  assert.match(
    await page.locator("#checkin-done-text").textContent(),
    /Amber/,
    "Undo restores the cleared check-in",
  );

  // Groups start open, so a new list shows buttons straight away; nothing is pinned yet.
  const initial = await groups(page);
  assert.ok(initial.length >= 2, "the default list has several groups");
  assert.deepEqual(
    initial.filter((x) => !x),
    [],
    "every group starts open",
  );
  assert.equal(await page.locator("#acts .act.on").count(), 0, "nothing is logged yet");

  // Log the first group's first activity.
  const firstButton = page.locator("#acts details.act-group[open] button.act").first();
  const name = (await firstButton.locator("span").first().textContent()).trim();
  const inList = (el) =>
    el.evaluate((e) => {
      const a = e.getBoundingClientRect(),
        b = document.getElementById("acts").getBoundingClientRect();
      return { x: a.x - b.x, y: a.y - b.y };
    });
  const before = await inList(firstButton);
  const beforeHeight = await firstButton.evaluate((el) => el.getBoundingClientRect().height);
  await firstButton.click();
  await saved(page);

  const card = page.locator("#acts details.act-group .act.on", { hasText: name }).first();
  await card.waitFor();
  const after = await inList(card);
  assert.ok(
    Math.abs((await card.evaluate((el) => el.getBoundingClientRect().height)) - beforeHeight) < 2,
    "selection keeps the tile height",
  );
  assert.equal(await page.getByRole("heading", { name: "So far", exact: true }).count(), 0);
  assert.ok(
    Math.abs(after.y - before.y) < 2 && Math.abs(after.x - before.x) < 2,
    "a logged activity changes in place instead of moving",
  );
  assert.equal(await page.locator("#onboarding li.done").count(), 2, "both first steps are ticked");
  assert.match(
    await page.locator("#onboarding-title").textContent(),
    /first records are ready.*Allowance review is optional/,
    "the finished checklist stays up for now",
  );
  assert.equal((await card.locator(".count").textContent()).trim(), "×1");
  assert.equal(
    await page.locator("#acts details.act-group button.act", { hasText: name }).count(),
    0,
    "the plain button became the logged card",
  );
  // The keyboard's place follows the tile: it lands on the card's "+", and Ctrl+Z takes the log back while the
  // toast with Undo is on screen.
  assert.equal(
    await card.locator('[data-step="1"]').evaluate((el) => el === document.activeElement),
    true,
    "focus follows the tile to its + button",
  );
  await page.keyboard.press("Control+z");
  await page.locator("#entries li").first().waitFor({ state: "detached" });
  assert.equal(await page.locator("#acts .act.on").count(), 0, "Ctrl+Z took the activity back");
  // Log it again from the keyboard: Enter on the tile, focus lands on the card's +.
  const again = page.locator("#acts details.act-group[open] button.act", { hasText: name }).first();
  await again.focus();
  await page.keyboard.press("Enter");
  await saved(page);
  await card.waitFor();
  assert.equal(
    await card.locator('[data-step="1"]').evaluate((el) => el === document.activeElement),
    true,
    "Enter on a tile leaves focus on the logged card, not the page",
  );
  const green = await page.evaluate(() =>
    getComputedStyle(document.documentElement).getPropertyValue("--green").trim(),
  );
  const border = await card.evaluate((el) => getComputedStyle(el).borderTopColor);
  assert.ok(green && border !== "rgba(0, 0, 0, 0)", "the card has a visible green border");
  assert.equal(
    await card.locator('[data-step="1"]').getAttribute("aria-label"),
    `Add one more ${name}`,
  );
  assert.equal(
    await card.locator('[data-step="-1"]').getAttribute("aria-label"),
    `Remove one ${name}`,
  );

  // + logs another, - takes one off (with Undo), and the entries list agrees at every step.
  const entries = () => page.locator("#entries li").count();
  assert.equal(await entries(), 1);
  await card.locator('[data-step="1"]').click();
  await saved(page);
  assert.equal((await card.locator(".count").textContent()).trim(), "×2");
  assert.equal(await entries(), 2);
  await card.locator('[data-step="-1"]').click();
  await saved(page);
  assert.equal((await card.locator(".count").textContent()).trim(), "×1");
  assert.equal(await entries(), 1);
  await page.locator("#toastbar button", { hasText: "Undo removal" }).click();
  await saved(page);
  assert.equal(
    (await card.locator(".count").textContent()).trim(),
    "×2",
    "Undo puts the removed one back",
  );

  // Closing every group hides everything, logged or not; reopening shows the card where it was.
  while (await page.locator("#acts details.act-group[open] summary").count())
    await page.locator("#acts details.act-group[open] summary").first().click();
  assert.deepEqual((await groups(page)).filter(Boolean), []);
  assert.equal(await card.isVisible(), false, "a logged activity lives in its group");
  await page.locator("#acts details.act-group summary").first().click();
  assert.ok(await card.isVisible());

  // A group the person opened stays open after tapping inside it.
  await page.locator("#acts details.act-group summary").nth(1).click();
  await page.locator("#acts details.act-group[open] button.act").first().click();
  await saved(page);
  assert.equal(
    (await groups(page)).filter(Boolean).length,
    2,
    "the opened groups stay open after tapping",
  );

  // Taking the last one off returns the plain button.
  await card.locator('[data-step="-1"]').click();
  await card.locator('[data-step="-1"]').click();
  await saved(page);
  assert.equal(await page.locator("#acts .act.on", { hasText: name }).count(), 0);
  assert.equal(
    await page.locator("#acts button.act", { hasText: name }).count(),
    1,
    "the plain button is back",
  );

  assert.equal(
    await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth),
    false,
    "no horizontal overflow at phone width",
  );

  // The new visual must preserve the ledger's full value: a bounded ring
  // must never hide overspending, recovery above the allowance, or a zero allowance.
  for (const sample of [
    { status: "green", penalty: 0, costs: [4], left: 6, fill: 60, level: "ready" },
    { status: "green", penalty: 0, costs: [7, 7], left: -4, fill: 0, level: "over" },
    { status: "green", penalty: 0, costs: [-3], left: 13, fill: 100, level: "ready" },
    { status: "red", penalty: 10, costs: [], left: 0, fill: 0, level: "empty" },
  ]) {
    // Unload the app before fixture writes: reload-time normalization may otherwise
    // save a newer revision between GET and PUT. The server must keep refusing stale writes.
    await page.goto(base + "/api/me");
    const result = await page.evaluate(async (sample) => {
      const now = new Date(),
        date = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`;
      const id = "d-" + date,
        docs = await (await fetch("/api/docs")).json();
      const body = {
        date,
        budget: 10,
        sleepPenalty: 3,
        status: sample.status,
        statusPenalty: sample.penalty,
        entries: sample.costs.map((c, i) => ({
          id: "visual-" + i,
          a: "Visual check " + i,
          c,
          t: "10:00",
        })),
      };
      const response = await fetch("/api/docs/" + id, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          "X-Requested-With": "jiggered",
          "If-Match": `"${docs[id].rev}"`,
        },
        body: JSON.stringify(body),
      });
      return { status: response.status, body: await response.text() };
    }, sample);
    assert.equal(result.status, 200, `sample accepted by the real document API: ${result.body}`);
    await page.goto(base + "/");
    await saved(page);
    assert.equal(
      Number((await page.locator("#left").textContent()).trim().split(/\s/)[0]),
      sample.left,
      "readout preserves the full balance",
    );
    assert.equal(
      Number(
        (await page.locator("#energy-progress").getAttribute("stroke-dasharray")).split(" ")[0],
      ),
      sample.fill,
      "ring reflects the allowance",
    );
    assert.equal(await page.locator("#energy-visual").getAttribute("data-level"), sample.level);
  }
  // Energy pills use individual entry IDs, even when activity names repeat.
  const logCustom = async (name, cost, time) => {
    await page.locator("#other-activity").click();
    await page.locator("#entry-name").fill(name);
    await page.locator("#entry-cost").fill(String(cost));
    await page.locator("#entry-time").fill(time);
    await page.locator('#entry-form button[type="submit"]').click();
    await saved(page);
  };
  assert.equal(
    await page.locator("#energy-activities").isVisible(),
    false,
    "empty days have no pill controls",
  );
  await logCustom("Rest & recover <quietly>", -3, "09:00");
  await logCustom("Rest & recover <quietly>", 0, "12:00");
  const pills = page.locator("#energy-activity-pills li");
  assert.equal(await pills.count(), 2);
  assert.match(await pills.first().textContent(), /Rest & recover <quietly>.*09:00.*\+3/);
  assert.equal(
    await pills.first().locator(".energy-activity-name").textContent(),
    "Rest & recover <quietly>",
    "names are escaped",
  );
  const firstId = await pills.first().locator('[data-action="edit"]').getAttribute("data-entry");
  const secondId = await pills.nth(1).locator('[data-action="edit"]').getAttribute("data-entry");
  assert.notEqual(firstId, secondId);
  await pills.first().locator('[data-action="edit"]').focus();
  await page.keyboard.press("Enter");
  assert.equal(
    await page.locator("#entry-time").inputValue(),
    "09:00",
    "keyboard edit opens the correct duplicate",
  );
  await page.locator("#entry-name").fill("A gentle recovery break");
  // The form says what the number will look like everywhere else: a cost of 2 shows as −2, a recovery of 2 as +2.
  await page.locator("#entry-cost").fill("2");
  assert.match(await page.locator("#entry-effect").textContent(), /Uses 2 points\. Shown as −2\./);
  await page.locator("#entry-cost").fill("-1");
  assert.match(
    await page.locator("#entry-effect").textContent(),
    /Gives back 1 point\. Shown as \+1\./,
  );
  await page.locator("#entry-cost").fill("0");
  assert.match(await page.locator("#entry-effect").textContent(), /Only records the activity/);
  await page.locator("#entry-cost").fill("-2");
  assert.match(await page.locator("#entry-effect").textContent(), /Shown as \+2\./);
  await page.locator('#entry-form button[type="submit"]').click();
  await saved(page);
  assert.match(await pills.first().textContent(), /A gentle recovery break/);
  assert.match(await pills.first().textContent(), /\+2/, "corrected costs update the pill");
  assert.match(await pills.nth(1).textContent(), /Rest & recover <quietly>/);
  await pills.first().locator('[data-action="remove"]').click();
  await saved(page);
  assert.equal(await pills.count(), 1);
  assert.equal(
    await pills.first().locator('[data-action="edit"]').getAttribute("data-entry"),
    secondId,
    "removal preserves the other duplicate",
  );
  assert.equal(
    await pills
      .first()
      .locator('[data-action="edit"]')
      .evaluate((el) => el === document.activeElement),
    true,
    "focus stays on a remaining pill",
  );
  await page.locator("#toastbar button", { hasText: "Undo removal" }).click();
  await saved(page);
  assert.equal(await pills.count(), 2);
  assert.equal(
    await pills.first().locator('[data-action="edit"]').getAttribute("data-entry"),
    firstId,
    "Undo restores entry identity and order",
  );
  await page.locator("#day-prev").click();
  assert.equal(await pills.count(), 0, "pills follow the selected day");
  await logCustom("Yesterday’s quiet walk", 2, "15:00");
  assert.match(await pills.first().textContent(), /Yesterday’s quiet walk/);
  await page.locator("#day-back").click();
  assert.equal(await pills.count(), 2, "returning to today restores its own pills");
  await logCustom("A long activity name that should stay within the energy card", 1, "13:45");
  for (const width of [320, 390, 1440]) {
    await page.setViewportSize({ width, height: 1000 });
    await page.emulateMedia({ colorScheme: width === 390 ? "dark" : "light" });
    assert.equal(
      await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth),
      false,
      `pills fit at ${width}px`,
    );
    assert.ok(
      await pills
        .last()
        .evaluate(
          (el) =>
            el.getBoundingClientRect().right <= el.parentElement.getBoundingClientRect().right + 1,
        ),
      "long names fit their card",
    );
    if (process.env.JIGGERED_SCREENSHOT_DIR) {
      fs.mkdirSync(process.env.JIGGERED_SCREENSHOT_DIR, { recursive: true });
      await page.locator(".energy-panel").screenshot({
        path: path.join(process.env.JIGGERED_SCREENSHOT_DIR, `energy-pills-${width}.png`),
      });
    }
  }
  await page.reload();
  await saved(page);
  assert.equal(await pills.count(), 3, "pills survive reload and sync");
  // An episode that is still going can be ended with one tap, and the length is worked out from when it started.
  const ongoing = await page.evaluate(async () => {
    const started = new Date(Date.now() - 2 * 3600_000);
    const p = (n) => String(n).padStart(2, "0");
    const when = `${started.getFullYear()}-${p(started.getMonth() + 1)}-${p(started.getDate())}T${p(started.getHours())}:${p(started.getMinutes())}`;
    const r = await fetch("/api/docs/e-1700000000001", {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
        "X-Requested-With": "jiggered",
        "If-None-Match": "*",
      },
      body: JSON.stringify({
        when,
        symptoms: ["Headache"],
        onset: "Sudden",
        duration: "Still going",
        before: [],
        notes: "",
      }),
    });
    return r.status;
  });
  assert.equal(ongoing, 200, "the ongoing episode was accepted");
  await page.reload();
  await saved(page);
  const banner = page.locator("#today-ongoing");
  await banner.waitFor();
  await banner.locator("[data-end-episode-now]").click();
  for (let i = 0, ended = false; !ended; i++) {
    assert.ok(i < 100, "the ended episode reaches the server");
    ended = await page.evaluate(async () => {
      const r = await fetch("/api/docs", { credentials: "same-origin" });
      const doc = (await r.json())["e-1700000000001"]?.body;
      return doc?.duration === "1–4 hours" && !!doc?.endedAt;
    });
    if (!ended) await page.waitForTimeout(100);
  }
  await banner.waitFor({ state: "hidden" }); // the banner goes once the episode has ended
  await page.locator("#t-history").click();
  assert.equal(await page.locator("#view-heading").textContent(), "History");
  await page.reload();
  await saved(page);
  assert.equal(
    await page.locator("#view-heading").textContent(),
    "History",
    "view heading survives a direct reload",
  );
  await page.emulateMedia({ reducedMotion: "reduce" });
  assert.equal(
    await page
      .locator("#energy-progress")
      .evaluate((el) => getComputedStyle(el).transitionDuration),
    "0s",
  );
  assert.deepEqual(errors, []);
  console.log(
    "PASS: Today: checklist, check-in/Undo, groups, activity controls, energy ring, per-entry pills/edit/remove/Undo, duplicate names, past days, mobile/dark layouts, view headings and reduced motion",
  );
}).catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

// Real-browser check of the Tools tab and Fretboard: open the tool, add a card by double-clicking and typing, drag
// it across the midline with a real mouse, use the right-click menu for its status and today's three, undo, marquee
// select several cards, and come back after a reload to the same board (it is a document, saved like any other).
// Needs Playwright (see the README); run with `node test/browser-tools.cjs`.
const assert = require("node:assert/strict");
const { runBrowser } = require("./support/browser.cjs");
const saved = (page) =>
  page.waitForFunction(() => document.querySelector("#sync")?.dataset.state === "saved");
const cardBox = async (page, text) => page.locator(".fb-item", { hasText: text }).boundingBox();

runBrowser({ name: "tools", portEnv: "JIGGERED_TOOLS_PORT" }, async (harness) => {
  const { base } = harness;
  const browser = await harness.launchBrowser();
  const context = await browser.newContext({ viewport: { width: 1280, height: 1500 } });
  const page = await context.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(e.message));

  await page.goto(base + "/login");
  await page.locator("#username").fill("tester");
  await page.locator("#password").fill("local-preview-password");
  await page.getByRole("button", { name: "Sign in", exact: true }).click();
  await page.locator("#acts details.act-group").first().waitFor();
  await saved(page);

  // The Tools tab lists Fretboard; opening it shows an empty board with its hint.
  await page.getByRole("tab", { name: "Tools" }).click();
  await page.locator('#tool-grid [data-tool="fretboard"]').click();
  await page.locator("#fb-canvas").waitFor();
  assert.ok(await page.locator("#fb-empty").isVisible(), "an empty board explains itself");
  assert.match(await page.locator("#tool-title").textContent(), /Fretboard/);
  await harness.screenshot(page, "tools-empty.png");

  // A real mouse click on the empty state's button loads the example (the canvas must not swallow it).
  await page.locator('[data-fb="example"]').click();
  await page.waitForFunction(() => document.querySelectorAll(".fb-item").length > 1);
  await page.locator('[data-fb="undo"]').click();
  await page.waitForFunction(() => document.querySelectorAll(".fb-item").length === 0);
  // The server copy must be empty again before the next step reads it.
  for (let i = 0, empty = false; !empty; i++) {
    assert.ok(i < 100, "the undone example reaches the server");
    empty = await page.evaluate(async () => {
      const r = await fetch("/api/docs", { credentials: "same-origin" });
      const body = (await r.json())["t-fretboard"]?.body;
      return !body || Object.keys(body.items || {}).length === 0;
    });
    if (!empty) await page.waitForTimeout(100);
  }

  // Double-click adds a card where the mouse is and starts typing straight away.
  await page.locator("#fb-canvas").scrollIntoViewIfNeeded();
  const canvas = await page.locator("#fb-canvas").boundingBox();
  await page.mouse.dblclick(canvas.x + canvas.width * 0.2, canvas.y + canvas.height * 0.3);
  await page.locator("textarea.fb-edit").waitFor();
  await page.keyboard.type("Sleep");
  await page.keyboard.press("Enter");
  await saved(page);
  const sleep = page.locator(".fb-item", { hasText: "Sleep" });
  await sleep.waitFor();
  assert.equal(await page.locator("#fb-empty").isVisible(), false);
  assert.match(await sleep.getAttribute("aria-label"), /Out of your hands, matters most/);

  // A card left empty is not kept.
  await page.mouse.dblclick(canvas.x + canvas.width * 0.7, canvas.y + canvas.height * 0.7);
  await page.locator("textarea.fb-edit").waitFor();
  await page.keyboard.press("Escape");
  await page.waitForFunction(() => document.querySelectorAll(".fb-item").length === 1);

  // Dragging with a real mouse moves it across the midline, and the saved position follows.
  let box = await cardBox(page, "Sleep");
  await page.mouse.move(box.x + 20, box.y + box.height / 2);
  await page.mouse.down();
  await page.mouse.move(box.x + 20 + canvas.width * 0.5, box.y + box.height / 2, { steps: 12 });
  await page.mouse.up();
  await saved(page);
  box = await cardBox(page, "Sleep");
  assert.ok(box.x > canvas.x + canvas.width * 0.5, "the card is now right of the midline");
  assert.match(await sleep.getAttribute("aria-label"), /In your hands, matters most/);
  // "saved" can read true before the drag's save is queued, so wait for the server to hold the move.
  const fetchStored = () =>
    page.evaluate(async () => {
      const r = await fetch("/api/docs", { credentials: "same-origin" });
      return (await r.json())["t-fretboard"]?.body;
    });
  let stored;
  for (let i = 0; i < 50; i++) {
    stored = await fetchStored();
    if (Object.values(stored?.items || {})[0]?.x > 0.5) break;
    await page.waitForTimeout(100);
  }
  const [, item] = Object.entries(stored.items)[0];
  assert.ok(item.x > 0.5 && item.t === "Sleep", "the server copy holds the moved card");

  // Right-click: status from the menu, then add it to today's three.
  await sleep.click({ button: "right" });
  await page.locator("#fb-menu").waitFor();
  await page.locator("#fb-menu button", { hasText: "In progress" }).click();
  await saved(page);
  assert.ok(await sleep.evaluate((el) => el.classList.contains("fb-s-doing")));
  await sleep.click({ button: "right" });
  await page.locator("#fb-menu button", { hasText: "Add to today's three" }).click();
  await saved(page);
  assert.equal(await page.locator("#fb-three li").count(), 1);
  assert.match(await page.locator("#fb-three li").textContent(), /Sleep/);
  await page.locator("#fb-three li input[type=checkbox]").check();
  await saved(page);
  assert.ok(await page.locator("#fb-three li.is-done").count(), "a ticked thing shows as done");

  // A typed thing joins the list and gets its own card in the top right; typing it again reuses that card.
  await page.locator("#fb-three-input").fill("Ten minutes outside");
  await page.locator("#fb-three-form button").click();
  await saved(page);
  assert.equal(await page.locator("#fb-three li").count(), 2);
  const outside = page.locator(".fb-item", { hasText: "Ten minutes outside" });
  assert.equal(await outside.count(), 1, "the typed thing is placed on the board");
  assert.match(await outside.getAttribute("aria-label"), /In your hands, matters most/);
  assert.equal(await page.locator("#fb-three [data-three-card]").count(), 2);
  await page.locator("#fb-three-input").fill("ten minutes outside");
  await page.locator("#fb-three-form button").click();
  await saved(page);
  assert.equal(await outside.count(), 1, "no second card for the same words");
  await page.locator("#fb-three li").nth(2).locator("[data-three-remove]").click();
  await saved(page);
  assert.equal(await page.locator("#fb-three li").count(), 2);

  // Choosing a status again clears it: "Not my problem" is a toggle, from the menu and from the keyboard.
  await sleep.click({ button: "right" });
  await page.locator("#fb-menu button", { hasText: "Not my problem" }).click();
  await saved(page);
  assert.ok(await sleep.evaluate((el) => el.classList.contains("fb-s-external")));
  await sleep.click({ button: "right" });
  assert.match(
    await page.locator("#fb-menu button", { hasText: "Not my problem" }).textContent(),
    /✓/,
  );
  await page.locator("#fb-menu button", { hasText: "Not my problem" }).click();
  await saved(page);
  assert.ok(
    await sleep.evaluate((el) => el.classList.contains("fb-s-todo")),
    "chosen again, it clears",
  );
  await sleep.click();
  await page.keyboard.press("4");
  await saved(page);
  assert.ok(await sleep.evaluate((el) => el.classList.contains("fb-s-external")));
  await page.keyboard.press("4");
  await saved(page);
  assert.ok(await sleep.evaluate((el) => el.classList.contains("fb-s-todo")), "4 again clears it");

  // The keyboard sets status and deletes, and Undo brings the card back.
  await sleep.click();
  await page.keyboard.press("3");
  await saved(page);
  assert.ok(await sleep.evaluate((el) => el.classList.contains("fb-s-done")));
  await page.keyboard.press("Delete");
  await saved(page);
  assert.equal(await page.locator(".fb-item").count(), 1);
  await page.locator("#toastbar button", { hasText: "Undo" }).click();
  await saved(page);
  assert.equal(await page.locator(".fb-item").count(), 2, "Undo restores the deleted card");

  // Toolbar buttons add more; a marquee over empty space selects everything it touches and arrows nudge them together.
  for (const name of ["Decking", "Weight"]) {
    await page.locator('[data-fb="add-card"]').click();
    await page.locator("textarea.fb-edit").waitFor();
    await page.keyboard.type(name);
    await page.keyboard.press("Enter");
    await saved(page);
  }
  assert.equal(await page.locator(".fb-item").count(), 4);
  await page.mouse.move(canvas.x + 4, canvas.y + 4);
  await page.mouse.down();
  await page.mouse.move(canvas.x + canvas.width - 4, canvas.y + canvas.height - 4, { steps: 8 });
  await page.mouse.up();
  assert.equal(
    await page.locator(".fb-item.is-selected").count(),
    4,
    "the marquee selected every card",
  );
  const before = await page.locator(".fb-item").evaluateAll((els) => els.map((e) => e.offsetTop));
  await page.keyboard.press("Shift+ArrowDown");
  await saved(page);
  const after = await page.locator(".fb-item").evaluateAll((els) => els.map((e) => e.offsetTop));
  assert.ok(
    after.every((t, i) => t > before[i]),
    "every selected card moved down together",
  );
  await page.keyboard.press("Escape");
  assert.equal(await page.locator(".fb-item.is-selected").count(), 0);

  // A press outside the canvas drops the selection; a press on the actions bar keeps it.
  await page.locator(".fb-item").first().click();
  assert.equal(await page.locator(".fb-item.is-selected").count(), 1);
  await page.locator("#fb-actions").click({ position: { x: 3, y: 3 } });
  assert.equal(await page.locator(".fb-item.is-selected").count(), 1, "the actions bar keeps it");
  await page.locator(".fb-legend-label").click();
  assert.equal(
    await page.locator(".fb-item.is-selected").count(),
    0,
    "outside the canvas clears it",
  );

  // Renaming an axis end is an inline edit; the legend hides a status without deleting anything.
  await page.locator('[data-axis="right"]').click();
  await page.locator(".fb-axis-input").fill("Controlled");
  await page.keyboard.press("Enter");
  await saved(page);
  assert.equal(await page.locator('[data-axis="right"]').textContent(), "Controlled");
  await page.locator('#fb-legend [data-status="todo"]').click();
  assert.equal(await page.locator(".fb-item.is-dimmed").count(), 3);
  await page.locator('#fb-legend [data-status="todo"]').click();
