  await phone.locator("#toastbar").filter({ hasText: "Couldn't save that" }).waitFor();
  await reload(phone);
  await phone.locator("#t-episode").click();
  assert.equal(await phone.locator("#ep-notes").inputValue(), "Retained refusal");
  assert.equal(
