const day = (status, entries = [], extra = {}) => ({ status, entries, budget: 10, ...extra });
const activity = (a, c) => ({ a, c });
const episode = (when, symptoms = [], before = []) => ({
  when,
  symptoms,
  before,
  duration: "Under 15 min",
});

test("history keeps unlogged gaps, recovery below zero and stamped historical allowances", () => {
  const docs = {
    "d-2026-09-28": day("amber", [activity("Work", 8), activity("Rest", -2)], {
      budget: 12,
      poorSleep: true,
      sleepPenalty: 2,
      statusPenalty: 3,
    }),
    "d-2026-09-29": day("green"),
    "d-2026-10-01": day("red", [activity("Rest", -4)]),
    "e-1": episode("2026-09-30T23:50", ["Fatigue"]),
  };
  const d = historyInsights(docs, { ...DEFAULTS, budget: 30 }, "2026-10-01", {
    from: "2026-09-28",
  });
  assert.equal(d.metrics.avgUsed, 1);
  assert.equal(d.metrics.avgAllowance, 8.5);
  assert.equal(d.metrics.spent, 8);
  assert.equal(d.metrics.recovery, 6);
  assert.equal(d.metrics.checked, 3);
  assert.deepEqual(
    d.buckets.map((b) => b.avgUsed),
    [6, null, null, -4],
