test("large histories have at most 60 buckets and preserve counts and averages", () => {
  const docs = {};
  for (let i = 0; i < 10000; i++) {
    const date = addDays("1999-01-01", i);
    docs["d-" + date] = day(i % 2 ? "red" : "green", [activity("Work", i % 3)]);
    docs["e-" + i] = episode(date + "T08:00", ["Fatigue"]);
  }
  const d = historyInsights(docs, DEFAULTS, "2026-10-01");
  assert.ok(d.buckets.length <= 60);
  assert.equal(d.metrics.checked, 10000);
  assert.equal(d.metrics.episodes, 10000);
  assert.equal(
    d.buckets.reduce((n, b) => n + b.checked, 0),
    10000,
  );
  assert.equal(
    d.buckets.reduce((n, b) => n + b.episodes, 0),
    10000,
  );
  assert.ok(d.buckets.every((b) => b.avgUsed === null || Number.isFinite(b.avgUsed)));
});

