test("calendar windows stay bounded, align Monday rows and retain gaps and episode-only days", () => {
  const d = historyInsights(
    {
      "d-2026-09-28": day("green", [activity("Rest", -2)]),
      "d-2026-09-29": day("amber"),
      "e-1": episode("2026-09-30T08:00"),
    },
    DEFAULTS,
    "2026-10-01",
    { from: "2020-01-01" },
  );
  const win = calendarWindow(d, DEFAULTS);
  assert.equal(win.cells.length, 366);
  assert.ok(win.weeks <= 54);
  assert.equal(win.from, "2025-10-01");
  const short = calendarWindow({ ...d, from: "2026-09-28" }, DEFAULTS);
  assert.equal(short.offset, 0);
  assert.equal(short.weeks, 1);
  assert.equal(short.cells[0].net, -2);
  assert.equal(short.cells[1].net, null);
  assert.equal(short.cells[2].logged, false);
  assert.equal(short.cells[2].episodes, 1);
  // "Matching" is only said when a filter is doing the matching.
  assert.match(
    describeCalendarDay(short.cells[2], "en-GB"),
    /No check-in\..*No activities logged.*1 episode recorded/,
  );
  assert.match(
    describeCalendarDay(short.cells[2], "en-GB", "points", true),
    /No matching check-in.*No activities logged.*1 matching episode/,
  );
  const older = calendarWindow(d, DEFAULTS, addDays(win.from, -1));
  assert.equal(older.to, "2025-09-30");
  assert.equal(older.cells.length, 366);
  const first = calendarWindow(d, DEFAULTS, d.from);
  assert.equal(first.cells.length, 1);
  assert.equal(first.from, d.from);
  const phone = calendarWindow(d, DEFAULTS, d.to, 91);
  assert.equal(phone.cells.length, 91);
  assert.ok(phone.weeks <= 14);
  assert.equal(phone.to, d.to);
});

