    "0999-01-01",
    "2026-1-1",
    "",
    null,
    undefined,
    5,
    "2026-10-01x",
  ]) {
    const direct =
      typeof v === "string" &&
      /^\d{4}-\d{2}-\d{2}$/.test(v) &&
      Number(v.slice(0, 4)) >= 1000 &&
