import test from "node:test";
import assert from "node:assert/strict";

process.env.TZ = "Europe/London";
const p = await import("../web/picker.js");
const m = await import("../web/model.js");

test("matches ignores case and accents and needs every word", () => {
  assert.ok(p.matches("cafe walk", "Walk to the Café"));
  assert.ok(p.matches("", "anything"));
  assert.ok(!p.matches("walk run", "Walk"));
});

const docs = {
  "d-2026-09-30": {
    entries: [
      { a: "Walk", c: -2, t: "09:00" },
      { a: "Call", c: 2, t: "10:00" },
    ],
  },
  "d-2026-09-29": {
    entries: [
      { a: "Walk", c: -2, t: "08:00" },
      { a: "Nap", c: -1, t: "14:00" },
    ],
  },
  "d-2026-01-01": { entries: [{ a: "Old", c: 1, t: "08:00" }] },
  "e-1": { when: "2026-09-30T08:00", symptoms: ["Dizzy"], before: ["Poor sleep"] },
};

test("usage counts recent use only, with the latest time", () => {
  const u = p.usage(docs, "2026-10-01");
  assert.equal(u.acts.get("Walk").n, 2);
  assert.equal(u.acts.get("Walk").last, "2026-09-30T09:00");
  assert.equal(u.acts.has("Old"), false);
  assert.equal(u.sym.get("Dizzy").n, 1);
  assert.equal(u.trig.get("Poor sleep").n, 1);
});

test("favourites put often-used names first, then the latest used", () => {
  const u = p.usage(docs, "2026-10-01").acts;
  assert.deepEqual(p.favourites(["Call", "Nap", "Walk", "Never"], u, 3), ["Walk", "Call", "Nap"]);
  assert.deepEqual(p.favourites(["Never"], u), []);
});

test("groupItems keeps list order, groups by first appearance and puts ungrouped last", () => {
  const items = [{ a: "1", g: "Home" }, { a: "2" }, { a: "3", g: "Work" }, { a: "4", g: "Home" }];
  const g = p.groupItems(items);
  assert.deepEqual(
    g.map((x) => [x.name, x.rows.map((r) => r.i)]),
    [
      ["Home", [0, 3]],
      ["Work", [2]],
      ["Ungrouped", [1]],
    ],
  );
  assert.deepEqual(
    p.groupItems([{ a: "x" }]).map((x) => x.name),
    [""],
  );
  assert.deepEqual(p.groupNames(items), ["Home", "Work"]);
});

test("settings keep an optional activity group and allow 200 items", () => {
  const s = m.normaliseSettings({
    activities: [
      { a: "A", c: 1, g: " Work " },
      { a: "B", c: 1, g: "  " },
    ],
  });
  assert.equal(s.activities[0].g, "Work");
  assert.equal("g" in s.activities[1], false);
  const many = Array.from({ length: 250 }, (_, i) => ({ a: "n" + i, c: 1 }));
  assert.equal(m.normaliseSettings({ activities: many }).activities.length, 200);
  assert.ok(
    m.validateSettings({
      ...m.normaliseSettings({}),
      activities: [{ a: "A", c: 1, g: "x".repeat(31) }],
    }).length > 0,
  );
});

test("a group change merges onto a newer copy without touching other fields", () => {
  const before = [{ id: "1", a: "A", c: 1 }],
    next = [{ id: "1", a: "A", c: 1, g: "Work" }],
    current = [{ id: "1", a: "A", c: 2 }];
  const out = m.applyOp(
    { type: "settingsPatch", arg: { activities: next }, before: { activities: before } },
    { activities: current },
  );
  assert.deepEqual(out.activities, [{ id: "1", a: "A", c: 2, g: "Work" }]);
});

test("selection pins logged activities in list order and counts repeats", () => {
  const rows = ["Walk", "Call", "Nap", "Cook"].map((a, i) => ({ item: { a, c: 1 }, i }));
  const entries = [{ a: "Nap" }, { a: "Walk" }, { a: "Nap" }, { a: "One-off other" }];
  const s = p.selection(rows, entries);
  assert.deepEqual(
    s.selected.map((r) => r.item.a),
    ["Walk", "Nap"],
    "list order, not the order they were logged",
  );
  assert.deepEqual(
    s.rest.map((r) => r.item.a),
    ["Call", "Cook"],
  );
  assert.equal(s.count.get("Nap"), 2);
  assert.equal(s.count.get("Walk"), 1);
  assert.equal(
    s.selected.length + s.rest.length,
    rows.length,
    "every row is in exactly one of the two",
  );
});

test("selection with nothing logged leaves the list alone", () => {
  const rows = [{ item: { a: "Walk" }, i: 0 }];
  assert.deepEqual(p.selection(rows, []).selected, []);
  assert.equal(p.selection(rows, undefined).rest.length, 1);
});

import test from "node:test";
import assert from "node:assert/strict";
import { applyOp, listDays, normaliseSettings } from "../web/model.js";
import {
  forecast,
  planId,
  plannedEntryId,
  energyFlow,
  planComparison,
} from "../web/planner-model.js";
const S = normaliseSettings({});
const date = "2026-10-03";
const work = { id: "work", a: "Deep focus", c: 8, t: "09:00" };
const rest = { id: "rest", a: "Quiet break", c: -3, t: "12:00" };
test("plans never create logged history days; recovery remains an estimate", () => {
  const docs = { [planId(date)]: { date, allowance: 6, entries: [work, rest] } };
  const f = forecast(docs, date, S);
  assert.equal(f.remaining, 6);
  assert.equal(f.afterWork, -2);
  assert.equal(f.projected, 1);
  assert.equal(f.shortfall, 2);
  assert.equal(f.gap, 0);
  assert.equal(listDays(docs).length, 0);
  assert.equal(forecast(docs, "2026-10-04", S).remaining, 10);
});
test("completion is idempotent and excludes the completed commitment using the actual cost", () => {
  const op = {
    id: "d-" + date,
    type: "addEntry",
    arg: { ...work, c: 5, id: plannedEntryId(date, work.id) },
    stamp: { budget: 10, sleepPenalty: 3 },
  };
  const day = applyOp(op);
  const twice = applyOp(op, day);
  assert.equal(twice.entries.length, 1);
  const docs = { [planId(date)]: { date, entries: [work, rest] }, ["d-" + date]: twice };
  const f = forecast(docs, date, S);
  assert.equal(f.done.length, 1);
  assert.equal(f.committed, 0);
  assert.equal(f.remaining, 5);
  assert.equal(f.projected, 8);
  assert.deepEqual(planComparison(docs, date), { total: 2, completed: 1, estimated: 8, actual: 5 });
  assert.equal(forecast({ ...docs, ["d-" + date]: { ...day, entries: [] } }, date, S).committed, 8);
});
test("logged check-ins and sleep supersede an estimated future allowance", () => {
  const docs = {
    [planId(date)]: { allowance: 9, entries: [work] },
    ["d-" + date]: {
      budget: 10,
      status: "amber",
      statusPenalty: 2,
      poorSleep: true,
      sleepPenalty: 3,
      entries: [{ c: -2 }],
    },
  };
  const f = forecast(docs, date, S);
  assert.equal(f.allowance, 5);
  assert.equal(f.remaining, 7);
  assert.equal(f.projected, -1);
  assert.deepEqual(energyFlow(f.day, S), { allowance: 5, spent: 0, recovered: 2, remaining: 7 });
});
test("planned operations replay and merge without losing other activities", () => {
  let body = applyOp({ id: planId(date), type: "addEntry", arg: work });
  body = applyOp({ id: planId(date), type: "addEntry", arg: rest }, body);
  body = applyOp({ id: planId(date), type: "addEntry", arg: work }, body);
  body = applyOp(
    { id: planId(date), type: "editEntry", arg: { id: "work", changes: { c: 4 } } },
    body,
  );
  assert.deepEqual(
    body.entries.map((x) => x.c),
    [4, -3],
  );
