  assert.equal(await d.store.load(), true);
  assert.deepEqual(ids(d.store.view(DAY)), ["e1"], "the refresh must not wipe it");
  await d.store.flush();
  assert.deepEqual(ids(s.docs.get(DAY).body), ["e1"]);
  assert.equal(d.store.status().pending, 0);
});

