func TestRegenerateRecoveryCodesInvalidatesOldOnes(t *testing.T) {
	e := newTestServer(t)
	c := e.newClient()
	c.login(adminName, adminPass)
	secret, codes := enableTestFactor(t, e, c, adminPass)
	// Another device is signed in; regenerating codes must sign it out.
	other := e.newClient()
