package main

import (
	"context"
	"database/sql"
	"errors"
	"log"
	"time"
)

type adminMutationKey struct{}

var errStaleAuthorization = errors.New("authorization changed; sign in and confirm again")

func guardMutation(ctx context.Context, tx *sql.Tx) error {
	if active, _ := ctx.Value(adminMutationKey{}).(bool); !active {
		return nil
	}
	a, _ := ctx.Value(authKey{}).(*authInfo)
	if a == nil || len(a.verified) == 0 {
		return errStaleAuthorization
	}
	var n int
	err := tx.QueryRowContext(ctx, `SELECT count(*) FROM users u JOIN sessions s ON s.user_id=u.id
        WHERE u.id=? AND u.role='admin' AND u.disabled=0 AND u.must_change_password=0
        AND u.password_hash=? AND s.token_hash=? AND s.sid=? AND s.expires_at>?`,
		a.u.ID, string(a.verified), a.hash, a.sid, time.Now().Unix()).Scan(&n)
	if err != nil {
		return err
	}
	if n != 1 {
		return errStaleAuthorization
	}
	return nil
}

var (
	errUserExists = errors.New("that username is taken")
	errNoUser     = errors.New("no such user")
	errLastAdmin  = errors.New("that would leave no active admin")
)

type user struct {
	ID         int64  `json:"id"`
	Username   string `json:"username"`
	Role       string `json:"role"`
	Disabled   bool   `json:"disabled"`
	MustChange bool   `json:"must_change_password"`
	CreatedAt  int64  `json:"created_at"`
	LastLogin  int64  `json:"last_login_at"` // 0 = never
}

// userStat is what an admin sees about an account: counts and sizes, never contents.
type userStat struct {
	user
	Docs          int   `json:"docs"`
	Bytes         int64 `json:"bytes"`
	Sessions      int   `json:"sessions"`
	RecoveryReady bool  `json:"recovery_ready"`
	TwoFactor     bool  `json:"two_factor"`
	RecoveryCodes int   `json:"recovery_codes_left"`
}

const userCols = "id, username, role, disabled, must_change_password, created_at, COALESCE(last_login_at, 0)"

type rowScanner interface{ Scan(dest ...any) error }

func scanUser(row rowScanner) (*user, error) {
	var u user
	var disabled, must int
	err := row.Scan(&u.ID, &u.Username, &u.Role, &disabled, &must, &u.CreatedAt, &u.LastLogin)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, errNoUser
	}
	if err != nil {
		return nil, err
	}
	u.Disabled, u.MustChange = disabled != 0, must != 0
	return &u, nil
}

func boolInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

// loginUser finds an account by (already normalised) name together with its
// bcrypt hash. An unknown name is (nil, nil, nil), not an error.
func (s *server) loginUser(ctx context.Context, name string) (*user, []byte, error) {
	if name == "" || len(name) > 64 {
		return nil, nil, nil
	}
	var hash string
	row := s.db.QueryRowContext(ctx, "SELECT "+userCols+", password_hash FROM users WHERE username = ?", name)
	var u user
	var disabled, must int
	err := row.Scan(&u.ID, &u.Username, &u.Role, &disabled, &must, &u.CreatedAt, &u.LastLogin, &hash)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, nil, nil
	}
	if err != nil {
		return nil, nil, err
	}
	u.Disabled, u.MustChange = disabled != 0, must != 0
	return &u, []byte(hash), nil
}

func (s *server) userByID(ctx context.Context, id int64) (*user, error) {
	return scanUser(s.db.QueryRowContext(ctx, "SELECT "+userCols+" FROM users WHERE id = ?", id))
}

func (s *server) userByName(ctx context.Context, name string) (*user, error) {
	return scanUser(s.db.QueryRowContext(ctx, "SELECT "+userCols+" FROM users WHERE username = ?", normUsername(name)))
}

func (s *server) passwordHash(ctx context.Context, id int64) ([]byte, error) {
	var h string
	err := s.db.QueryRowContext(ctx, "SELECT password_hash FROM users WHERE id = ?", id).Scan(&h)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, errNoUser
	}
	return []byte(h), err
}

func (s *server) createUser(ctx context.Context, name, hash, role string, mustChange bool) (*user, error) {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return nil, err
	}
	defer tx.Rollback()
	if err := guardMutation(ctx, tx); err != nil {
		return nil, err
	}
	var taken int
	if err := tx.QueryRowContext(ctx, "SELECT count(*) FROM users WHERE username = ?", name).Scan(&taken); err != nil {
		return nil, err
	}
	if taken > 0 {
		return nil, errUserExists
	}
	now := time.Now().Unix()
	res, err := tx.ExecContext(ctx, "INSERT INTO users(username, password_hash, role, must_change_password, created_at) VALUES(?, ?, ?, ?, ?)",
		name, hash, role, boolInt(mustChange), now)
	if err != nil {
		return nil, err
	}
	id, err := res.LastInsertId()
	if err != nil {
		return nil, err
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	return &user{ID: id, Username: name, Role: role, MustChange: mustChange, CreatedAt: now}, nil
}

func (s *server) listUsers(ctx context.Context) ([]userStat, error) {
	rows, err := s.db.QueryContext(ctx, `
		SELECT u.id, u.username, u.role, u.disabled, u.must_change_password, u.created_at, COALESCE(u.last_login_at, 0),
		  (SELECT count(*) FROM docs d WHERE d.user_id = u.id),
		  (SELECT COALESCE(sum(size), 0) FROM docs d WHERE d.user_id = u.id),
		  (SELECT count(*) FROM sessions s WHERE s.user_id = u.id AND s.expires_at > ?),
          EXISTS(SELECT 1 FROM account_security a WHERE a.user_id=u.id AND a.email IS NOT NULL AND a.email!=''),
          COALESCE((SELECT enabled FROM account_security a WHERE a.user_id=u.id),0),
          (SELECT count(*) FROM recovery_codes c WHERE c.user_id=u.id)
		FROM users u ORDER BY u.username`, time.Now().Unix())
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []userStat{}
	for rows.Next() {
		var st userStat
		var disabled, must int
		if err := rows.Scan(&st.ID, &st.Username, &st.Role, &disabled, &must, &st.CreatedAt, &st.LastLogin, &st.Docs, &st.Bytes, &st.Sessions, &st.RecoveryReady, &st.TwoFactor, &st.RecoveryCodes); err != nil {
			return nil, err
		}
		st.Disabled, st.MustChange = disabled != 0, must != 0
		out = append(out, st)
	}
	return out, rows.Err()
}

func (s *server) userCount(ctx context.Context) (int, error) {
	var n int
	err := s.db.QueryRowContext(ctx, "SELECT count(*) FROM users").Scan(&n)
	return n, err
}

// withUserTx loads the account inside a write transaction and hands it to fn,
// so checks like "is this the last admin" can't race with the change.
func (s *server) withUserTx(ctx context.Context, id int64, fn func(tx *sql.Tx, u *user) error) error {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()
	if err := guardMutation(ctx, tx); err != nil {
		return err
	}
	u, err := scanUser(tx.QueryRowContext(ctx, "SELECT "+userCols+" FROM users WHERE id = ?", id))
	if err != nil {
		return err
	}
	if err := fn(tx, u); err != nil {
		return err
	}
	return tx.Commit()
}

// guardLastAdmin refuses a change that would leave the instance with no active admin.
func guardLastAdmin(ctx context.Context, tx *sql.Tx, u *user) error {
	if u.Role != roleAdmin || u.Disabled {
		return nil
	}
	var others int
	if err := tx.QueryRowContext(ctx, "SELECT count(*) FROM users WHERE role = 'admin' AND disabled = 0 AND id != ?", u.ID).Scan(&others); err != nil {
		return err
	}
	if others == 0 {
		return errLastAdmin
	}
	return nil
}

// setPassword replaces the password and signs the account out everywhere except
// the session whose public id is keepSID ("" keeps none).
func (s *server) setPassword(ctx context.Context, id int64, hash string, mustChange bool, keepSID string) error {
	return s.withUserTx(ctx, id, func(tx *sql.Tx, _ *user) error {
		if _, err := tx.ExecContext(ctx, "UPDATE users SET password_hash = ?, must_change_password = ? WHERE id = ?", hash, boolInt(mustChange), id); err != nil {
			return err
		}
		for _, q := range []string{"DELETE FROM auth_tokens WHERE user_id = ?", "DELETE FROM login_challenges WHERE user_id = ?"} {
			if _, err := tx.ExecContext(ctx, q, id); err != nil {
				return err
			}
		}
		_, err := tx.ExecContext(ctx, "DELETE FROM sessions WHERE user_id = ? AND sid != ?", id, keepSID)
		return err
	})
}

func (s *server) setRole(ctx context.Context, id int64, role string) error {
	return s.withUserTx(ctx, id, func(tx *sql.Tx, u *user) error {
		if u.Role == role {
			return nil
		}
		if err := guardLastAdmin(ctx, tx, u); err != nil {
			return err
		}
		_, err := tx.ExecContext(ctx, "UPDATE users SET role = ? WHERE id = ?", role, id)
		return err
	})
}

// setDisabled blocks or restores sign-in. Disabling also ends every session.
func (s *server) setDisabled(ctx context.Context, id int64, disabled bool) error {
	return s.withUserTx(ctx, id, func(tx *sql.Tx, u *user) error {
		if u.Disabled == disabled {
			return nil
		}
		if disabled {
			if err := guardLastAdmin(ctx, tx, u); err != nil {
				return err
			}
			for _, q := range []string{"DELETE FROM auth_tokens WHERE user_id = ?", "DELETE FROM login_challenges WHERE user_id = ?"} {
				if _, err := tx.ExecContext(ctx, q, id); err != nil {
					return err
				}
			}
			if _, err := tx.ExecContext(ctx, "DELETE FROM sessions WHERE user_id = ?", id); err != nil {
				return err
			}
		}
		_, err := tx.ExecContext(ctx, "UPDATE users SET disabled = ? WHERE id = ?", boolInt(disabled), id)
		return err
	})
}

// deleteUser removes the account and, by cascade, all of its docs and sessions.
func (s *server) deleteUser(ctx context.Context, id int64) error {
	return s.withUserTx(ctx, id, func(tx *sql.Tx, u *user) error {
		if err := guardLastAdmin(ctx, tx, u); err != nil {
			return err
		}
		if err := eraseUsage(ctx, tx, id); err != nil {
			return err
		}
		_, err := tx.ExecContext(ctx, "DELETE FROM users WHERE id = ?", id)
		return err
	})
}

// revokeSessions ends the account's sessions except the one whose public id is
// exceptSID ("" ends them all) and says how many it ended.
func (s *server) revokeSessions(ctx context.Context, userID int64, exceptSID string) (int64, error) {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return 0, err
	}
	defer tx.Rollback()
	if err := guardMutation(ctx, tx); err != nil {
		return 0, err
	}
	res, err := tx.ExecContext(ctx, "DELETE FROM sessions WHERE user_id = ? AND sid != ?", userID, exceptSID)
	if err != nil {
		return 0, err
	}
	n, err := res.RowsAffected()
	if err != nil {
		return 0, err
	}
	return n, tx.Commit()
}

const (
	auditKeepFor = 180 * 24 * time.Hour
	auditMaxRows = 10000 // for each of the two kinds of event below
)

// auditSelfService matches the events a person can cause at will about themselves: signing in or failing to,
// changing their own password, signing their devices out, importing. They are kept under a cap of their own, so
// a flood of them can't push the record of what an admin did out of the log. Everything else (admin and
// command-line actions, settings, backups) has a cap that only an admin can fill.
const auditSelfService = `(action IN ('login', 'login_failed', 'login_refused', 'password_check_failed', 'password_changed', 'session_revoked', 'import', 'restore', 'account_deleted')
	OR (action = 'sessions_revoked' AND actor = target))`

// audit records who did what. Best effort: a failure to log never fails the request.
func (s *server) audit(ctx context.Context, actor, action, target, detail, ip string) {
	_, err := s.db.ExecContext(context.WithoutCancel(ctx),
		"INSERT INTO audit_log(at, actor, action, target, detail, ip) VALUES(?, ?, ?, ?, ?, ?)",
		time.Now().Unix(), actor, action, target, detail, ip)
	if err != nil {
		log.Printf("audit log: %v", err)
	}
}

// prune drops expired sessions and old audit entries (by age, and by count within each kind of event).
func (s *server) prune() {
	now := time.Now()
	s.db.Exec("DELETE FROM sessions WHERE expires_at < ?", now.Unix())
	s.db.Exec("DELETE FROM auth_tokens WHERE expires < ?", now.Unix())
	s.db.Exec("DELETE FROM login_challenges WHERE expires < ?", now.Unix())
	s.db.Exec("UPDATE account_security SET pending_secret='',pending_until=0 WHERE pending_until < ?", now.Unix())
	s.db.Exec("DELETE FROM audit_log WHERE at < ?", now.Add(-auditKeepFor).Unix())
	for _, kind := range []string{auditSelfService, "NOT " + auditSelfService} {
		s.db.Exec("DELETE FROM audit_log WHERE "+kind+" AND id <= (SELECT id FROM audit_log WHERE "+kind+" ORDER BY id DESC LIMIT 1 OFFSET ?)", auditMaxRows)
	}
}

// The checked credential and live calling session must still match when the password changes.
// Revoke every old token, including copies of the caller's cookie, and issue a new token atomically.
func (s *server) changePassword(ctx context.Context, a *authInfo, hash, ip, ua string) (string, time.Time, error) {
	token, err := randomHex(32)
	if err != nil {
		return "", time.Time{}, err
	}
	sid, err := randomHex(8)
	if err != nil {
		return "", time.Time{}, err
	}
	now := time.Now()
	exp := now.Add(sessionTTL)
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return "", time.Time{}, err
	}
	defer tx.Rollback()
	res, err := tx.ExecContext(ctx, `UPDATE users SET password_hash=?, must_change_password=0
 WHERE id=? AND password_hash=? AND disabled=0 AND EXISTS
 (SELECT 1 FROM sessions WHERE user_id=? AND token_hash=? AND sid=? AND expires_at>?)`,
		hash, a.u.ID, string(a.verified), a.u.ID, a.hash, a.sid, now.Unix())
	if err != nil {
		return "", time.Time{}, err
	}
	n, err := res.RowsAffected()
	if err != nil {
		return "", time.Time{}, err
	}
	if n != 1 {
		return "", time.Time{}, errStaleAuthorization
	}
	if _, err = tx.ExecContext(ctx, "DELETE FROM sessions WHERE user_id=?", a.u.ID); err != nil {
		return "", time.Time{}, err
	}
	for _, q := range []string{"DELETE FROM auth_tokens WHERE user_id=?", "DELETE FROM login_challenges WHERE user_id=?"} {
		if _, err = tx.ExecContext(ctx, q, a.u.ID); err != nil {
			return "", time.Time{}, err
		}
	}
	if _, err = tx.ExecContext(ctx, `INSERT INTO sessions(token_hash,sid,user_id,created_at,last_seen_at,expires_at,ip,user_agent) VALUES(?,?,?,?,?,?,?,?)`, hashToken(token), sid, a.u.ID, now.Unix(), now.Unix(), exp.Unix(), ip, cleanText(ua, 200)); err != nil {
		return "", time.Time{}, err
	}
	return token, exp, tx.Commit()
}

package main

import (
	"encoding/json"
	"fmt"
	"regexp"
	"strings"
	"time"
	"unicode/utf8"
)

// validateDoc is the one definition of a valid document. It checks the fields the app knows about and leaves everything
// else alone, so older records and fields from newer clients are accepted and kept exactly as sent. It runs on every
// way a document can arrive: a save (PUT), a legacy import, and a restore preview or commit. A save or an imported
// record that fails is refused; a restore with any failing record is rejected whole.
func validateDoc(id string, raw json.RawMessage) error {
	if !validDocID(id) || len(raw) > maxBodySize {
		return fmt.Errorf("unsupported record id or record too large")
	}
	var fields map[string]json.RawMessage
	if json.Unmarshal(raw, &fields) != nil || fields == nil {
		return fmt.Errorf("record must be a JSON object")
	}
	if id == "settings" {
		factory, _ := webFS.ReadFile("web/defaults.json")
		var d productDefaults
		json.Unmarshal(factory, &d)
		if err := json.Unmarshal(raw, &d); err != nil {
			return fmt.Errorf("settings field has the wrong type")
		}
		// A penalty the document leaves out falls back to its default, but never above the budget: that is how the
		// app reads a short settings document, so an older one such as {"budget":3} is valid.
		if _, ok := fields["sleepPenalty"]; !ok {
			d.SleepPenalty = min(d.SleepPenalty, d.Budget)
		}
		for name, p := range map[string]**int{"amberPenalty": &d.AmberPenalty, "redPenalty": &d.RedPenalty} {
			if _, ok := fields[name]; !ok && *p != nil {
				v := min(**p, d.Budget)
				*p = &v
			}
		}
		// A group set for a name that is no longer in the list is dropped when the app reads settings, and a renamed
		// item in the shared defaults leaves exactly that behind, so it is read the same way here, not refused.
		d.SymptomGroups = pruneGroups(d.SymptomGroups, d.Symptoms)
		d.TriggerGroups = pruneGroups(d.TriggerGroups, d.Triggers)
		return d.validate()
	}
	if strings.HasPrefix(id, "t-") {
		return validateToolDoc(fields)
	}
	var value map[string]any
	json.Unmarshal(raw, &value)
	for _, field := range []string{"when", "endedAt", "whenZone", "endZone", "notes", "onset", "duration", "date"} {
		if v, ok := value[field]; ok {
			if _, ok := v.(string); !ok {
				return fmt.Errorf("%s must be text", field)
			}
		}
	}
	for _, field := range []string{"symptoms", "before"} {
		if v, ok := value[field]; ok {
			list, ok := v.([]any)
			if !ok {
				return fmt.Errorf("%s must be a list", field)
			}
			for _, n := range list {
				if _, ok := n.(string); !ok {
					return fmt.Errorf("%s must contain text", field)
				}
			}
		}
	}
	for _, field := range []string{"when", "endedAt"} {
		if v, ok := value[field].(string); ok && v != "" {
			if _, err := time.Parse("2006-01-02T15:04", v); err != nil {
				if _, err := time.Parse("2006-01-02T15:04:05", v); err != nil {
					return fmt.Errorf("%s must be a valid local date and time", field)
				}
			}
		}
	}
	if strings.HasPrefix(id, "d-") || strings.HasPrefix(id, "p-") {
		if strings.HasPrefix(id, "p-") {
			n, exists := value["allowance"]
			if exists {
				v, ok := n.(float64)
				if !ok || v != float64(int(v)) || v < 1 || v > 30 {
					return fmt.Errorf("planned allowance must be a whole number from 1 to 30")
				}
			}
			if rows, ok := value["entries"].([]any); ok {
				if len(rows) > 200 {
					return fmt.Errorf("a day can contain at most 200 planned activities")
				}
				for _, row := range rows {
					e, ok := row.(map[string]any)
					if !ok {
						return fmt.Errorf("planned activity must be an object")
					}
					if id, ok := e["id"].(string); !ok || id == "" || len(id) > 200 {
						return fmt.Errorf("planned activity needs an id of 1–200 characters")
					}
					if err := validDuration(e); err != nil {
						return err
					}
					if v, ok := e["col"]; ok && v != nil {
						if col, ok := v.(string); !ok || len(col) > 20 {
							return fmt.Errorf("planned activity colour must be short text")
						}
					}
				}
			}
		}
		if v, ok := value["date"]; ok && v != id[2:] {
			return fmt.Errorf("date does not match record id")
		}
		if v, ok := value["status"]; ok && v != nil && v != "green" && v != "amber" && v != "red" {
			return fmt.Errorf("unknown check-in status")
		}
		if v, ok := value["poorSleep"]; ok {
			if _, ok := v.(bool); !ok {
				return fmt.Errorf("poorSleep must be true or false")
			}
		}
		for _, field := range []string{"budget", "sleepPenalty"} {
			if v, ok := value[field]; ok {
				n, ok := v.(float64)
				if !ok || n != float64(int(n)) || n < 0 || n > 30 || field == "budget" && n < 1 {
					return fmt.Errorf("%s must be a valid whole number", field)
				}
			}
		}
		if v, ok := value["entries"]; ok {
			list, ok := v.([]any)
			if !ok {
				return fmt.Errorf("entries must be a list")
			}
			ids := map[string]bool{}
			for _, entry := range list {
				e, ok := entry.(map[string]any)
				if !ok {
					return fmt.Errorf("activity must be an object")
				}
				a, ok := e["a"].(string)
				if !ok || strings.TrimSpace(a) == "" || utf8.RuneCountInString(a) > 60 {
					return fmt.Errorf("activity needs a name of 1–60 characters")
				}
				n, ok := e["c"].(float64)
				if !ok || n != float64(int(n)) || n < -10 || n > 10 {
					return fmt.Errorf("activity points must be a whole number from −10 to 10")
				}
				if v, ok := e["id"]; ok {
					id, ok := v.(string)
					if !ok || id == "" || ids[id] {
						return fmt.Errorf("activity ids must be distinct text")
					}
					ids[id] = true
				}
				if v, ok := e["t"]; ok {
					t, ok := v.(string)
					if !ok {
						return fmt.Errorf("activity time must be text")
					}
					if t != "" {
						if _, err := time.Parse("15:04", t); err != nil {
							return fmt.Errorf("activity time must be HH:MM or empty")
						}
					}
				}
				if err := validDuration(e); err != nil {
					return err
				}
			}
		}
	}
	return nil
}

// validDuration checks the optional length of a planned or logged activity: a whole number of minutes from 5 to 1440
// (null clears it, as the app does when a length is removed). With a start time the activity must also finish by
// midnight, so a day's calendar never has a block hanging off its end.
func validDuration(e map[string]any) error {
	v, ok := e["dur"]
	if !ok || v == nil {
		return nil
	}
	n, ok := v.(float64)
	if !ok || n != float64(int(n)) || n < 5 || n > 1440 {
		return fmt.Errorf("activity length must be a whole number of minutes from 5 to 1440")
	}
	if t, ok := e["t"].(string); ok && t != "" {
		start, err := time.Parse("15:04", t)
		if err != nil {
			return fmt.Errorf("activity time must be HH:MM or empty")
		}
		if start.Hour()*60+start.Minute()+int(n) > 1440 {
			return fmt.Errorf("activity must finish by midnight")
		}
	}
	return nil
}

// validateToolDoc bounds a Tools document. The frontend owns its shape (see web/fretboard-model.js); the server only
// refuses what could never be drawn: items that are not objects, text beyond the card limit, positions off the canvas,
// and more items than a board holds. Fields it does not know are kept as sent, so a newer client's board survives.
func validateToolDoc(fields map[string]json.RawMessage) error {
	if raw, ok := fields["items"]; ok {
		var items map[string]json.RawMessage
		if json.Unmarshal(raw, &items) != nil {
			return fmt.Errorf("items must be an object keyed by id")
		}
		if len(items) > 400 {
			return fmt.Errorf("a board can hold at most 400 items")
		}
		for id, raw := range items {
			if !toolItemID.MatchString(id) {
				return fmt.Errorf("item ids are 1–40 letters, digits, dashes or underscores")
			}
			var item struct {
				T *string  `json:"t"`
				X *float64 `json:"x"`
				Y *float64 `json:"y"`
			}
			if json.Unmarshal(raw, &item) != nil {
				return fmt.Errorf("item %s must be an object with text and a position", id)
			}
			if item.T != nil && utf8.RuneCountInString(*item.T) > 240 {
				return fmt.Errorf("item text is limited to 240 characters")
			}
			for _, n := range []*float64{item.X, item.Y} {
				if n != nil && (*n < 0 || *n > 1) {
					return fmt.Errorf("item positions are fractions of the canvas, from 0 to 1")
				}
			}
		}
	}
	if raw, ok := fields["three"]; ok {
		var three []map[string]any
		if json.Unmarshal(raw, &three) != nil {
			return fmt.Errorf("three must be a list")
		}
		if len(three) > 10 {
			return fmt.Errorf("the three-things list holds at most 10 entries")
		}
		for _, row := range three {
			if t, ok := row["t"]; ok {
				s, ok := t.(string)
				if !ok || utf8.RuneCountInString(s) > 240 {
					return fmt.Errorf("a three-things entry needs text of at most 240 characters")
				}
			}
		}
	}
	return nil
}

