}
/* History has one heading; its calendar and selected day carry the page. */
.app-shell .matrix-cell.green,
.app-shell .matrix-cell.recovery {
  --tone-bg: var(--matrix-green);
  --tone-ink: var(--matrix-status-ink);
}
.app-shell .matrix-cell.red {
  --tone-bg: var(--matrix-red);
  --tone-ink: var(--matrix-status-ink);
}
.app-shell .matrix-cell.amber {
