}
.app-shell #history-panel > details:not([open]) {
  padding-block: 10px;
}
/* A closed disclosure is only its summary: the panel's row gap would otherwise leave a blank strip beneath it, where
   the browser keeps the hidden content. */
.app-shell .history-disclosure:not([open]),
.app-shell .history-filter-panel:not([open]) {
  gap: 0;
}
.app-shell #history-panel > .history-intro {
