/* Administration: one focused workspace, with the same calm visual language. */
.app-shell #admin-panel,
.app-shell #account-panel {
  max-width: 1200px;
}
.account-workspace {
  margin-top: 20px;
}
.admin-workspace {
  display: grid;
  grid-template-columns: 248px minmax(0, 1fr);
  gap: 30px;
  align-items: start;
}
.admin-sidebar {
  position: sticky;
  top: 90px;
  padding: 24px 16px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--surface);
}
.admin-sidebar > h2 {
  margin: 0 10px 24px;
  font-size: 23px;
}
.admin-sidebar > .eyebrow {
  margin: 0 10px 8px;
}
.admin-nav {
  display: grid;
  gap: 6px;
}
.admin-nav button {
  display: flex;
  gap: 12px;
  align-items: center;
  width: 100%;
  min-height: 68px;
  padding: 12px 10px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: var(--fg);
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.admin-nav button:hover {
  background: var(--bg);
  border-color: var(--line);
}
.admin-nav button[aria-selected="true"] {
  background: var(--accent-soft);
  border-color: var(--line);
  box-shadow: inset 3px 0 var(--accent);
}
.admin-nav b {
  display: block;
  font-size: 14px;
}
.admin-nav small {
  display: block;
  margin-top: 3px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.35;
}
.admin-nav-number {
  color: var(--muted);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
.admin-nav-arrow {
  margin-left: auto;
  color: var(--accent);
  opacity: 0;
}
.admin-nav [aria-selected="true"] .admin-nav-arrow {
  opacity: 1;
}
.admin-nav-note {
  margin: 24px 10px 0;
  padding-top: 20px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 12px;
}
.admin-content {
  display: grid;
  gap: 20px;
  min-width: 0;
}
.admin-intro {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 0 6px;
}
.admin-intro h2 {
  margin: 8px 0 10px;
  font-size: clamp(26px, 3vw, 36px);
  letter-spacing: -0.04em;
  line-height: 1.15;
}
.admin-intro .meta {
  max-width: 48ch;
  margin: 0;
  line-height: 1.6;
}
.admin-intro .badge {
  flex-shrink: 0;
  margin-top: 28px;
}
.app-shell .admin-confirmation {
  padding: 16px 20px;
  background: var(--accent-soft);
}
.admin-confirmation label {
  font-size: 13px;
  font-weight: 700;
}
.admin-confirmation input {
  max-width: 360px;
  margin-top: 6px;
}
.admin-confirmation .hint {
  margin: 0;
  font-size: 12px;
}
.admin-section {
  min-width: 0;
  align-items: start;
}
.admin-section > .panel {
  min-width: 0;
}
.admin-section .people > li {
  display: grid;
  gap: 12px;
  padding-block: 18px;
}
.admin-user-actions {
  border-top: 1px solid var(--line);
}
.admin-user-actions summary {
  padding: 10px 0;
  min-height: 44px;
  color: var(--accent);
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
}
.admin-user-actions .actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding-bottom: 8px;
}
@media (min-width: 1180px) {
  #admin-section-people {
    grid-template-columns: minmax(0, 1.45fr) minmax(240px, 1fr);
  }
}
@media (max-width: 959px) {
  .admin-workspace {
    grid-template-columns: minmax(0, 1fr);
