.app-shell[data-view="admin"] .dashboard-masthead {
  padding-block: 28px 20px;
}
.app-shell[data-view="admin"] .dashboard-masthead h1 {
  font-size: clamp(28px, 3vw, 38px);
}
.app-shell[data-view="admin"] .dashboard-emblem {
  display: none;
}
.app-shell[data-view="admin"] .dashboard-eyebrow {
  margin-bottom: 10px;
}
@media (max-width: 520px) {
