// Tells a person when the shared defaults have items their own lists lack, and adds them in one tap.
// It only ever adds to the end of their lists. "Not now" is remembered until the shared defaults change again.
import { $, html, setHTML } from "./util.js";
import { defaultsGap, mergeDefaults, gapSignature, identifyActivities } from "./model.js";

const KEYS = ["activities", "symptoms", "triggers"];
const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;
export const describeGap = (gap) => {
  const parts = [
    gap.acts.length && plural(gap.acts.length, "activity", "activities"),
    gap.sym.length && plural(gap.sym.length, "symptom", "symptoms"),
    gap.trig.length && plural(gap.trig.length, "trigger", "triggers"),
  ].filter(Boolean);
  return parts.length > 1 ? `${parts.slice(0, -1).join(", ")} and ${parts.at(-1)}` : parts[0] || "";
};
export const previewGap = (gap, max = 4) => {
  const names = [...gap.acts.map((x) => x.a), ...gap.sym, ...gap.trig];
  return (
    names.slice(0, max).join(", ") + (names.length > max ? ` and ${names.length - max} more` : "")
  );
};

export function initDefaultsNotice(ctx, { canWrite }) {
  const el = $("defaults-notice"),
    dismissKey = `jiggered:defaults-dismissed:${ctx.me.id}`;
  const dismissed = () => {
    try {
      return localStorage.getItem(dismissKey);
    } catch {
      return null;
    }
  };
  const dismiss = (sig) => {
    try {
      localStorage.setItem(dismissKey, sig);
    } catch {
      /* only a convenience */
    }
  };
  const current = () => {
    if (!ctx.store.view("settings") || !canWrite()) return null;
    const gap = defaultsGap(ctx.settings(), ctx.defaults());
    return gap.total ? gap : null;
  };
  const pick = (S, keys) => Object.fromEntries(keys.map((k) => [k, S[k]]));

  function update() {
    const gap = current(),
      sig = gap && gapSignature(gap);
    if (!gap || dismissed() === sig) {
      if (!el.hidden) {
        el.hidden = true;
        el.replaceChildren();
      }
      return;
    }
    if (el.dataset.sig === sig && !el.hidden) return; // already showing this; don't rebuild under someone's finger
    el.dataset.sig = sig;
    setHTML(
      el,
      html`<p><b>New in the shared defaults:</b> your admin added ${describeGap(gap)} (<span class="meta">${previewGap(gap)}</span>). They go at the end of your lists; your own items, order and points don't change.</p><div class="row"><button class="primary small" data-notice="add">Add ${gap.total === 1 ? "it" : `all ${gap.total}`}</button><button class="secondary small" data-notice="review">Review</button><button class="secondary small" data-notice="later">Not now</button></div>`,
    );
    el.hidden = false;
  }

  el.addEventListener("click", (e) => {
    const b = e.target.closest("[data-notice]"),
      gap = current();
    if (!b || !gap) return;
    if (b.dataset.notice === "later") {
      dismiss(gapSignature(gap));
      update();
      return;
    }
    if (b.dataset.notice === "review") {
      ctx.editSettings("set-acts");
      return;
    }
    if (ctx.drafts?.get("settings")) {
      ctx.toast(
        "You have an unfinished settings draft in Account. Finish or discard it first, or review there.",
      );
      return;
    }
    const S = ctx.settings(),
      base = { ...S, activities: identifyActivities(S.activities) },
      merged = mergeDefaults(S, ctx.defaults());
    const keys = KEYS.filter((k) => JSON.stringify(merged[k]) !== JSON.stringify(base[k]));
    if (!keys.length) return;
    ctx.store.dispatch({
      id: "settings",
      type: "settingsPatch",
      arg: pick(merged, keys),
      before: pick(base, keys),
      original: base,
    });
    ctx.toast(`Added ${plural(gap.total, "item", "items")} to your lists.`, {
      label: "Undo",
      fn: () => {
        dismiss(gapSignature(gap)); // they chose not to have these: don't ask again
        ctx.store.dispatch({
          id: "settings",
          type: "settingsPatch",
          arg: pick(base, keys),
          before: pick(merged, keys),
          original: merged,
        });
      },
    });
  });

  return { update };
}

// One editing tab per browser profile. The browser releases the lock on close/crash;
// other tabs remain live readers without ever writing a stale cache/outbox snapshot.
export async function claimEditingTab(locks, name) {
  if (!locks?.request)
    return {
      writable: false,
      reason: "Editing needs a browser with Web Locks on HTTPS (or localhost).",
      close() {},
    };
  let release;
  const held = new Promise((resolve) => (release = resolve));
  let resolveClaim;
  const claimed = new Promise((resolve) => (resolveClaim = resolve));
  locks
    .request(name, { ifAvailable: true }, async (lock) => {
      resolveClaim({
        writable: !!lock,
        reason: lock
          ? ""
          : "Another Jiggered tab is editing. Close it, then reload this tab to edit here.",
        close: release,
      });
      if (lock) await held;
    })
    .catch(() =>
      resolveClaim({
        writable: false,
        reason: "Tab coordination is unavailable. Reload on HTTPS before editing.",
        close() {},
      }),
    );
  return claimed;
}

// A synchronous in-memory view backed by acknowledged IndexedDB transactions.
// The large cache/outbox lives here rather than competing with localStorage's small quota.
export const PURGE_KEY = "jiggered:purge-generation";

export async function openDeviceStorage({
  indexedDB = globalThis.indexedDB,
  legacy = null,
  userId = null,
  username = "",
  coordination = null,
} = {}) {
  let invalidated = false;
  const generation = legacy?.getItem(PURGE_KEY);
  const valid = () => !invalidated && legacy?.getItem(PURGE_KEY) === generation;
  const purgeLegacy = () => {
    if (!legacy) return;
    legacy.setItem(PURGE_KEY, `${Date.now()}:${Math.random()}`);
    for (let i = legacy.length - 1; i >= 0; i--) {
      const key = legacy.key(i);
      if (key?.startsWith("jiggered:") && key !== PURGE_KEY) legacy.removeItem(key);
    }
  };
  const fallback = () =>
    !coordination
      ? legacy
      : {
          get writable() {
            return coordination.writable && valid();
          },
          reason: coordination.reason,
          get length() {
            return valid() ? legacy?.length || 0 : 0;
          },
          key: (i) => (valid() ? legacy?.key(i) : null),
          getItem: (key) => (valid() ? (legacy?.getItem(key) ?? null) : null),
          setItem(key, value) {
            if (coordination.writable && valid()) legacy?.setItem(key, value);
          },
          removeItem(key) {
            if (coordination.writable && valid()) legacy?.removeItem(key);
          },
          purge: async () => purgeLegacy(),
        };
  if (!indexedDB) return fallback();
  let db;
  try {
    db = await new Promise((resolve, reject) => {
      const request = indexedDB.open("jiggered-device", 1);
      let expired = false;
      const timer = setTimeout(() => {
        expired = true;
        reject(new Error("Device storage is unavailable"));
      }, 6000);
      request.onupgradeneeded = () => {
        if (!request.result.objectStoreNames.contains("items"))
          request.result.createObjectStore("items");
      };
      request.onsuccess = () => {
        clearTimeout(timer);
        if (expired) request.result.close();
        else resolve(request.result);
      };
      request.onerror = () => {
        expired = true;
        clearTimeout(timer);
        reject(request.error);
      };
      request.onblocked = () => {
        expired = true;
        clearTimeout(timer);
        reject(new Error("Close another old Jiggered tab to open device storage"));
      };
    });
    const cache = await new Promise((resolve, reject) => {
      const tx = db.transaction("items", "readonly"),
        store = tx.objectStore("items");
      const keys = store.getAllKeys(),
        values = store.getAll();
      tx.oncomplete = () => resolve(new Map(keys.result.map((k, i) => [k, values.result[i]])));
      tx.onerror = tx.onabort = () =>
        reject(tx.error || new Error("Device storage could not be read"));
    });
    const channel =
      coordination && globalThis.BroadcastChannel
        ? new BroadcastChannel("jiggered-device-changes")
        : null;
    let onChange = () => {};
    async function refresh() {
      const fresh = await new Promise((resolve, reject) => {
        const tx = db.transaction("items", "readonly"),
          store = tx.objectStore("items");
        const keys = store.getAllKeys(),
          values = store.getAll();
        tx.oncomplete = () => resolve(new Map(keys.result.map((k, i) => [k, values.result[i]])));
        tx.onerror = tx.onabort = () => reject(tx.error);
      });
      cache.clear();
      for (const [k, v] of fresh) cache.set(k, v);
    }
    if (channel)
      channel.onmessage = async (event) => {
        if (event.data === "purged") {
          invalidated = true;
          cache.clear();
          onChange();
          return;
        }
        if (coordination.writable === false) {
          try {
            await refresh();
            onChange();
          } catch {
            /* retry when visible */
          }
        }
      };
    let tail = Promise.resolve();
    const write = (action, purge = false) => {
      const promise = tail.then(
        () =>
          new Promise((resolve, reject) => {
            if (!purge && !valid()) {
              reject(new Error("This device was signed out"));
              return;
            }
            const tx = db.transaction("items", "readwrite");
            action(tx.objectStore("items"));
            tx.oncomplete = () => {
              channel?.postMessage("changed");
              resolve();
            };
            tx.onerror = tx.onabort = () =>
              reject(tx.error || new Error("Device storage is full or unavailable"));
          }),
      );
      tail = promise.catch(() => {});
      return promise;
    };
    const retainedLegacy = new Map();
    const expectedKey = userId == null ? null : `jiggered:v1:${userId}:${username}`;
    const storage = {
      kind: "IndexedDB",
      get writable() {
        return (coordination?.writable ?? true) && valid();
      },
      reason: coordination?.reason || "",
      onChange(fn) {
        onChange = fn;
      },
      refresh,
      legacyCopies(id, name) {
        const value = retainedLegacy.get(`jiggered:v1:${id}:${name}`);
        return value ? [value] : [];
      },
      get length() {
        return cache.size;
      },
      key: (i) => [...cache.keys()][i] ?? null,
      getItem: (key) => (valid() ? (cache.get(key) ?? null) : null),
      setItem(key, value) {
        if (coordination?.writable === false || !valid()) return Promise.resolve();
        cache.set(key, value);
        return write((store) => store.put(value, key));
      },
      removeItem(key) {
        if (coordination?.writable === false || !valid()) return Promise.resolve();
        cache.delete(key);
        return write((store) => store.delete(key));
      },
      async purge() {
        purgeLegacy();
        invalidated = true;
        channel?.postMessage("purged");
        cache.clear();
        retainedLegacy.clear();
        await write((store) => store.clear(), true);
      },
      close() {
        channel?.close();
        db.close();
        coordination?.close();
      },
    };
    // Migrate only name-bound cache keys. Unnamed keys cannot be attributed safely after an instance restore.
    if (legacy && coordination?.writable !== false) {
      const keys = Array.from({ length: legacy.length }, (_, i) => legacy.key(i));
      for (const key of keys)
        if (key && /^jiggered:v1:\d+:.+/.test(key)) {
          try {
            if (expectedKey && key !== expectedKey) {
              legacy.removeItem(key);
              continue;
            }
            const old = legacy.getItem(key);
            // A still-open older build may have written new operations to localStorage after migration.
            // Do not pick one divergent outbox and silently throw the other away.
            if (cache.has(key) && cache.get(key) !== old) {
              retainedLegacy.set(key, old);
              continue;
            }
            if (!cache.has(key)) await storage.setItem(key, old);
            legacy.removeItem(key);
          } catch {
            /* retain the old copy until a later migration succeeds */
          }
        }
      if (expectedKey)
        for (const key of keys)
          if (key?.startsWith("jiggered:v1:") && !/^jiggered:v1:\d+:.+/.test(key)) {
            try {
              legacy.removeItem(key);
            } catch {
              /* never adopt an unbound identity */
            }
          }
    }
    return storage;
  } catch {
    if (db) db.close();
    return fallback(); // callers detect actual persistence failures and show memory-only warnings
  }
}

export function createDrafts({
  storage,
  userId,
  username,
  onError = () => {},
  now = () => Date.now(),
}) {
  const prefix = `jiggered:drafts:${userId}:${username}:`;
  const memory = new Map();
  const expiry = 7 * 24 * 60 * 60 * 1000;
  const remove = (key) => {
    if (storage?.writable === false) return;
    memory.delete(key);
    if (!storage) return;
    try {
      Promise.resolve(storage.removeItem(key)).catch(onError);
    } catch (e) {
      onError(e);
    }
  };
  if (storage)
    for (let i = storage.length - 1; i >= 0; i--) {
      const key = storage.key(i);
      if (key?.startsWith("jiggered:drafts:") && !key.startsWith(prefix)) remove(key);
    }
  if (storage)
    for (let i = storage.length - 1; i >= 0; i--) {
      const key = storage.key(i);
      if (key?.startsWith(prefix)) {
        try {
          const draft = JSON.parse(storage.getItem(key));
          if (now() - draft.at > expiry) remove(key);
          else memory.set(key, draft);
        } catch {
          remove(key);
        }
      }
    }
  const prune = () => {
    for (const [key, draft] of memory) if (now() - draft.at > expiry) remove(key);
  };
  return {
    get(name) {
      try {
        const draft = memory.get(prefix + name);
        if (!draft || typeof draft.at !== "number") return null;
        if (now() - draft.at > expiry) {
          remove(prefix + name);
          return null;
        }
        return draft.value;
      } catch {
        return null;
      }
    },
    put(name, value) {
      if (storage?.writable === false) return;
      const draft = { at: now(), value };
      memory.set(prefix + name, draft);
      if (!storage) {
        onError(
          new Error(
            "Draft is only in memory. Keep this page open and download recovery before leaving.",
          ),
        );
        return;
      }
      try {
        Promise.resolve(storage.setItem(prefix + name, JSON.stringify(draft))).catch(onError);
      } catch (e) {
        onError(e);
      }
    },
    remove(name) {
      remove(prefix + name);
    },
    list() {
      prune();
      return [...memory]
        .map(([key, draft]) => ({ name: key.slice(prefix.length), at: draft.at }))
        .sort((a, b) => b.at - a.at);
    },
    count() {
      prune();
      return memory.size;
    },
    export() {
      prune();
      return Object.fromEntries(
        [...memory].map(([key, draft]) => [key.slice(prefix.length), draft.value]),
      );
    },
    clear() {
      memory.clear();
      if (storage)
        for (let i = storage.length - 1; i >= 0; i--) {
          const key = storage.key(i);
          if (key?.startsWith(prefix)) remove(key);
        }
    },
  };
}

export async function purgeDeviceStorage(legacy = null) {
  const storage = await openDeviceStorage({ legacy });
  try {
    if (globalThis.indexedDB && storage?.kind !== "IndexedDB")
      throw new Error("Could not clear IndexedDB");
    if (storage?.purge) await storage.purge();
    else if (legacy) {
      legacy.setItem(PURGE_KEY, `${Date.now()}:${Math.random()}`);
      for (let i = legacy.length - 1; i >= 0; i--) {
        const key = legacy.key(i);
        if (key?.startsWith("jiggered:") && key !== PURGE_KEY) legacy.removeItem(key);
      }
    }
  } finally {
    storage?.close?.();
  }
}

// Runs as the page is parsed, before the first paint and before the app has started (the app waits on the network).
// The page ships showing Today, so without this a refresh on another tab flashes Today and then jumps. This applies
// the tab named in the address to the markup that is already here; app.js does the real navigation afterwards.
// A tab that doesn't exist yet (Admin is added later) or an unknown name leaves the page as it is.
(function () {
  history.scrollRestoration = "manual";
  var tab = "",
    saved;
  try {
    var me = JSON.parse(localStorage.getItem("jiggered:me") || "null");
    if (me)
      saved = JSON.parse(
        sessionStorage.getItem("jiggered:view:" + me.id + ":" + me.username) || "null",
      );
    var appearance = saved?.v === 1 && saved.views?.appearance;
    if (appearance && ["light", "dark"].includes(appearance.theme))
      document.documentElement.dataset.theme = appearance.theme;
    if (appearance && ["points", "spoons"].includes(appearance.energyTheme))
      document.documentElement.dataset.energyTheme = appearance.energyTheme;
  } catch {}
  try {
    tab = decodeURIComponent(location.hash.slice(1));
  } catch {}
  if (!tab && saved?.v === 1) tab = saved.views?.nav?.tab || "";
  var panel = document.getElementById(tab + "-panel");
  if (!panel || panel.tagName !== "SECTION" || !document.getElementById("t-" + tab)) return;
  document.body.dataset.view = tab;
  var intro = document.getElementById("t-" + tab).dataset;
  document.getElementById("view-heading").textContent = intro.heading;
  document.getElementById("view-description").textContent = intro.description;
  document.querySelectorAll("section[id$=-panel]").forEach(function (s) {
    s.hidden = s !== panel;
  });
  document.querySelectorAll("#tabs button").forEach(function (b) {
    var on = b.dataset.tab === tab;
    b.setAttribute("aria-selected", on);
    b.tabIndex = on ? 0 : -1;
  });
})();

// Shared personal/default settings editor. Ordering works with pointer, touch, keyboard or buttons.
import { applyEnergyTheme, energyCopy } from "./energy-theme.js";
