  )}<datalist id="${prefix}-groups-acts"></datalist><datalist id="${prefix}-groups-sym"></datalist><datalist id="${prefix}-groups-trig"></datalist>${prefix === "set" ? html`<p class="hint" data-gap hidden></p>` : ""}<p class="sr-only" role="status" data-order-status></p><div class="row sticky-save"><button class="primary" type="submit">Save ${prefix === "def" ? "shared defaults" : "settings"}</button><button class="secondary" type="button" data-discard>Discard draft</button>${prefix === "set" ? html`<button class="secondary" type="button" data-merge>Add new shared items</button>` : ""}<button class="secondary" type="button" data-reset>${prefix === "def" ? "Use factory defaults" : "Replace with shared defaults"}</button></div><p class="msg" id="${prefix}-msg" role="status"></p>`;
