export function createEditor(form, prefix, onChange = () => {}, getTheme = () => "points") {
  const get = (key) => form.querySelector(`#${prefix}-${key}`);
  // Anything that sends the person to a field (a shortcut, a validation error) first opens the section holding it.
  const reveal = (el) => {
    for (let d = el?.closest("details"); d; d = d.parentElement?.closest("details")) d.open = true;
  };
  const row = (key, name = "", cost = 1, id = uid(), group = "") =>
    html`<div class="order-row" data-row data-id="${id}"><button type="button" class="drag-handle" aria-label="Move ${name || "item"}; arrow keys reorder" title="Drag to reorder; arrow keys also work">⠿</button><input type="text" value="${name}" aria-label="${key === "acts" ? "Activity" : key === "sym" ? "Symptom" : "Trigger"} name" placeholder="Name">${key === "acts" ? html`<input class="order-cost" type="number" min="-10" max="10" step="1" value="${cost}" ${prefix === "set" ? html`data-energy-label="Points it costs"` : ""} aria-label="Points it costs" required>` : ""}<input class="order-group" type="text" maxlength="30" list="${prefix}-groups-${key}" value="${group}" aria-label="Group (optional)" placeholder="Group"><div class="order-actions"><button type="button" data-move="-1" class="x" aria-label="Move up">↑</button><button type="button" data-move="1" class="x" aria-label="Move down">↓</button><button type="button" data-remove class="x" aria-label="Remove ${name || "item"}">×</button></div></div>`;
  function syncGroups() {
    for (const key of ["acts", "sym", "trig"]) {
      const dl = get("groups-" + key);
      if (dl)
        setHTML(
          dl,
          html`${[...new Set([...get(key).querySelectorAll(".order-group")].map((i) => i.value.trim()).filter(Boolean))].map((g) => html`<option value="${g}">`)}`,
        );
    }
  }
  // name -> group for the rows that have one; keyed by the trimmed name, which is what the settings store
  function groupsOfRows(key) {
    const out = {};
    for (const r of get(key).children) {
      const [name, group] = r.querySelectorAll("input"),
        n = name.value.trim(),
        g = group.value.trim();
      if (n && g) out[n] = g;
    }
    return out;
  }
  // A list inside a collapsed section keeps its rows and values; only the count says what is in it.
  function refresh(list) {
    const count = form.querySelector(`[data-count="${list.dataset.list}"]`);
    if (count) count.textContent = `(${list.children.length})`;
    [...list.children].forEach((r, i) => {
      r.querySelector('[data-move="-1"]').disabled = i === 0;
      r.querySelector('[data-move="1"]').disabled = i === list.children.length - 1;
      r.querySelector(".drag-handle").setAttribute(
        "aria-label",
        `Move ${r.querySelector("input").value || "item"}, position ${i + 1} of ${list.children.length}; arrow keys reorder`,
      );
    });
  }
  function reposition(r, index) {
    const list = r.parentElement,
      rows = [...list.children],
      old = rows.indexOf(r);
    index = Math.max(0, Math.min(rows.length - 1, index));
    if (index === old) return;
    const rects = new Map(rows.map((el) => [el, el.getBoundingClientRect().top]));
    const ordered = moveItem(rows, old, index);
    list.replaceChildren(...ordered);
    refresh(list);
    if (!globalThis.matchMedia?.("(prefers-reduced-motion: reduce)").matches)
      for (const el of rows) {
        const delta = rects.get(el) - el.getBoundingClientRect().top;
        if (delta && el.animate)
          el.animate([{ transform: `translateY(${delta}px)` }, { transform: "translateY(0)" }], {
            duration: 160,
            easing: "ease-out",
          });
      }
    form.querySelector("[data-order-status]").textContent =
      `${r.querySelector("input").value || "Item"} moved to position ${index + 1}.`;
    onChange();
  }
  form.addEventListener("input", () => {
    for (const list of form.querySelectorAll("[data-list]")) refresh(list);
    syncGroups();
    onChange();
  });
  form.addEventListener("click", (e) => {
    const add = e.target.closest("[data-add]"),
      remove = e.target.closest("[data-remove]"),
      move = e.target.closest("[data-move]");
    if (add) {
      const list = get(add.dataset.add);
      if (list.children.length >= LIMITS.items) {
        get("msg").textContent = `Keep at most ${LIMITS.items} items in each list.`;
        return;
      }
      const template = document.createElement("template");
      setHTML(template, row(add.dataset.add));
      list.append(template.content);
      applyEnergyTheme(getTheme(), form);
      refresh(list);
      list.lastElementChild.querySelector("input").focus();
      onChange();
    }
    if (remove) {
      const list = remove.closest("[data-list]");
      remove.closest("[data-row]").remove();
      refresh(list);
      onChange();
    }
    if (move) {
      const r = move.closest("[data-row]");
      reposition(r, [...r.parentElement.children].indexOf(r) + Number(move.dataset.move));
      r.querySelector(".drag-handle").focus();
    }
  });
  form.addEventListener("keydown", (e) => {
    if (
      !e.target.closest(".drag-handle") ||
      !["ArrowUp", "ArrowDown", "Home", "End"].includes(e.key)
    )
      return;
    e.preventDefault();
    const r = e.target.closest("[data-row]"),
      list = r.parentElement,
      i = [...list.children].indexOf(r);
    reposition(
      r,
      e.key === "Home"
