  form.addEventListener("pointerdown", (e) => {
    const handle = e.target.closest(".drag-handle");
    if (!handle || e.button !== 0) return;
    const r = handle.closest("[data-row]"),
      list = r.parentElement,
      startX = e.clientX,
      startY = e.clientY;
    const originalIndex = [...list.children].indexOf(r),
      slots = [...list.children].map((row) => {
        const rect = row.getBoundingClientRect();
        return rect.top + rect.height / 2 + window.scrollY;
      });
    let ghost = null,
      frame = null,
      lastY = startY,
      lastX = startX;
    const position = () => {
      const rect = list.getBoundingClientRect();
      if (lastX < rect.left - 40 || lastX > rect.right + 40) return;
      const y = lastY + window.scrollY;
      let index = 0;
      for (let i = 1; i < slots.length; i++)
        if (Math.abs(slots[i] - y) < Math.abs(slots[index] - y)) index = i;
      reposition(r, index);
    };
    const scroll = () => {
      if (ghost) {
        if (lastY < 80) window.scrollBy(0, -10);
        else if (lastY > window.innerHeight - 80) window.scrollBy(0, 10);
        position();
        frame = requestAnimationFrame(scroll);
      }
    };
    const move = (event) => {
      if (event.pointerId !== e.pointerId) return;
      lastY = event.clientY;
      lastX = event.clientX;
      if (!ghost && Math.hypot(event.clientX - startX, event.clientY - startY) < 6) return;
      event.preventDefault();
      if (!ghost) {
        ghost = r.cloneNode(true);
        ghost.classList.add("drag-preview");
        ghost.setAttribute("aria-hidden", "true");
        ghost.inert = true;
        const rect = r.getBoundingClientRect();
        ghost.style.width = rect.width + "px";
        document.body.append(ghost);
        r.classList.add("drop-placeholder");
        frame = requestAnimationFrame(scroll);
      }
      ghost.style.left = event.clientX - 20 + "px";
      ghost.style.top = event.clientY - 20 + "px";
      position();
    };
    const finish = (event) => {
      if (event.pointerId !== e.pointerId) return;
      document.removeEventListener("pointermove", move);
      document.removeEventListener("pointerup", finish);
      document.removeEventListener("pointercancel", finish);
      document.removeEventListener("keydown", escape);
