      if (ghost) {
        const stop = (event) => {
          event.preventDefault();
          event.stopPropagation();
        };
        handle.addEventListener("click", stop, { once: true });
      }
    };
    const escape = (event) => {
      if (event.key === "Escape") {
        event.preventDefault();
        finish({ pointerId: e.pointerId, type: "pointercancel" });
      }
    };
