        ...S,
        symptomGroups: S.symptomGroups ?? DEFAULTS.symptomGroups,
        triggerGroups: S.triggerGroups ?? DEFAULTS.triggerGroups,
      }; // a draft saved before groups existed has no maps: start from the defaults, not from none
      get("budget").value = S.budget;
      get("penalty").value = S.sleepPenalty;
      get("amber").value = S.amberPenalty ?? DEFAULTS.amberPenalty;
      get("red").value = S.redPenalty ?? DEFAULTS.redPenalty;
      get("locale").value = S.locale;
      for (const [key, items] of [
        ["acts", identifyActivities(S.activities)],
        ["sym", S.symptoms],
        ["trig", S.triggers],
      ]) {
        setHTML(
          get(key),
          html`${items.map((x) => row(key, typeof x === "string" ? x : x.a, x.c, x.id, typeof x === "string" ? ((key === "sym" ? S.symptomGroups : S.triggerGroups) && Object.hasOwn(key === "sym" ? S.symptomGroups : S.triggerGroups, x) ? (key === "sym" ? S.symptomGroups : S.triggerGroups)[x] : "") : x.g || ""))}`,
        );
