        sleepPenalty: get("penalty").value,
        amberPenalty: get("amber").value,
        redPenalty: get("red").value,
        locale: get("locale").value,
        activities: [...get("acts").children].map((r) => ({
          id: r.dataset.id,
          a: r.querySelector("input").value,
          c: r.querySelectorAll("input")[1].value,
          ...(r.querySelectorAll("input")[2].value.trim()
            ? { g: r.querySelectorAll("input")[2].value.trim() }
            : {}),
        })),
        symptoms: [...get("sym").children].map((r) => r.querySelector("input").value),
        triggers: [...get("trig").children].map((r) => r.querySelector("input").value),
        symptomGroups: groupsOfRows("sym"),
        triggerGroups: groupsOfRows("trig"),
      };
    },
    validate() {
      const value = this.read(),
        errors = validateSettings(value);
