      }
      return normaliseSettings(value);
    },
    focus(key) {
      const el = get(key.replace("set-", ""));
      reveal(el);
      el?.scrollIntoView({ block: "center", behavior: "smooth" });
      (el?.matches("input,select") ? el : el?.querySelector("input"))?.focus();
    },
  };
}

import { html, setHTML, signed } from "./util.js";
