const previous = new WeakMap();
export function renderEnergyFlow(ctx, day, settings) {
  const f = energyFlow(day, settings),
    word = (n) => energyAmount(n, themeOf(ctx));
  const last = previous.get(ctx);
  if (
    last?.date === day.date &&
    last.remaining !== f.remaining &&
    !matchMedia("(prefers-reduced-motion: reduce)").matches
  ) {
    document
      .getElementById("energy-visual")
      .animate(
        [{ transform: "scale(1)" }, { transform: "scale(1.025)" }, { transform: "scale(1)" }],
        { duration: 360, easing: "ease-out" },
      );
  }
  previous.set(ctx, { date: day.date, remaining: f.remaining });
  setHTML(
    document.getElementById("energy-breakdown"),
    html`<dl class="energy-breakdown"><div><dt>Starting allowance</dt><dd>${f.allowance}</dd></div><div class="is-spending"><dt>Used</dt><dd>${signed(f.spent)}</dd></div><div class="is-recovery"><dt>Recovered</dt><dd>${signed(-f.recovered)}</dd></div><div><dt>Remaining</dt><dd>${f.remaining}</dd></div></dl><p class="sr-only">${word(f.allowance)} to start, ${word(f.spent)} used, ${word(f.recovered)} recovered, ${word(f.remaining)} remaining.</p>`,
  );
  let balance = f.allowance;
  const changes = day.entries.map((e) => {
    balance -= e.c;
    return { ...e, balance };
  });
  const recent = changes.slice(-5);
  const startingBalance = changes.length > 5 ? changes[changes.length - 6].balance : f.allowance;
  const wasOpen = document.querySelector("#energy-flow details")?.open;
  setHTML(
    document.getElementById("energy-flow"),
    html`<details><summary>How your energy changed${changes.length ? ` · ${changes.length} activities` : ""}</summary><ol class="energy-flow-list"><li><span>${changes.length > 5 ? "Before the latest 5 activities" : "Starting allowance"}</span><b>${startingBalance}</b></li>${recent.map((e) => html`<li class="${e.c < 0 ? "is-recovery" : "is-spending"}"><span>${e.a}<small>${e.t || "Time not set"}${e.c === 0 ? " · recorded only" : e.c < 0 ? ` · +${word(-e.c)} recovered` : ` · −${word(e.c)} used`}</small></span><b>${e.balance}<small>left</small></b></li>`)}</ol>${changes.length > 5 ? html`<p class="hint">Showing the latest 5 changes. The full activity log is below.</p>` : ""}</details>`,
  );
  document.querySelector("#energy-flow details").open = !!wasOpen;
}

// Presentation only. Saved budgets, activity costs and export fields always keep their original values.
export const energyTheme = (profile) => (profile?.energyTheme === "spoons" ? "spoons" : "points");
export const energyWords = (theme) =>
  theme === "spoons"
    ? { singular: "spoon", plural: "spoons", title: "Spoons" }
    : { singular: "point", plural: "points", title: "Points" };
export const energyAmount = (n, theme) =>
  `${n} ${Math.abs(n) === 1 ? energyWords(theme).singular : energyWords(theme).plural}`;
// Only for application-authored energy copy, never names, notes, search queries or graph data points.
export const energyCopy = (text, theme) =>
  theme === "spoons"
    ? text.replace(
        /\b[Pp]oints?\b/g,
        (word) =>
          (word[0] === "P" ? "S" : "s") + (word.toLowerCase() === "point" ? "poon" : "poons"),
      )
    : text;
export const themeOf = (ctx) => energyTheme(ctx.store?.view("settings")?.profile);

export function applyEnergyTheme(theme, root = document) {
  for (const el of root.querySelectorAll("[data-energy-copy]")) {
    const text = energyCopy(el.dataset.energyCopy, theme);
    if (el.textContent !== text) el.textContent = text;
  }
  for (const el of root.querySelectorAll("[data-energy-tooltip]"))
    el.dataset.tooltip = energyCopy(el.dataset.energyTooltip, theme);
  for (const el of root.querySelectorAll("[data-energy-label]"))
    el.setAttribute("aria-label", energyCopy(el.dataset.energyLabel, theme));
}

