      const here = link.getAttribute("href") || "";
      link.href = open ? (here.startsWith("/register") ? here : "/register") : "/login"; // keep ?w=spoons
      link.firstChild.textContent = open ? "Create your free account " : "Log in ";
    });
  })
  .catch(() => {
