  "Under 15 min",
  "15–60 min",
  "1–4 hours",
  "4–12 hours",
  "Most of a day",
  "Over a day",
  "Ended (duration unknown)",
];
export const ADVICE = {
  green: "A good starting point. There’s still room for pauses.",
  amber: "Somewhere in between. A little breathing space may help.",
  red: "A low-energy starting point. Take the day at your own pace.",
};
// "" means whatever the browser uses.
export const LOCALES = [
  ["en-GB", "English (UK)"],
  ["en-US", "English (US)"],
  ["en-AU", "English (Australia)"],
  ["en-CA", "English (Canada)"],
  ["de-DE", "Deutsch"],
  ["fr-FR", "Français"],
  ["es-ES", "Español"],
  ["nl-NL", "Nederlands"],
  ["", "Browser default"],
];

export const LIMITS = { budget: [1, 30], cost: [-10, 10], items: 200, text: 60, group: 30 };

// ---- dates ----

export const pad = (n) => String(n).padStart(2, "0");
export const dkey = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
export const hhmm = (d) => `${pad(d.getHours())}:${pad(d.getMinutes())}`;
export const nowLocal = (d = new Date()) => `${dkey(d)}T${hhmm(d)}`;
export const dayId = (key) => "d-" + key;
export const isDayId = (id) => /^d-\d{4}-\d{2}-\d{2}$/.test(id);
export const isEpisodeId = (id) => /^e-\d+$/.test(id);
export const isToolId = (id) => /^t-[a-z][a-z0-9-]{0,30}$/.test(id);

export function addDays(key, n) {
  const [y, m, d] = key.split("-").map(Number);
  return dkey(new Date(y, m - 1, d + n));
}

// ---- settings ----

const text = (s, n = LIMITS.text) =>
  typeof s === "string" ? [...s.trim()].slice(0, n).join("") : "";
const int = (v, lo, hi, dflt) => {
  const n = Math.round(Number(v));
  return Number.isFinite(n) && n >= lo && n <= hi ? n : dflt;
};
const names = (v, dflt) =>
  Array.isArray(v)
    ? [...new Set(v.map((x) => text(x)).filter(Boolean))].slice(0, LIMITS.items)
    : [...dflt];

// A name-to-group map keeps only names still in the list and groups that are real text. No map at all means the
// defaults; a map that is present, even an empty one, is the person's own choice.
const groupsOf = (raw, list, dflt) => {
  const src = raw && typeof raw === "object" && !Array.isArray(raw) ? raw : dflt;
  return Object.fromEntries(
    list
      .filter((n) => Object.hasOwn(src, n) && text(src[n], LIMITS.group))
      .map((n) => [n, text(src[n], LIMITS.group)]),
  );
};

// normaliseSettings turns whatever is stored (or typed) into valid settings, falling back to the
// defaults for anything missing. A list that is present but empty stays empty.
export function normaliseSettings(raw) {
  const r = raw && typeof raw === "object" ? raw : {};
  const budget = int(r.budget, ...LIMITS.budget, DEFAULTS.budget);
  const activities = Array.isArray(r.activities)
    ? r.activities
        .map((x) => ({
          ...(typeof x?.id === "string" ? { id: x.id } : {}),
          a: text(x && x.a),
          c: int(x && x.c, ...LIMITS.cost, NaN),
          ...(text(x && x.g, LIMITS.group) ? { g: text(x && x.g, LIMITS.group) } : {}),
        }))
        .filter((x) => x.a && Number.isFinite(x.c))
        .slice(0, LIMITS.items)
    : DEFAULTS.activities.map((x) => ({ ...x }));
  const symptoms = names(r.symptoms, DEFAULTS.symptoms),
    triggers = names(r.triggers, DEFAULTS.triggers);
  return {
    budget,
    sleepPenalty: int(r.sleepPenalty, 0, budget, Math.min(DEFAULTS.sleepPenalty, budget)),
    amberPenalty: int(r.amberPenalty, 0, budget, Math.min(DEFAULTS.amberPenalty, budget)),
    redPenalty: int(r.redPenalty, 0, budget, Math.min(DEFAULTS.redPenalty, budget)),
    locale:
      typeof r.locale === "string" && LOCALES.some(([v]) => v === r.locale)
        ? r.locale
        : DEFAULTS.locale,
    activities,
    symptoms,
    triggers,
    symptomGroups: groupsOf(r.symptomGroups, symptoms, DEFAULTS.symptomGroups),
    triggerGroups: groupsOf(r.triggerGroups, triggers, DEFAULTS.triggerGroups),
  };
}

// resolveSettings is what the app shows for a person: their stored settings over the shared defaults. Groups for
// symptoms and triggers are decided per name, so an item with no group of its own takes the shared defaults' group
// for that name, while a group they chose themselves always wins.
export function resolveSettings(raw, shared) {
  const own = raw && typeof raw === "object" ? raw : {},
    base = shared || {};
  const maps = Object.fromEntries(
    ["symptomGroups", "triggerGroups"].map((k) => [
      k,
      { ...(base[k] || {}), ...(own[k] && typeof own[k] === "object" ? own[k] : {}) },
    ]),
  );
  return normaliseSettings({ ...base, ...own, ...maps });
}

// ---- a day ----

export const emptyDay = (key) => ({ date: key, status: null, poorSleep: false, entries: [] });
export const used = (d) => (d.entries || []).reduce((s, e) => s + (e.c || 0), 0);
// The one definition of "average net points" for the graphs and the printed summary: days with at least one activity
// count, a day that only has a check-in does not (nothing was recorded to average).
export const activityDays = (days) => days.filter((d) => (d.entries || []).length);
export const averageNet = (days) => {
  const logged = activityDays(days);
  return logged.length
    ? Math.round((logged.reduce((s, d) => s + used(d), 0) / logged.length) * 10) / 10
    : null;
};
// Days remember the budget they were made under, so changing your settings doesn't rewrite history.
// A day's points: its budget, less the poor-sleep cost and less what its check-in took off (stamped on the day when the
// check-in was chosen, so days from before check-ins cost anything keep the numbers they had).
export const capOf = (d, S) =>
  Math.max(
    0,
    (d.budget ?? S.budget) -
      (d.poorSleep ? (d.sleepPenalty ?? S.sleepPenalty) : 0) -
      (d.statusPenalty || 0),
  );

// ---- operations ----
// Edits are operations rather than whole-doc snapshots, so they can be replayed on top of a newer copy
// from the server. Each is safe to apply twice (a retried save must not add an entry twice).

// Deterministic legacy identities let independent devices migrate the same rows consistently.
export function identifyEntries(entries = []) {
  return (Array.isArray(entries) ? entries : []).map((e, i) =>
    e.id ? e : { ...e, id: `legacy-entry:${i}:${JSON.stringify([e.a, e.c, e.t])}` },
  );
}
export const identifyActivities = (rows) =>
  (Array.isArray(rows) ? rows : []).map((e) =>
    e.id ? e : { ...e, id: `legacy-activity:${encodeURIComponent(e.a)}` },
  );
// Compared by value, not by the order keys happen to be written in: {id,a} and {a,id} are the same row.
const canon = (v) =>
  Array.isArray(v)
    ? v.map(canon)
    : v && typeof v === "object"
      ? Object.fromEntries(
          Object.keys(v)
            .sort()
            .map((k) => [k, canon(v[k])]),
        )
      : v;
const equal = (a, b) => JSON.stringify(canon(a)) === JSON.stringify(canon(b));
// defaultsGap lists what the shared defaults have that a person's own lists lack, matched by name and ignoring case.
// It never looks at points or groups of items they already have, so their own choices are not second-guessed.
const same = (a, b) =>
  String(a).trim().toLocaleLowerCase() === String(b).trim().toLocaleLowerCase();
export function defaultsGap(mine, shared) {
  const missing = (have, want, nameOf) =>
    (want || []).filter((w) => !(have || []).some((h) => same(nameOf(h), nameOf(w))));
  const acts = missing(mine?.activities, shared?.activities, (x) => x.a),
    sym = missing(mine?.symptoms, shared?.symptoms, (x) => x),
    trig = missing(mine?.triggers, shared?.triggers, (x) => x);
  return { acts, sym, trig, total: acts.length + sym.length + trig.length };
}
// mergeDefaults adds the missing shared items to the end of each list and changes nothing else.
export function mergeDefaults(mine, shared) {
  const gap = defaultsGap(mine, shared);
  const grouped = (names, from, own) => ({
    ...Object.fromEntries(names.filter((n) => from?.[n]).map((n) => [n, from[n]])),
    ...own,
  }); // new items arrive in their shared group
  return {
    ...mine,
    activities: [...identifyActivities(mine.activities), ...identifyActivities(gap.acts)],
    symptoms: [...mine.symptoms, ...gap.sym],
    triggers: [...mine.triggers, ...gap.trig],
    symptomGroups: grouped(gap.sym, shared.symptomGroups, mine.symptomGroups),
    triggerGroups: grouped(gap.trig, shared.triggerGroups, mine.triggerGroups),
  };
}
// gapSignature is a short stable string for a gap, so "not now" can be remembered until the shared defaults change again.
export const gapSignature = (gap) =>
  [...gap.acts.map((x) => x.a), ...gap.sym, ...gap.trig]
    .map((x) => x.trim().toLocaleLowerCase())
    .sort()
    .join("|");

export function operationConflicts(op, body) {
  if (!op.before) return [];
  if (body == null) return ["deleted record"];
  if (op.type === "editEntry") {
    const current = identifyEntries(body.entries).find((e) => e.id === op.arg.id);
    if (!current) return ["deleted activity"];
    return Object.keys(op.arg.changes).filter(
      (k) => !equal(current[k], op.before[k]) && !equal(current[k], op.arg.changes[k]),
    );
  }
  const GROUPS = ["symptomGroups", "triggerGroups"];
  const fields = Object.keys(op.arg).filter((k) => k !== "activities" && !GROUPS.includes(k));
  // A settings field the server copy has never had (an older account) can't have been changed by anyone else.
  const conflicts = fields.filter(
    (k) =>
      !(op.type === "settingsPatch" && body[k] === undefined) &&
      !equal(body[k], op.before[k]) &&
      !equal(body[k], op.arg[k]),
  );
  // Group maps are compared name by name: a name the stored copy doesn't list is unchanged, not a conflict.
  for (const k of GROUPS)
    if (op.type === "settingsPatch" && op.arg[k]) {
      for (const name of new Set([...Object.keys(op.arg[k]), ...Object.keys(op.before[k] || {})])) {
        const mine = op.arg[k][name],
          was = op.before[k]?.[name],
          now = body[k]?.[name];
        if (now !== undefined && now !== was && now !== mine) {
          conflicts.push(k);
          break;
        }
      }
    }
  if (op.type === "settingsPatch" && op.arg.activities) {
    const current = identifyActivities(body.activities || []),
      before = identifyActivities(op.before.activities || []),
      next = op.arg.activities;
    for (const row of before) {
      const n = next.find((x) => x.id === row.id),
        c = current.find((x) => x.id === row.id);
      if (!n || !c) {
        if (!equal(n, row) && !equal(c, row) && !equal(c, n)) conflicts.push(`activity: ${row.a}`);
      } else
        for (const k of ["a", "c", "g"])
          if (!equal(n[k], row[k]) && !equal(c[k], row[k]) && !equal(c[k], n[k]))
            conflicts.push(
              `activity: ${row.a} (${k === "a" ? "name" : k === "g" ? "group" : "points"})`,
            );
    }
    const common = new Set(
      before
        .filter((x) => current.some((c) => c.id === x.id) && next.some((n) => n.id === x.id))
        .map((x) => x.id),
    );
    const order = (rows) => rows.filter((x) => common.has(x.id)).map((x) => x.id);
    if (
      !equal(order(next), order(before)) &&
      !equal(order(current), order(before)) &&
      !equal(order(current), order(next))
    )
      conflicts.push("activity order");
  }
  return conflicts;
}
function mergeActivities(current, before, next) {
  const old = identifyActivities(before || []),
    rows = identifyActivities(current || []);
  const deleted = old.filter((x) => !next.some((n) => n.id === x.id)).map((x) => x.id);
  const out = rows
    .filter((x) => !deleted.includes(x.id))
    .map((x) => {
      const n = next.find((n) => n.id === x.id),
        b = old.find((b) => b.id === x.id);
      if (!n) return x;
      const merged = {
        ...x,
        ...Object.fromEntries(Object.entries(n).filter(([k, v]) => !equal(v, b?.[k]))),
      };
      if (b?.g !== undefined && n.g === undefined && x.g === b.g) delete merged.g;
      return merged;
    });
  for (const n of next)
    if (!old.some((b) => b.id === n.id) && !out.some((x) => x.id === n.id)) out.push(n);
  if (
    !equal(
      next.map((x) => x.id),
      old.map((x) => x.id),
    )
  ) {
    const rank = new Map(next.map((x, i) => [x.id, i]));
    out.sort((a, b) => (rank.get(a.id) ?? next.length) - (rank.get(b.id) ?? next.length));
  }
  return out;
}
const sameEntry = (x, y) =>
  x.id && y.id ? x.id === y.id : x.a === y.a && x.c === y.c && x.t === y.t;

const DAY_OPS = {
  setStatus: (d, v, op) => {
    const { statusPenalty: _previousPenalty, ...rest } = d,
      took =
        v === "amber" || v === "red" ? Math.max(0, Number(op?.stamp?.[v + "Penalty"]) || 0) : 0;
    return { ...rest, status: v || null, ...(took ? { statusPenalty: took } : {}) };
  },
  setPoorSleep: (d, v) => ({ ...d, poorSleep: !!v }),
  addEntry: (d, e) =>
    d.entries.some((x) => x.id && x.id === e.id) ? d : { ...d, entries: [...d.entries, e] },
  removeEntry: (d, e) => {
    const i = d.entries.findIndex((x) => sameEntry(x, e));
    return i < 0 ? d : { ...d, entries: d.entries.filter((_, j) => j !== i) };
  },
  editEntry: (d, arg) => ({
    ...d,
    entries: identifyEntries(d.entries).map((e) =>
      e.id === arg.id ? { ...e, ...arg.changes, id: e.id } : e,
    ),
  }),
  restoreEntry: (d, arg) => {
    const entries = identifyEntries(d.entries);
    if (entries.some((e) => e.id === arg.entry.id)) return d;
    entries.splice(Math.min(arg.index, entries.length), 0, arg.entry);
    return { ...d, entries };
  },
  restamp: (d, s) => ({ ...d, budget: s.budget, sleepPenalty: s.sleepPenalty }),
};

// applyOp returns the doc after the operation, or undefined if the doc is gone.
export function applyOp(op, body) {
  if (op.type === "remove") return undefined;
  if (op.type === "replace") return op.arg;
  if (op.type === "settingsPatch") {
    const { activities, ...fields } = op.arg;
    return {
      ...(body || {}),
      ...fields,
      ...(activities
        ? { activities: mergeActivities(body?.activities, op.before?.activities, activities) }
        : {}),
    };
  }
  if (op.type === "patch") return { ...(body || {}), ...op.arg };
  if (op.type === "boardPatch") return applyBoardPatch(op.arg, body);
  const fn = DAY_OPS[op.type];
  if (!fn) throw new Error("unknown operation " + op.type);
  let d = body ?? emptyDay(op.id.slice(2));
  if (!Array.isArray(d.entries)) d = { ...d, entries: [] };
  if (d.budget === undefined && op.stamp && op.type !== "restamp")
    d = { ...d, budget: op.stamp.budget, sleepPenalty: op.stamp.sleepPenalty };
  if (["editEntry", "removeEntry", "restoreEntry"].includes(op.type))
    d = { ...d, entries: identifyEntries(d.entries) };
  return fn(d, op.arg, op);
}

// ---- reading the docs ----

export function readableDay(raw, date) {
  const d = raw && typeof raw === "object" ? raw : {};
  return {
    ...d,
    date,
    status: ["green", "amber", "red"].includes(d.status) ? d.status : null,
    entries: Array.isArray(d.entries)
      ? d.entries
          .filter((e) => e && Number.isFinite(e.c))
          .map((e) => ({
            ...e,
            a: typeof e.a === "string" ? e.a : "",
            t: typeof e.t === "string" ? e.t : "",
          }))
      : [],
  };
}
// A stored document keeps the same object from one render to the next until it is edited, so its readable copy is made
// once and reused: on a large account every keystroke in History otherwise rebuilt thousands of identical copies.
// Nothing mutates these copies (callers that reorder take a fresh array from listDays/listEpisodes each time).
const readableCache = new WeakMap();
const readableOf = (stored, make) => {
  if (stored === null || typeof stored !== "object") return make();
  let copy = readableCache.get(stored);
  if (copy === undefined) {
    copy = make();
    readableCache.set(stored, copy);
  }
  return copy;
};

export function listDays(docs) {
  return Object.entries(docs)
    .filter(([k, v]) => isDayId(k) && v)
    .map(([id, v]) => readableOf(v, () => readableDay(v, id.slice(2))))
    .sort((a, b) => b.date.localeCompare(a.date));
}

export function listEpisodes(docs) {
  return Object.entries(docs)
    .filter(([k]) => isEpisodeId(k))
    .filter(([, v]) => v && typeof v.when === "string")
    .map(([id, v]) => [id, readableOf(v, () => readableEpisode(v))])
    .sort((a, b) => b[1].when.localeCompare(a[1].when));
}

const top = (counts, n) =>
  [...counts].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, n);
const tally = (lists) => {
  const m = new Map();
  for (const l of lists) for (const x of new Set(l || [])) if (x) m.set(x, (m.get(x) || 0) + 1);
  return m;
};

// trends summarises the last `window` days ending today.
export function trends(docs, S, today, window = 30) {
  const from = addDays(today, -(window - 1));
  const days = listDays(docs).filter((d) => d.date >= from && d.date <= today);
  const count = (s) => days.filter((d) => d.status === s).length;
  const checked = days.filter((d) => d.status);
  const sleepy = days.filter((d) => d.poorSleep);
  const since = (n) => addDays(today, -(n - 1)) + "T00:00";
  const eps = listEpisodes(docs).map(([, e]) => e);
  const recent90 = eps.filter((e) => e.when >= since(90) && e.when < addDays(today, 1) + "T00:00");
  return {
    window,
    green: count("green"),
    amber: count("amber"),
    red: count("red"),
    unchecked: window - checked.length,
    avgUsed: days.length
      ? Math.round((days.reduce((s, d) => s + used(d), 0) / days.length) * 10) / 10
      : null,
    poorSleepDays: sleepy.length,
    poorSleepBad: sleepy.filter((d) => d.status === "amber" || d.status === "red").length,
    episodes30: eps.filter((e) => e.when >= since(30) && e.when < addDays(today, 1) + "T00:00")
      .length,
    episodes90: recent90.length,
    topTriggers: top(tally(recent90.map((e) => e.before)), 3),
    topSymptoms: top(tally(recent90.map((e) => e.symptoms)), 3),
  };
}

// ---- CSV ----

// Cells starting with = + - @ would run as formulas if someone opens the file in a spreadsheet.
export const csvCell = (v) => {
  let s = v == null ? "" : String(v);
  if (typeof v === "string" && /^[=+\-@\t\r]/.test(s)) s = "'" + s; // numbers like -2 are not formulas
  return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
};
const csv = (rows) => rows.map((r) => r.map(csvCell).join(",")).join("\r\n") + "\r\n";

export function daysCsv(docs, S) {
  // One convention in every export: a cost is the energy spent (positive) or recovered (negative, written as
  // "recovered"). points_used is spent minus recovered; the two columns after "activities" give each side.
  const rows = [
    [
      "date",
      "check_in",
      "poor_sleep",
      "points_used",
      "points_available",
      "activities",
      "points_spent",
      "points_recovered",
    ],
  ];
  for (const d of listDays(docs).reverse()) {
    rows.push([
      d.date,
      d.status || "",
      d.poorSleep ? "yes" : "no",
      used(d),
      capOf(d, S),
      (d.entries || [])
        .map(
          (e) =>
            `${e.t ? e.t + " " : ""}${e.a} (${e.c > 0 ? "spent " + e.c : e.c < 0 ? "recovered " + -e.c : "no change"})`,
        )
        .join("; "),
      (d.entries || []).reduce((n, e) => n + Math.max(0, e.c), 0),
      (d.entries || []).reduce((n, e) => n + Math.max(0, -e.c), 0),
    ]);
  }
  return csv(rows);
}

export function episodesCsv(docs, { includeNotes = true } = {}) {
  const rows = [
    [
      "started",
      "symptoms",
      "how_it_came_on",
      "how_long",
      "in_the_day_or_two_before",
      "notes",
      "ended_local",
      "start_time_zone",
      "start_utc_offset_minutes",
      "end_time_zone",
      "end_utc_offset_minutes",
    ],
  ];
  for (const [, e] of listEpisodes(docs).reverse()) {
    rows.push([
      e.when,
      (e.symptoms || []).join("; "),
      e.onset || "",
      e.duration || "",
      (e.before || []).join("; "),
      includeNotes ? e.notes || "" : "Omitted",
      e.endedAt || "",
      e.whenZone || "",
      e.whenOffset ?? "",
      e.endZone || "",
      e.endOffset ?? "",
    ]);
  }
  return csv(rows);
}

// ---- clinician summary ----

export const RANGES = [
  ["30", "Last 30 days"],
  ["90", "Last 90 days"],
  ["365", "Last year"],
  ["all", "Everything"],
];

export function summary(docs, S, range, today) {
  // History supplies its exact dates and filters. Keep legacy preset callers on the same calculation.
  const filters = range && typeof range === "object" ? range : {};
  const all = range === "all" || (typeof range === "object" && !filters.from);
  const from = filters.from || (all ? "0000-00-00" : addDays(today, -(Number(range) - 1)));
  const to = filters.to || today;
  const selected = selectHistory(docs, { ...filters, from, to });
  const days = selected.days;
  const episodes = selected.episodes.map(([, e]) => e);
  const count = (s) => days.filter((d) => d.status === s).length;
  return {
    from: all
      ? [today, ...days.map((d) => d.date), ...episodes.map((e) => e.when.slice(0, 10))].sort()[0]
      : from,
    to,
    days,
    episodes,
    green: count("green"),
    amber: count("amber"),
    red: count("red"),
    avgUsed: averageNet(days),
    activityDays: activityDays(days).length,
    poorSleepDays: days.filter((d) => d.poorSleep).length,
    topTriggers: top(tally(episodes.map((e) => e.before)), 5),
    topSymptoms: top(tally(episodes.map((e) => e.symptoms)), 5),
  };
}

// Editor validation is separate from defensive reading: never silently trim a person's unfinished work.
export function validateSettings(r) {
  const errors = [];
  const integer = (v, lo, hi) =>
    String(v).trim() !== "" && Number.isInteger(Number(v)) && Number(v) >= lo && Number(v) <= hi;
  if (!integer(r.budget, ...LIMITS.budget))
    errors.push(["set-budget", "Choose a whole-number budget from 1 to 30."]);
  for (const [key, field, label] of [
    ["amberPenalty", "set-amber", "An amber day"],
    ["redPenalty", "set-red", "A red day"],
  ]) {
    if (r[key] !== undefined && !integer(r[key], 0, Number(r.budget)))
      errors.push([
        field,
        `${label} costs a whole number of points between zero and your daily budget.`,
      ]);
  }
  if (!integer(r.sleepPenalty, 0, Number(r.budget)))
    errors.push([
      "set-penalty",
      "Poor sleep costs must be a whole number between zero and your daily budget.",
    ]);
  if (!LOCALES.some(([v]) => v === r.locale))
    errors.push(["set-locale", "Choose a supported date format."]);
  for (const [key, field, label] of [
    ["activities", "set-acts", "activities"],
    ["symptoms", "set-sym", "symptoms"],
    ["triggers", "set-trig", "triggers"],
  ]) {
    const values =
      key === "activities"
        ? r[key].map((x) => x.a.trim())
        : r[key].map((x) => x.trim()).filter(Boolean);
    if (values.length > LIMITS.items)
      errors.push([field, `Keep at most ${LIMITS.items} ${label}. Your text has been kept.`]);
    if (values.some((x) => !x || [...x].length > LIMITS.text))
      errors.push([field, `Each ${label} name needs 1–${LIMITS.text} characters.`]);
    if (new Set(values.map((x) => x.toLowerCase())).size !== values.length)
      errors.push([field, `Use distinct ${label} names (including capitalisation).`]);
  }
  if (r.activities.some((x) => [...String(x.g || "").trim()].length > LIMITS.group))
    errors.push(["set-acts", `Group names are at most ${LIMITS.group} characters.`]);
  for (const [key, field] of [
    ["symptomGroups", "set-sym"],
    ["triggerGroups", "set-trig"],
  ]) {
    if (Object.values(r[key] || {}).some((g) => [...String(g).trim()].length > LIMITS.group))
      errors.push([field, `Group names are at most ${LIMITS.group} characters.`]);
  }
  if (r.activities.some((x) => !integer(x.c, ...LIMITS.cost)))
    errors.push([
      "set-acts",
      "Activity points must be whole numbers from −10 to 10. Zero is allowed.",
    ]);
  return errors;
}

export function balanceLabel(left, cap) {
  return left < 0
    ? `${-left} over your planned budget`
    : left > cap
      ? `${left - cap} above the starting budget`
      : left === 0
        ? "No points left today"
        : "Points left today";
}

export function ongoingEpisodes(docs) {
  return listEpisodes(docs).filter(([, e]) => e.duration === "Still going" && !e.endedAt);
}

// The lower-cased text a search looks in, kept for as long as the record's readable copy is (see readableOf).
const searchTexts = new WeakMap();
const searchText = (record, make) => {
  let text = searchTexts.get(record);
  if (text === undefined) {
    text = make().toLocaleLowerCase();
    searchTexts.set(record, text);
  }
  return text;
};

export function selectHistory(docs, filters = {}) {
  const { from = "", to = "", status = "", symptom = "", ongoing = false, query = "" } = filters;
  const between = (date) => (!from || date >= from) && (!to || date <= to);
  const needle = query.trim().toLocaleLowerCase();
  const contains = (record, make) => !needle || searchText(record, make).includes(needle);
  const days = listDays(docs).filter(
    (d) =>
      between(d.date) &&
      (!status || d.status === status) &&
      contains(d, () => [d.date, ...(d.entries || []).map((e) => e.a)].join(" ")),
  );
  const episodes = listEpisodes(docs).filter(
    ([, e]) =>
      between(e.when.slice(0, 10)) &&
      (!symptom || (e.symptoms || []).includes(symptom)) &&
      (!ongoing || (e.duration === "Still going" && !e.endedAt)) &&
      contains(e, () =>
        [e.when, ...(e.symptoms || []), ...(e.before || []), e.notes || ""].join(" "),
      ),
  );
  return { days, episodes };
}

// Strip broken imported fields at the read boundary; retain the original document for recovery/export.
export function readableEpisode(e) {
  const names = (value) => (Array.isArray(value) ? value.filter((x) => typeof x === "string") : []);
  return {
    ...e,
    symptoms: names(e.symptoms),
    before: names(e.before),
    notes: typeof e.notes === "string" ? e.notes : "",
    onset: typeof e.onset === "string" ? e.onset : "",
    duration: typeof e.duration === "string" ? e.duration : "",
  };
}

// Existing captures retain their recorded offset when an end time is entered in another time zone.
export function validateEpisodeTimes(value, original = {}, now = new Date()) {
  const localInstant = (text) => new Date(text).getTime();
  const recordedInstant = (text, offset) => Date.parse(text + "Z") - offset * 60000;
  const start =
    value.when === original.when && Number.isFinite(original.whenOffset)
      ? recordedInstant(value.when, original.whenOffset)
      : localInstant(value.when);
  const end =
    value.endedAt === original.endedAt && Number.isFinite(original.endOffset)
      ? recordedInstant(value.endedAt, original.endOffset)
      : localInstant(value.endedAt);
  if (!value.when || !Number.isFinite(start)) return ["ep-when", "Choose when it started."];
  if (start > now.getTime())
    return ["ep-when", "Start time can't be in the future. Choose a time before now."];
  if (value.endedAt && !Number.isFinite(end))
    return ["ep-ended", "Choose when it ended, or leave it empty."];
  if (value.endedAt && end < start)
    return ["ep-ended", "It can't have ended before it started. Choose a later end time."];
  if (value.endedAt && end > now.getTime())
    return ["ep-ended", "End time can't be in the future. Choose a time before now."];
  return null;
}

// Separate rows preserve repeated and recovery activities for spreadsheet analysis.
export function activitiesCsv(docs) {
  const rows = [["date", "entry_id", "local_time", "activity", "cost_points"]];
  for (const d of listDays(docs).reverse())
    for (const e of d.entries) rows.push([d.date, e.id || "", e.t || "", e.a, e.c]);
  return csv(rows);
}

// Long-list helpers for the activity buttons and the symptom/trigger chips. Pure functions, no DOM, so they can be
// tested and reused by any future picker (search, favourites, groups and paging are all decided here).
import { addDays, listDays, listEpisodes } from "./model.js";

export const PICKER = {
  searchFrom: 8, // show a search box once a list is longer than this
  favourites: 6, // most shown in the favourites row
  favouriteWindow: 60, // days of history that count as "use"
  page: 12, // items shown per group before "Show more"
  searchPage: 24, // items shown per page of search results
  chipsAll: 12, // symptom/trigger lists up to this long show every chip; longer ones start compact
  chipPage: 12, // chips shown (frequent and recent first, then list order) before "Show all"
};

const fold = (s) => String(s).normalize("NFD").replace(/\p{M}/gu, "").toLocaleLowerCase();

// matches: every word of the query appears somewhere in the text, ignoring case and accents.
export function matches(query, text) {
  const words = fold(query).split(/\s+/).filter(Boolean),
    t = fold(text);
  return words.every((w) => t.includes(w));
}

// usage counts how often, and how recently, each activity, symptom and trigger name was logged.
export function usage(docs, today, days = PICKER.favouriteWindow) {
  const since = addDays(today, -days),
    out = { acts: new Map(), sym: new Map(), trig: new Map() };
  const bump = (m, name, when) => {
    const u = m.get(name) || { n: 0, last: "" };
    u.n++;
    if (when > u.last) u.last = when;
    m.set(name, u);
  };
  for (const d of listDays(docs))
    if (d.date >= since)
      for (const e of d.entries) bump(out.acts, e.a, d.date + "T" + (e.t || "00:00"));
  for (const [, e] of listEpisodes(docs))
    if (e.when.slice(0, 10) >= since) {
      for (const s of e.symptoms) bump(out.sym, s, e.when);
      for (const t of e.before) bump(out.trig, t, e.when);
    }
  return out;
}

// favourites picks up to `max` names: mostly the ones used at least twice, then the latest used to fill the rest.
export function favourites(names, use, max = PICKER.favourites) {
  const used = names.filter((n) => use.get(n)),
    byCount = [...used]
      .filter((n) => use.get(n).n >= 2)
      .sort((a, b) => use.get(b).n - use.get(a).n || use.get(b).last.localeCompare(use.get(a).last))
      .slice(0, Math.ceil((max * 2) / 3));
  const recent = used
    .filter((n) => !byCount.includes(n))
    .sort((a, b) => use.get(b).last.localeCompare(use.get(a).last));
  return [...byCount, ...recent].slice(0, max);
}

// selection says which list items the person has already logged on the day shown, and how many times. Rows keep the
// order of the list; `count` is by activity name; the rest are the rows not selected. Entries whose name is not in
// the list (one-off "Other" activities) are not rows, so they never appear here.
export function selection(rows, entries) {
  const count = new Map();
  for (const e of entries || []) count.set(e.a, (count.get(e.a) || 0) + 1);
  return {
    count,
    selected: rows.filter((r) => count.get(r.item.a)),
    rest: rows.filter((r) => !count.get(r.item.a)),
  };
}

// groupItems keeps the order the person chose: groups by first appearance, items inside by list order. Anything
// without a group goes last. A list with no groups at all comes back as one unnamed group.
export function groupItems(items, groupOf = (x) => x.g) {
  const groups = new Map(),
    loose = [];
  items.forEach((item, i) => {
    const g = (groupOf(item) || "").trim();
    if (!g) {
      loose.push({ item, i });
      return;
    }
    if (!groups.has(g)) groups.set(g, []);
    groups.get(g).push({ item, i });
  });
  if (!groups.size) return [{ name: "", rows: loose }];
  return [...groups]
    .map(([name, rows]) => ({ name, rows }))
    .concat(loose.length ? [{ name: "Ungrouped", rows: loose }] : []);
}

export const groupNames = (items) => [
  ...new Set(items.map((x) => (x.g || "").trim()).filter(Boolean)),
];

import { capOf, dayId, readableDay, used } from "./model.js";
import { byTime } from "./calendar-model.js";

export const planId = (date) => `p-${date}`;
export const plannedEntryId = (date, id) => `planned:${date}:${id}`;
// In the order of the day: timed rows by start time, then the ones with no time.
export const planRows = (plan) =>
  Array.isArray(plan?.entries) ? [...plan.entries].sort(byTime) : [];
export function energyFlow(day, settings) {
  const spent = day.entries.reduce((n, e) => n + Math.max(0, e.c), 0);
  const recovered = day.entries.reduce((n, e) => n + Math.max(0, -e.c), 0);
  const allowance = capOf(day, settings);
  return { allowance, spent, recovered, remaining: allowance - spent + recovered };
}
// Planned recovery is never included in the balance available now. Plans have their
// own document namespace, keeping unlogged days out of clinical/history reporting.
export function forecast(docs, date, settings) {
  const plan = docs[planId(date)] || {};
  const day = readableDay(docs[dayId(date)], date);
  const logged = !!docs[dayId(date)];
  const allowance = logged ? capOf(day, settings) : (plan.allowance ?? settings.budget);
  const rows = planRows(plan);
  const done = rows.filter((e) => day.entries.some((a) => a.id === plannedEntryId(date, e.id)));
  const pending = rows.filter((e) => !done.includes(e));
  const committed = pending.reduce((n, e) => n + Math.max(0, e.c), 0);
  const recovery = pending.reduce((n, e) => n + Math.max(0, -e.c), 0);
  const remaining = allowance - used(day);
  const afterWork = remaining - committed;
  return {
    plan,
    day,
    logged,
    allowance,
    rows,
    done,
    pending,
    committed,
    recovery,
    remaining,
    afterWork,
    projected: afterWork + recovery,
    shortfall: Math.max(0, -afterWork),
    gap: Math.max(0, -(afterWork + recovery)),
  };
}
export function planComparison(docs, date) {
  const rows = planRows(docs[planId(date)]);
  if (!rows.length) return null;
  const entries = readableDay(docs[dayId(date)], date).entries;
  const completed = rows.filter((r) => entries.some((e) => e.id === plannedEntryId(date, r.id)));
  const estimated = completed.reduce((n, r) => n + r.c, 0);
  const actual = entries
    .filter((e) => completed.some((r) => e.id === plannedEntryId(date, r.id)))
    .reduce((n, e) => n + e.c, 0);
  return { total: rows.length, completed: completed.length, estimated, actual };
}

import { $, html, setHTML, uid, fmtDay, signed, minus, confirmDialog, sheetMode } from "./util.js";
import { addDays, dayId, hhmm } from "./model.js";
import {
  DAY,
  NEW_DUR,
  fromMinutes,
  formatDur,
  scaleCost,
  slotText,
  spanOf,
  suggestDuration,
  toMinutes,
  validDur,
} from "./calendar-model.js";
import { createTimeGrid } from "./calendar.js";
import { validDate } from "./history-model.js";
import { energyAmount, energyWords, themeOf } from "./energy-theme.js";
import { forecast, planId, plannedEntryId } from "./planner-model.js";

const markupCache = new WeakMap();
export function setStable(el, markup) {
  if (markupCache.get(el) === markup.s) return;
  markupCache.set(el, markup.s);
  setHTML(el, markup);
}
// Colours a person can give a planned block (stored as `col` on the entry); no `col` means the default by cost.
export const TONES = [
  { id: "sand", label: "Sand" },
  { id: "sage", label: "Sage" },
  { id: "sky", label: "Sky" },
  { id: "rose", label: "Rose" },
  { id: "plum", label: "Plum" },
  { id: "slate", label: "Slate" },
];
// A copy of an activity for the same day: beside the original if there is room after it, otherwise at the same time.
export function copyOf(row) {
  const span = spanOf(row),
    t = span && span.start + span.dur * 2 <= DAY ? fromMinutes(span.start + span.dur) : row.t;
  return { ...row, id: uid(), ...(t === undefined ? {} : { t }) };
}

// The right-click menu shared by the plan and Today timelines. `actions` does the work on the page's own document:
// edit(), duplicate(), patch(changes, message) for colour and points, remove().
let menu = null;
function closeBlockMenu() {
  if (!menu) return;
  const { el, away, node } = menu;
  node.remove();
  document.removeEventListener("pointerdown", away, true);
  menu = null;
  if (el?.isConnected) el.focus({ preventScroll: true });
}
export function showEntryMenu({ x, y, el, row, ...actions }) {
  closeBlockMenu();
  const span = spanOf(row),
    entries = [];
  const add = (label, action, { key = "", danger = false, disabled = false } = {}) =>
    entries.push({ label, action, key, danger, disabled });
  add(actions.editLabel || "Edit", actions.edit, { key: "Enter" });
  add("Duplicate", actions.duplicate);
  entries.push({ heading: "Colour" }, { swatches: true });
  entries.push({
    heading: span
      ? `Points for ${formatDur(span.dur)}: ${signed(row.c)}`
      : `Points: ${signed(row.c)}`,
  });
  const step = (by) => () =>
    actions.patch({ c: row.c + by }, `${row.a} now ${signed(row.c + by)}.`);
  add("Costs 1 more (−1 left)", step(1), { disabled: row.c >= 10 });
  add("Costs 1 less (+1 left)", step(-1), { disabled: row.c <= -10 });
  entries.push(null);
  add("Remove", actions.remove, { danger: true, key: "Del" });
  const node = document.createElement("div");
  node.className = "fb-menu";
  node.setAttribute("role", "menu");
  setHTML(
    node,
    html`${entries.map((e, i) =>
      e === null
        ? html`<hr />`
        : e.heading
          ? html`<p class="fb-menu-heading">${e.heading}</p>`
          : e.swatches
            ? html`<div class="fb-swatches" role="group" aria-label="Colour">${[{ id: "", label: "Automatic" }, ...TONES].map((t) => html`<button type="button" role="menuitemradio" class="fb-swatch cal-tone-${t.id || "auto"}" data-tone="${t.id}" aria-checked="${(row.col || "") === t.id ? "true" : "false"}" aria-label="${t.label}" title="${t.label}"></button>`)}</div>`
            : html`<button type="button" role="menuitem" class="${e.danger ? "is-danger" : ""}" data-menu="${i}" ${e.disabled ? "disabled" : ""}><span>${e.label}</span>${e.key ? html`<kbd>${e.key}</kbd>` : ""}</button>`,
    )}`,
  );
  document.body.append(node);
  const w = node.offsetWidth,
    h = node.offsetHeight;
  node.style.left = `${Math.max(8, Math.min(x, innerWidth - w - 8))}px`;
  node.style.top = `${Math.max(8, Math.min(y, innerHeight - h - 8))}px`;
  node.onclick = (e) => {
    const tone = e.target.closest("[data-tone]");
    const b = e.target.closest("[data-menu]");
    if (!tone && !b) return;
    closeBlockMenu();
    if (tone) {
      const col = tone.dataset.tone;
      if ((row.col || "") !== col)
        actions.patch({ col: col || null }, col ? `${row.a} coloured ${col}.` : "Colour cleared.");
    } else entries[Number(b.dataset.menu)].action();
  };
  node.onkeydown = (e) => {
    const buttons = [...node.querySelectorAll("button:not([disabled])")];
    const i = buttons.indexOf(document.activeElement);
    if (
      e.key === "ArrowDown" ||
      e.key === "ArrowUp" ||
      e.key === "ArrowRight" ||
      e.key === "ArrowLeft"
    ) {
      e.preventDefault();
      const dir = e.key === "ArrowDown" || e.key === "ArrowRight" ? 1 : -1;
      buttons[(i + dir + buttons.length) % buttons.length]?.focus();
    } else if (e.key === "Escape" || e.key === "Tab") {
      e.preventDefault();
      closeBlockMenu();
    }
  };
  const away = (e) => {
    if (!node.contains(e.target)) closeBlockMenu();
  };
  document.addEventListener("pointerdown", away, true);
  menu = { node, away, el };
  node.querySelector("button:not([disabled])")?.focus();
}

const amount = (ctx, n) => energyAmount(n, themeOf(ctx));
// In a form, an activity's points follow its length once that is changed, until the points are typed over. It starts
// from an activity that already has a length (or a saved one whose name gives it); `set(cost, length)` says which.
// What the number typed in a form will look like everywhere else: the sign shown on tiles, blocks and in the exports
// is the effect on points left, so a cost of 2 appears as −2 and a recovery of 1 as +1.
export function effectWords(ctx, c) {
  if (!Number.isInteger(c)) return "";
  if (c === 0) return "Only records the activity; your balance does not change.";
  const theme = themeOf(ctx);
  return c > 0
    ? `Uses ${energyAmount(c, theme)}. Shown as ${signed(c)}.`
    : `Gives back ${energyAmount(-c, theme)}. Shown as ${signed(c)}.`;
}
export function followLength(ctx, durInput, costInput, hint, effect = null) {
  let base = null,
    touched = false;
  const show = () => {
    if (effect)
      effect.textContent =
        costInput.value.trim() === "" ? "" : effectWords(ctx, Number(costInput.value));
  };
  costInput.addEventListener("input", () => {
    touched = true;
    hint.textContent = "";
    show();
  });
  durInput.addEventListener("change", () => {
    const dur = Number(durInput.value),
      next = base && !touched ? scaleCost(base.cost, base.dur, dur) : null;
    if (next === null || next === Number(costInput.value)) return;
    costInput.value = String(next);
    hint.textContent = `Points follow the length: ${signed(base.cost)} for ${formatDur(base.dur)}, so ${signed(next)} for ${formatDur(dur)}. Change them if you like.`;
    show();
  });
  return {
    set(cost, length) {
      base =
        Number.isInteger(cost) && cost !== 0 && validDur(length) ? { cost, dur: length } : null;
      touched = false;
      hint.textContent = "";
      show();
    },
    refresh: show, // after the value is assigned from a saved draft or a palette choice
  };
}
// When a planned activity is logged as done it started at its planned time if that has already passed, otherwise now.
// On a past day "now" would be wrong, so only the planned time (or none) is used.
function loggedStart(ctx, row, day) {
  if (day !== ctx.today()) return row.t || "";
  const now = hhmm(new Date());
  return row.t && row.t <= now ? row.t : now;
}
// Its planned length carries over, trimmed so the logged activity still ends by midnight.
function loggedLength(row, start) {
  const from = toMinutes(start),
    dur = from === null ? row.dur : Math.min(row.dur, DAY - from);
  return validDur(dur) ? { dur } : {};
}
const writable = (ctx) => !ctx.store.status().readOnly && !ctx.store.status().restoring;
const dispatch = (ctx, date, type, arg, before) =>
  ctx.store.dispatch({
    id: planId(date),
    type,
    arg,
    before,
    original: ctx.store.view(planId(date)),
  });

function rowsMarkup(ctx, f, date, todayOnly = false) {
  return html`<ul class="plan-activities">${f.rows.map((e) => {
    const done = f.done.includes(e);
    const actual = done ? f.day.entries.find((a) => a.id === plannedEntryId(date, e.id)) : null;
    return html`<li class="plan-activity ${done ? "is-done" : ""} ${e.c < 0 ? "is-recovery" : ""}">
      <div class="plan-activity-info"><b>${e.a}</b><span class="meta">${done ? `Logged · planned ${signed(e.c)}` : e.c < 0 ? "Recovery planned" : "Planned"}${slotText(e) ? ` · ${slotText(e)}` : ""}</span></div>
      <strong class="plan-cost">${signed(actual?.c ?? e.c)}<span class="sr-only"> ${amount(ctx, Math.abs(e.c)).split(" ").slice(1).join(" ")}</span></strong>
      <div class="plan-actions">${done ? html`<span class="plan-done">✓ Done</span>` : html`${date <= ctx.today() ? html`<button type="button" class="primary small" data-plan-action="complete" data-date="${date}" data-id="${e.id}" aria-label="Log ${e.a} as done">Done</button>` : ""}${todayOnly ? "" : html`<button type="button" class="secondary small" data-plan-action="edit" data-id="${e.id}" aria-label="Edit planned ${e.a}">Edit</button><button type="button" class="secondary small" data-plan-action="remove" data-id="${e.id}" aria-label="Remove planned ${e.a}">Remove</button>`}`}</div></li>`;
  })}</ul>`;
}

// Done on Today logs the planned activity right there, as tapping an activity tile does, instead of sending the
// person to Plan and a form. Undo takes it back; tapping it among the day's logged activities corrects it.
// It started at its planned time if that has passed, otherwise now (see loggedStart), and keeps its planned length.
export function completePlanned(ctx, day, id, { focus = true } = {}) {
  if (!writable(ctx)) return;
  const f = forecast(ctx.store.all(), day, ctx.settings()),
    row = f.pending.find((r) => r.id === id);
  if (!row) return;
  const target = dayId(day),
    start = loggedStart(ctx, row, day),
    entry = {
      id: plannedEntryId(day, row.id),
      a: row.a,
      c: row.c,
      t: start,
      ...loggedLength(row, start),
      ...(row.col ? { col: row.col } : {}),
    };
  ctx.store.dispatch({
    id: target,
    type: "addEntry",
    arg: entry,
    stamp: {
      budget: f.logged ? f.day.budget : f.allowance,
      sleepPenalty: ctx.settings().sleepPenalty,
    },
    original: ctx.store.view(target),
  });
  ctx.toast(`Logged ${row.a}.`, {
    label: "Undo",
    fn: () =>
      ctx.store.dispatch({
        id: target,
        type: "removeEntry",
        arg: entry,
        original: ctx.store.view(target),
      }),
  });
  // The row that held focus is gone; keep keyboard focus on the next one (or the card's own button).
  if (!focus) return;
  const card = $("today-plan");
  (
    card.querySelector("[data-plan-action='complete']") || card.querySelector("[data-open-plan]")
  )?.focus();
}

// Taking a planned activity off its day, after asking (a block is easy to catch while dragging). Undo puts it back.
export async function removePlanned(ctx, day, id) {
  const find = () =>
    forecast(ctx.store.all(), day, ctx.settings()).pending.find((r) => r.id === id);
  const row = find();
  if (!row || !writable(ctx)) return;
  const when = slotText(row);
  const yes = await confirmDialog({
    title: "Remove from your plan?",
    body: `${row.a} (${signed(row.c)}${when ? `, ${when}` : ""}) will be taken off your plan. You can undo this straight afterwards.`,
  });
  // The plan can change while the question is open (another device, a sync): act only on what is still there.
  const current = find();
  if (!yes || !current || !writable(ctx)) return;
  dispatch(ctx, day, "removeEntry", current);
  ctx.toast("Removed from plan.", {
    label: "Undo",
    fn: () => dispatch(ctx, day, "addEntry", current),
  });
}

// Moving a planned activity on its own day (from the timeline on Today). Undo puts its time and length back.
export function reschedulePlanned(ctx, day, id, start, dur, scaled) {
  if (!writable(ctx)) return;
  const row = forecast(ctx.store.all(), day, ctx.settings()).pending.find((r) => r.id === id);
  if (!row) return;
  const t = fromMinutes(start),
    cost = scaled !== undefined && scaled !== row.c ? scaled : undefined,
    changes = { t, dur, ...(cost === undefined ? {} : { c: cost }) };
  dispatch(ctx, day, "editEntry", { id, changes }, row);
  ctx.toast(lengthToast(ctx, row, { t, dur }, cost), {
    label: "Undo",
    fn: () =>
      dispatch(
        ctx,
        day,
        "editEntry",
        {
          id,
          changes: {
            t: row.t ?? "",
            dur: row.dur ?? null,
            ...(cost === undefined ? {} : { c: row.c }),
          },
        },
        { ...row, ...changes },
      ),
  });
}
// What a change to an activity's time slot says, including what happened to its points when its length changed.
export function lengthToast(ctx, row, next, cost) {
  const words = energyWords(themeOf(ctx)).plural;
  return spanOf(row)?.dur === next.dur
    ? `Moved ${row.a} to ${slotText(next)}.`
    : `${row.a} now ${slotText(next)}${cost === undefined ? "" : `, ${signed(row.c)} to ${signed(cost)} ${words}`}.`;
}

export function renderTodayPlan(ctx, date) {
  const root = $("today-plan"),
    f = forecast(ctx.store.all(), date, ctx.settings());
  setStable(
    root,
    html`<div class="plan-heading"><div><h3>${date === ctx.today() ? "Still to come today" : "Plan for this day"}</h3><p class="meta">${f.pending.length ? `${amount(ctx, f.committed)} committed · ${amount(ctx, f.recovery)} recovery planned` : "Make room for your workload and recovery."}</p></div><button type="button" class="secondary" data-open-plan="${date}">${f.rows.length ? "Review plan" : "Plan your day"}</button></div>
    ${f.pending.length ? html`<p class="plan-outlook ${f.afterWork < 0 ? "plan-warning" : ""}">${f.afterWork < 0 ? `${amount(ctx, -f.afterWork)} beyond your allowance before planned recovery.` : `${amount(ctx, f.afterWork)} uncommitted before planned recovery.`} After planned recovery: <b>${amount(ctx, f.projected)}</b>.</p>${rowsMarkup(ctx, { ...f, rows: f.pending }, date, true)}` : f.done.length ? html`<p class="hint">All ${f.done.length} planned activities are logged. Their actual costs are included above.</p>` : ""}`,
  );
}

export function init(ctx) {
  const root = $("plan-panel"),
    form = $("plan-form");
  const saved = ctx.ui?.get("plan") || {};
  let date = validDate(saved.date) ? saved.date : ctx.today(),
    span = [1, 3, 7].includes(saved.span) ? saved.span : 7,
    editing = null,
    completing = false;
  const model = () => forecast(ctx.store.all(), date, ctx.settings());
  const lengthPoints = followLength(
    ctx,
    $("plan-dur"),
    $("plan-cost"),
    $("plan-length-hint"),
    $("plan-effect"),
  );
  const days = () => Array.from({ length: span }, (_, i) => addDays(ctx.today(), i));
  // Opened from the timeline, the form floats over it as a sheet; from the buttons and the list it stays where it is.
  const sheet = sheetMode(form, {
    onCancel: () => $("plan-cancel").click(),
    labelledBy: "plan-form-title",
  });
  function openForm(entry = null, complete = false, { floating = false } = {}) {
    if (!writable(ctx)) return;
    editing = entry;
    completing = complete;
    if (floating) sheet.on();
    else sheet.off();
    form.hidden = false;
    // Say which day this is for: the form can open far from the board it belongs to.
    const dayName = fmtDay(date, ctx.settings().locale);
    $("plan-form-title").textContent = complete
      ? `Log what actually happened on ${dayName}`
      : entry
        ? `Edit planned activity on ${dayName}`
        : `Add to ${dayName}`;
    for (const el of form.querySelectorAll("[aria-invalid]")) el.removeAttribute("aria-invalid");
    $("plan-name").value = entry?.a || "";
    $("plan-cost").value = entry?.c ?? 1;
    $("plan-time").value = complete ? loggedStart(ctx, entry, date) : entry?.t || "";
    $("plan-dur").value = entry?.dur ?? "";
    lengthPoints.set(entry?.c, entry?.dur);
    $("plan-repeat-row").hidden = !!entry || date < ctx.today();
    $("plan-repeat").value = 1;
    $("plan-repeat").max = Math.max(
      1,
      Math.min(7, days().at(-1) >= date ? days().filter((d) => d >= date).length : 1),
    );
    $("plan-repeat-label").textContent =
      $("plan-repeat").max === "1"
        ? "Add on consecutive days"
        : `Add on consecutive days (up to ${$("plan-repeat").max})`;
    $("plan-submit").textContent = complete ? "Log activity" : "Save plan";
    $("plan-form-error").textContent = "";
    setStable(
      $("plan-presets"),
      html`<option value="">Choose from your activities…</option>${ctx.settings().activities.map((e, i) => html`<option value="${i}">${e.a} (${signed(e.c)})</option>`)}`,
    );
    $("plan-presets-row").hidden = complete;
    $("plan-name").focus();
  }
  function closeForm() {
    form.hidden = true;
    editing = null;
    completing = false;
  }
  function rememberDraft() {
    if (form.hidden || !writable(ctx)) return;
    ctx.drafts?.put(`plan:${date}`, {
      original: editing,
      completing,
      a: $("plan-name").value,
      c: $("plan-cost").value,
      t: $("plan-time").value,
      dur: $("plan-dur").value,
      repeat: $("plan-repeat").value,
    });
  }
  function restoreDraft() {
    if (!form.hidden || !writable(ctx)) return;
    const draft = ctx.drafts?.get(`plan:${date}`);
    if (!draft) return;
    openForm(draft.original, draft.completing === true);
    $("plan-name").value = draft.a;
    $("plan-cost").value = draft.c;
    $("plan-time").value = draft.t;
    $("plan-dur").value = draft.dur ?? "";
    lengthPoints.refresh();
    $("plan-repeat").value = Math.min(Number(draft.repeat) || 1, Number($("plan-repeat").max));
    $("plan-form-error").textContent = "Unfinished planning draft restored.";
  }
  form.addEventListener("input", (e) => {
    rememberDraft();
    $("plan-form-error").textContent = ""; // a message about what was wrong should not outlive the fix
    e.target.removeAttribute?.("aria-invalid");
  });
  form.addEventListener("change", rememberDraft);
  $("plan-presets").addEventListener("change", (e) => {
    if (e.target.value === "") return;
    const entry = ctx.settings().activities[Number(e.target.value)];
    $("plan-name").value = entry.a;
    $("plan-cost").value = entry.c;
    if (!$("plan-dur").value) $("plan-dur").value = suggestDuration(entry.a) ?? "";
    lengthPoints.set(entry.c, suggestDuration(entry.a));
  });
  $("plan-cancel").addEventListener("click", () => {
    ctx.drafts?.remove(`plan:${date}`);
    closeForm();
  });
  // A keyboard has to pass every saved activity (two dozen stops) to reach the timeline; this goes straight there.
  $("plan-skip-palette").addEventListener("click", () => {
    // After the key press has finished: the same Enter must not also activate the control it lands on.
    setTimeout(() => $("plan-board").querySelector(".cal-day-head, .cal-block")?.focus(), 0);
  });
  $("plan-add").addEventListener("click", () => openForm());
  $("plan-start-add").addEventListener("click", () => openForm(null, false, { floating: true }));
  $("plan-span").addEventListener("change", (e) => {
    span = Number(e.target.value);
    date = ctx.today();
    closeForm();
    render();
  });
  const planFields = (plan) =>
    plan.date
      ? {
          date: plan.date,
          allowance: plan.allowance,
          status: plan.status,
          poorSleep: plan.poorSleep,
        }
      : undefined;
  $("plan-allowance").addEventListener("change", (e) => {
    const n = Number(e.target.value),
      f = model();
    if (!Number.isInteger(n) || n < 1 || n > 30 || f.logged || !writable(ctx)) {
      e.target.value = f.allowance; // the field has focus, so render() would leave a rejected number in it
      render();
      return;
    }
    // A number typed by hand replaces the kind-of-day choice that produced the old one.
    const typed = f.plan.status || f.plan.poorSleep ? { status: null, poorSleep: false } : {};
    // Choosing a kind of day and typing a number are both "set it to this": the last one wins, so a quick run of
    // changes cannot be refused as a conflict with the one just before it.
    dispatch(
      ctx,
      date,
      "patch",
      { date, allowance: n, ...typed },
      Object.keys(typed).length ? undefined : planFields(f.plan),
    );
  });
  // Green, amber, red and poor sleep take the same amounts off the budget as a check-in does, so a planned
  // day starts from what that kind of day will really have.
  function setDayType(status, poorSleep) {
    const f = model();
    if (f.logged || !writable(ctx)) return;
    const S = ctx.settings(),
      took =
        (status === "amber" ? S.amberPenalty : status === "red" ? S.redPenalty : 0) +
        (poorSleep ? S.sleepPenalty : 0),
      allowance = Math.min(30, Math.max(1, S.budget - took));
    dispatch(ctx, date, "patch", { date, allowance, status, poorSleep }, undefined);
  }
  $("plan-daytype").addEventListener("click", (e) => {
    const b = e.target.closest("[data-daytype]");
    if (b) setDayType(b.dataset.daytype, model().plan.poorSleep === true);
  });
  $("plan-poorsleep").addEventListener("change", (e) =>
    setDayType(model().plan.status || "green", e.target.checked),
  );
  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const a = $("plan-name").value.trim(),
      c = Number($("plan-cost").value),
      t = $("plan-time").value;
    const repeat = Number($("plan-repeat").value);
    // One message, about one field: mark it and put the cursor there.
    const problem = (field, message) => {
      for (const el of form.querySelectorAll("[aria-invalid]")) el.removeAttribute("aria-invalid");
      field.setAttribute("aria-invalid", "true");
      $("plan-form-error").textContent = message;
      field.focus();
    };
    if (!a || [...a].length > 60)
      return problem($("plan-name"), "Give it a name of 1–60 characters.");
    if (!Number.isInteger(c) || c < -10 || c > 10)
      return problem($("plan-cost"), "Points must be a whole number from −10 to 10.");
    if (!Number.isInteger(repeat) || repeat < 1 || repeat > Number($("plan-repeat").max))
      return problem($("plan-repeat"), `Choose between 1 and ${$("plan-repeat").max} days.`);
    const durText = $("plan-dur").value.trim(),
      dur = durText === "" ? null : Number(durText);
    if (dur !== null && !validDur(dur))
      return problem(
        $("plan-dur"),
        "Use a whole number of minutes from 5 to 1440, or leave the duration empty.",
      );
    if (dur !== null && toMinutes(t) !== null && toMinutes(t) + dur > DAY)
      return problem(
        $("plan-dur"),
        "That would run past midnight. Start earlier or shorten the duration.",
      );
    if (!writable(ctx)) return;
    const f = model();
    if (editing && !f.pending.some((row) => row.id === editing.id)) {
      $("plan-form-error").textContent =
        "This activity changed on another device. Close this form and review the plan.";
      return;
    }
    const entry = { a, c, t, id: editing?.id || uid(), ...(dur !== null ? { dur } : {}) };
    if (completing) {
      ctx.store.dispatch({
        id: dayId(date),
        type: "addEntry",
        arg: { ...entry, id: plannedEntryId(date, editing.id) },
        stamp: {
          budget: f.logged ? f.day.budget : f.allowance,
          sleepPenalty: ctx.settings().sleepPenalty,
        },
        original: ctx.store.view(dayId(date)),
      });
    } else if (editing)
      dispatch(
        ctx,
        date,
        "editEntry",
        {
          id: editing.id,
          changes: { a, c, t, ...(dur !== null || editing.dur != null ? { dur } : {}) },
        },
        editing,
      );
    else {
      for (let i = 0; i < repeat; i++) {
        if (forecast(ctx.store.all(), addDays(date, i), ctx.settings()).rows.length >= 200) {
          $("plan-form-error").textContent =
            "A selected day already has 200 planned activities. Shorten the repeat or remove an activity.";
          return;
        }
      }
      for (let i = 0; i < repeat; i++)
        dispatch(ctx, addDays(date, i), "addEntry", { ...entry, id: i ? uid() : entry.id });
    }
    ctx.drafts?.remove(`plan:${date}`);
    const wasCompleting = completing;
    closeForm();
    render();
    $("plan-add").focus({ preventScroll: true });
    ctx.toast(wasCompleting ? "Logged." : "Plan saved.");
  });
  root.addEventListener("click", (e) => {
    const day = e.target.closest("[data-plan-day]");
    if (day) {
      date = day.dataset.planDay;
      closeForm();
      render();
      return;
    }
    const recovery = e.target.closest("[data-plan-recovery]");
    if (recovery && writable(ctx)) {
      const preset = ctx
        .settings()
        .activities.find((row) => (row.id || row.a) === recovery.dataset.planRecovery);
      if (preset) {
        openForm();
        $("plan-name").value = preset.a;
        $("plan-cost").value = preset.c;
        $("plan-dur").value = suggestDuration(preset.a) ?? "";
        lengthPoints.set(preset.c, suggestDuration(preset.a));
      }
      return;
    }
    const button = e.target.closest("[data-plan-action]");
    if (!button || !writable(ctx)) return;
    const entry = model().pending.find((row) => row.id === button.dataset.id);
    if (!entry) return;
    if (button.dataset.planAction === "remove") {
      dispatch(ctx, date, "removeEntry", entry);
      ctx.toast("Removed from plan.", {
        label: "Undo",
        fn: () => dispatch(ctx, date, "addEntry", entry),
      });
    } else openForm(entry, button.dataset.planAction === "complete");
  });
  function openDay(day) {
    date = day;
    closeForm();
    ctx.go("plan");
    render();
  }
  document.addEventListener("click", (e) => {
    const open = e.target.closest("[data-open-plan]");
    if (open) openDay(open.dataset.openPlan);
    const done = e.target.closest("#today-plan [data-plan-action='complete']");
    if (done) completePlanned(ctx, done.dataset.date, done.dataset.id);
  });
  // ---- the timeline: what each gesture on the calendar means for the plan ----
  const narrow = matchMedia("(max-width: 700px)"); // a phone shows one day at a time
  narrow.addEventListener("change", () => (placing === null ? render() : setPlacing(null)));
  const dayLabel = (d) =>
    d === ctx.today()
      ? "Today"
      : `${fmtDay(d, ctx.settings().locale).split(",")[0]} ${Number(d.slice(8))}`;
  let burst = null; // the last change to a block, so a run of arrow-key moves undoes as one
  const grid = createTimeGrid($("plan-board"), {
    editable: () => writable(ctx),
    onSelectDay(d) {
      date = d;
      closeForm();
      render();
    },
    onOpen({ date: d, id }) {
      const row = forecast(ctx.store.all(), d, ctx.settings()).pending.find((r) => r.id === id);
      if (!row) return;
      date = d;
      closeForm();
      render();
      openForm(row, false, { floating: true });
    },
    onCreate({ date: d, start }) {
      if (placing !== null) return place(placing, d, start);
      date = d;
      closeForm();
      render();
      openForm(null, false, { floating: true });
      $("plan-time").value = fromMinutes(start);
      $("plan-dur").value = String(Math.min(NEW_DUR, DAY - start));
    },
    onChange: (change) => moveBlock(change),
    onRemove: ({ date: d, id }) => removePlanned(ctx, d, id),
    onMenu: (at) => openBlockMenu(at),
    onDrop: (payload, at) => addPreset(payload.preset, at),
  });
  // ---- the right-click menu on a block: edit, duplicate, colour, points, remove ----
  function patchBlock(d, row, changes, message) {
    const undo = Object.fromEntries(Object.keys(changes).map((k) => [k, row[k] ?? null]));
    dispatch(ctx, d, "editEntry", { id: row.id, changes }, row);
    ctx.toast(message, {
      label: "Undo",
      fn: () =>
        dispatch(ctx, d, "editEntry", { id: row.id, changes: undo }, { ...row, ...changes }),
    });
  }
  function duplicateBlock(d, row) {
    const f = forecast(ctx.store.all(), d, ctx.settings());
    if (f.rows.length >= 200) return ctx.toast("That day already has 200 planned activities.");
    const copy = copyOf(row);
    dispatch(ctx, d, "addEntry", copy);
    ctx.toast(`Duplicated ${row.a}.`, {
      label: "Undo",
      fn: () => dispatch(ctx, d, "removeEntry", copy),
    });
  }
  function openBlockMenu({ date: d, id, x, y, el }) {
    const row = forecast(ctx.store.all(), d, ctx.settings()).pending.find((r) => r.id === id);
    if (!row || !writable(ctx)) return;
    showEntryMenu({
      x,
      y,
      el,
      row,
      edit() {
        date = d;
        closeForm();
        render();
        openForm(row, false, { floating: true });
      },
      duplicate: () => duplicateBlock(d, row),
      patch: (changes, message) => patchBlock(d, row, changes, message),
      remove: () => removePlanned(ctx, d, id),
    });
  }
  function moveBlock(c) {
    if (!writable(ctx)) return;
    const row = forecast(ctx.store.all(), c.fromDate, ctx.settings()).pending.find(
      (r) => r.id === c.id,
    );
    if (!row) return;
    const t = fromMinutes(c.start),
      again = burst?.id === row.id && c.source === "keyboard" && Date.now() - burst.at < 1500,
      // A run of arrow-key presses is scaled from where it began, so the rounding of each step does not add up.
      fresh = again ? scaleCost(burst.origin.row.c, spanOf(burst.origin.row)?.dur, c.dur) : c.cost,
      cost = fresh !== undefined && fresh !== row.c ? fresh : undefined;
    let moved = { ...row, t, dur: c.dur, ...(cost === undefined ? {} : { c: cost }) };
    if (c.fromDate === c.toDate)
      dispatch(
        ctx,
        c.toDate,
        "editEntry",
        { id: row.id, changes: { t, dur: c.dur, ...(cost === undefined ? {} : { c: cost }) } },
        row,
      );
    else {
      const target = forecast(ctx.store.all(), c.toDate, ctx.settings());
      if (target.rows.length >= 200)
        return ctx.toast("That day already has 200 planned activities.");
      if (target.rows.some((r) => r.id === row.id)) moved = { ...moved, id: uid() };
      // Add to the new day before removing from the old one: if the second step fails you see a copy, not a loss.
      dispatch(ctx, c.toDate, "addEntry", moved);
      dispatch(ctx, c.fromDate, "removeEntry", row);
    }
    const origin = again ? burst.origin : { date: c.fromDate, row };
    burst = { id: moved.id, origin, at: Date.now() };
    ctx.toast(
      c.fromDate === c.toDate
        ? lengthToast(ctx, row, moved, cost)
        : `Moved ${row.a} to ${dayLabel(c.toDate)}, ${slotText(moved)}.`,
      {
        label: "Undo",
        fn: () => restoreBlock(origin, c.toDate, moved),
      },
    );
  }
  function restoreBlock(origin, nowDate, moved) {
    if (!writable(ctx)) return;
    burst = null;
    if (origin.date === nowDate)
      dispatch(
        ctx,
        nowDate,
        "editEntry",
        {
          id: moved.id,
          changes: {
            t: origin.row.t ?? "",
            dur: origin.row.dur ?? null,
            ...(origin.row.c === moved.c ? {} : { c: origin.row.c }),
          },
        },
        moved,
      );
    else {
      dispatch(ctx, origin.date, "addEntry", origin.row);
      dispatch(ctx, nowDate, "removeEntry", moved);
    }
  }
  function addPreset(preset, at) {
    if (!writable(ctx)) return;
    if (forecast(ctx.store.all(), at.date, ctx.settings()).rows.length >= 200)
      return ctx.toast("That day already has 200 planned activities.");
    const entry = { id: uid(), a: preset.a, c: preset.c, t: fromMinutes(at.start), dur: at.dur };
    dispatch(ctx, at.date, "addEntry", entry);
    ctx.toast(`Added ${preset.a} at ${entry.t}.`, {
      label: "Undo",
      fn: () => dispatch(ctx, at.date, "removeEntry", entry),
    });
  }
  // Saved activities can be dragged onto the timeline with a mouse or pen. A click fills the form; on a phone, where a
  // finger scrolls rather than drags, a tap picks the activity and the next tap on the timeline places it.
  let placing = null; // the index of the picked activity in the person's list
  const palette = $("plan-palette");
  const indexOf = (target) => {
    const i = target.closest("[data-preset]")?.dataset.preset;
    return i === undefined ? null : Number(i);
  };
  const presetOf = (e) => ctx.settings().activities[indexOf(e.target)];
  function setPlacing(i) {
    placing = i;
    $("plan-placing").hidden = i === null;
    $("plan-board").toggleAttribute("data-placing", i !== null);
    $("plan-placing-text").textContent =
      i === null ? "" : `Choose a time on the timeline for ${ctx.settings().activities[i]?.a}.`;
    render();
  }
  function place(i, day, start) {
    const preset = ctx.settings().activities[i];
    setPlacing(null);
    if (preset)
      addPreset(preset, {
        date: day,
        start,
        dur: Math.min(suggestDuration(preset.a) ?? NEW_DUR, DAY - start),
      });
  }
  $("plan-placing-cancel").addEventListener("click", () => setPlacing(null));
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && placing !== null && !root.hidden) setPlacing(null);
  });
  palette.addEventListener("pointerdown", (e) => {
    const preset = e.pointerType === "touch" || e.button > 0 ? null : presetOf(e);
    if (preset) grid.beginExternalDrag(e, { preset, dur: suggestDuration(preset.a) ?? NEW_DUR });
  });
  palette.addEventListener("click", (e) => {
    const preset = presetOf(e);
    if (!preset || grid.justDropped() || !writable(ctx)) return;
    if (narrow.matches) {
      const i = indexOf(e.target);
      closeForm();
      setPlacing(placing === i ? null : i);
      if (placing !== null) $("plan-board").scrollIntoView({ block: "nearest" });
      return;
    }
    closeForm();
    openForm();
    $("plan-name").value = preset.a;
    $("plan-cost").value = preset.c;
    $("plan-dur").value = suggestDuration(preset.a) ?? "";
    lengthPoints.set(preset.c, suggestDuration(preset.a));
  });

  function render() {
    if (!validDate(date) || date > addDays(ctx.today(), 6)) date = ctx.today();
    $("plan-span").value = span;
    const f = model(),
      dates = days(),
      forecasts = dates.map((d) => forecast(ctx.store.all(), d, ctx.settings()));
    // With nothing planned in view, a phone leads with the way to start instead of a row of "No plan" days.
    $("plan-start").hidden = forecasts.some((m) => m.rows.length);
    $("plan-start-add").disabled = !writable(ctx);
    setStable(
      $("plan-days"),
      html`${dates.map((d, i) => {
        const m = forecasts[i];
        return html`<button type="button" class="plan-day ${m.afterWork < 0 ? "plan-warning" : ""}" data-plan-day="${d}" aria-pressed="${d === date}"><span>${d === ctx.today() ? "Today" : fmtDay(d, ctx.settings().locale).split(",")[0]}</span><b>${m.rows.length || m.logged ? m.projected : "—"}</b><small>${m.rows.length ? `${m.pending.length} planned` : "No plan"}</small><span class="sr-only">${m.rows.length ? `${amount(ctx, m.projected)} projected; ${amount(ctx, m.afterWork)} before recovery` : ""}</span></button>`;
      })}`,
    );
    $("plan-date-label").textContent = fmtDay(date, ctx.settings().locale);
    // A save landing while the number is being typed must not put the old value back under the cursor.
    if (document.activeElement !== $("plan-allowance")) $("plan-allowance").value = f.allowance;
    $("plan-allowance").disabled = f.logged || !writable(ctx);
    $("plan-allowance-hint").textContent = f.logged
      ? "Uses this day’s logged allowance. Adjust check-in and sleep in Today."
      : `Starts at your full ${ctx.settings().budget}. Pick the kind of day you expect to take off your Amber, Red or poor-sleep amount, or type your own number.`;
    {
      const S = ctx.settings(),
        shown = f.plan.status || (Number.isInteger(f.plan.allowance) ? "" : "green");
      $("plan-daytype").hidden = f.logged;
      for (const b of $("plan-daytype").querySelectorAll("[data-daytype]")) {
        b.setAttribute("aria-pressed", String(b.dataset.daytype === shown));
        b.disabled = !writable(ctx);
      }
      $("plan-day-amber").textContent = `Amber −${S.amberPenalty}`;
      $("plan-day-red").textContent = `Red −${S.redPenalty}`;
      $("plan-poorsleep").checked = f.plan.poorSleep === true;
      $("plan-poorsleep").disabled = !writable(ctx);
      $("plan-poorsleep-text").textContent = `Poor sleep −${S.sleepPenalty}`;
    }
    // Totals only mean something once there is a plan or a log; an empty day would show a wall of zeros.
    setStable(
      $("plan-forecast"),
      !f.rows.length && !f.logged
        ? html``
        : html`<div class="plan-metrics"><div><span>Available ${date === ctx.today() ? "now" : "for this day"}</span><b>${f.remaining}</b></div><div><span>Work still planned</span><b>${signed(f.committed)}</b></div><div><span>Uncommitted</span><b>${f.afterWork}</b></div><div class="is-recovery"><span>Planned recovery</span><b>${signed(-f.recovery)}</b></div><div><span>Projected balance</span><b>${f.projected}</b></div></div>
      <p class="plan-outlook ${f.shortfall ? "plan-warning" : ""}">${f.shortfall ? `${amount(ctx, f.shortfall)} recovery or less workload needed to stay within this allowance before recovery.` : `${amount(ctx, f.afterWork)} left after planned workload, before recovery.`}${f.recovery ? ` Your recovery plan adds an estimated ${amount(ctx, f.recovery)}; ${f.gap ? `${amount(ctx, f.gap)} still uncovered.` : "it is included only in the projected balance."}` : ""}</p>`,
    );
    setStable(
      $("plan-list"),
      f.rows.length
        ? rowsMarkup(ctx, f, date)
        : html`<div class="plan-empty"><h3>A little breathing room starts here.</h3><p>Add work, commitments or recovery. You’ll see how they fit before the day gets busy.</p></div>`,
    );
    setStable(
      $("plan-recovery-options"),
      f.shortfall
        ? html`<h3>Make room for recovery</h3><p class="hint">Choose something that helps you recover. These use your saved estimates.</p><div class="plan-recovery-options">${ctx
            .settings()
            .activities.filter((e) => e.c < 0)
            .slice(0, 4)
            .map(
              (e) =>
                html`<button type="button" class="secondary" data-plan-recovery="${e.id || e.a}">${e.a} · +${-e.c}</button>`,
            )}</div>${!ctx.settings().activities.some((e) => e.c < 0) ? html`<p class="hint">Add a recovery activity with a negative cost, or reduce a planned activity’s cost.</p>` : ""}`
        : html``,
    );
    $("plan-add").disabled = !writable(ctx) || f.rows.length >= 200;
    // The timeline: every planned activity of the days in view (just the chosen day on a phone).
    const forecastOf = (d) =>
      forecasts[dates.indexOf(d)] ?? forecast(ctx.store.all(), d, ctx.settings());
    grid.render({
      editable: writable(ctx),
      days: (narrow.matches ? [date] : dates).map((d) => {
        const m = forecastOf(d);
        return {
          date: d,
          label: dayLabel(d),
          value: m.rows.length || m.logged ? `${minus(m.projected)} left` : "—",
          aria:
            m.rows.length || m.logged
              ? `${fmtDay(d, ctx.settings().locale)}: ${amount(ctx, m.projected)} left after planned recovery${m.afterWork < 0 ? `, ${amount(ctx, -m.afterWork)} over before recovery` : ""}`
              : `${fmtDay(d, ctx.settings().locale)}: nothing planned`,
          today: d === ctx.today(),
          selected: d === date,
          warn: m.afterWork < 0,
          blocks: m.rows.map((e) => ({
            id: e.id,
            title: e.a,
            cost: e.c,
            t: e.t,
            dur: e.dur,
            kind: "plan",
            tone: TONES.some((t) => t.id === e.col) ? e.col : undefined,
            done: m.done.includes(e),
            editable: !m.done.includes(e),
            removable: !m.done.includes(e),
          })),
        };
      }),
    });
    const acts = ctx.settings().activities;
    $("plan-board-help").textContent = narrow.matches
      ? "Tap an activity, then a time to add it. Use the handle on a block to move it; to change how long it takes, press and hold its bottom edge, then drag: the points follow."
      : "Drag an activity to move it, or drag its edge to change how long it takes: the points follow. Click an empty space to add one.";
    setStable(
      $("plan-palette"),
      acts.length
        ? html`<h3 class="label">${narrow.matches ? "Tap one, then a time" : "Drag onto the timeline"}</h3>${acts.map((e, i) => html`<button type="button" class="cal-chip cal-preset${e.c < 0 ? " is-recovery" : ""}" data-preset="${i}"${narrow.matches ? html` aria-pressed="${placing === i ? "true" : "false"}"` : ""}>${e.a}<span>${signed(e.c)}</span></button>`)}`
        : html``,
    );
    root
      .querySelectorAll("[data-plan-action],[data-plan-recovery]")
      .forEach((b) => (b.disabled = !writable(ctx)));
  }
  return {
    show() {
      render();
      restoreDraft();
    },
    render,
    openDay,
    hide() {
      rememberDraft();
      closeForm();
    },
    snapshot: () => ({ date, span }),
  };
}

.presence {
  --bg: #f8f9f4;
  --surface: #fff;
  --card: #fffefb;
  --fg: #203c31;
  --muted: #52655a;
  --line: #d9e1d4;
  --accent: #285c46;
  --accent-hover: #1c4735;
  --on-accent: #fff;
  --accent-soft: #edf2e7;
  --tint: #eaf0e2;
  --tint-line: #dbe4d2;
  --field: #fff;
  --field-line: #bbc9b6;
  --hl: #64825a;
  --hover: #9b5526;
  --err: #a33423;
  --ok-bg: #eef5ee;
  --ok-line: #b9d2bf;
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  color-scheme: light;
}
/* The public pages and the sign-in page follow the visitor's light or dark setting, like the app. */
@media screen and (prefers-color-scheme: dark) {
  .presence {
    --bg: #17221c;
    --surface: #1f2d25;
    --card: #1f2d25;
    --fg: #e6efe4;
    --muted: #b4c4b6;
    --line: #2c3d33;
    --accent: #8fc29f;
    --accent-hover: #a6d3b3;
    --on-accent: #10231a;
    --accent-soft: #22332a;
    --tint: #1d2c23;
    --tint-line: #2f4337;
    --field: #15201a;
    --field-line: #4d6556;
    --hl: #9bbf8b;
    --hover: #e3a674;
    --err: #ff9d8a;
    --ok-bg: #1b3024;
    --ok-line: #3b6a4a;
    color-scheme: dark;
  }
}
.presence a {
  color: inherit;
  text-decoration: none;
}
.presence p {
  margin: 0;
}
.presence h1,
.presence h2,
.presence h3 {
  font-family: var(--display);
  letter-spacing: -0.045em;
  line-height: 1.06;
}
.presence button,
.presence input {
  font: inherit;
}
.presence h1[tabindex="-1"]:focus-visible {
  outline: none;
}
.presence :focus-visible {
  outline: 3px solid #b66a32;
  outline-offset: 5px;
}
.shell {
  width: min(1200px, calc(100% - 96px));
  margin-inline: auto;
}
.skip-link {
  position: fixed;
  top: 8px;
  left: 8px;
  z-index: 20;
  padding: 12px;
  background: var(--surface);
  transform: translateY(-150%);
}
.skip-link:focus {
  transform: none;
}
.site-header {
  padding-block: 30px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.wordmark {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-family: var(--display);
  font-weight: 700;
  font-size: 29px;
  letter-spacing: -1.5px;
}
.brand-dot {
  margin-left: -6px;
  color: #779253;
}
.site-nav {
  position: static;
  background: none;
  margin: 0;
  padding: 0;
  display: flex;
  gap: 28px;
  overflow: visible;
  font-size: 14px;
}
.site-nav a,
.text-link,
.site-footer a {
  transition: color 0.2s;
}
.site-nav a:hover,
.text-link:hover,
.site-footer a:hover {
  color: var(--hover);
}
.nav-actions {
  display: flex;
  align-items: center;
  gap: 24px;
  font-size: 14px;
}
.p-button {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 14px;
  white-space: nowrap;
  min-height: 56px;
  padding: 16px 25px;
  border-radius: 8px;
  background: var(--accent);
  color: var(--on-accent) !important;
  font-weight: 700;
  font-size: 16px;
  border: 1px solid var(--accent);
  box-shadow: 0 4px 0 #203c310a;
  transition:
    transform 0.2s,
    background 0.2s;
}
.p-button:hover {
  background: var(--accent-hover);
  transform: translateY(-2px);
}
.p-button.small {
  min-height: 44px;
  padding: 10px 17px;
  font-size: 14px;
  gap: 18px;
}
.p-button span {
  font-size: 21px;
  font-weight: 400;
}
