  font-weight: 700;
  letter-spacing: 0.13em;
  display: flex;
  align-items: center;
  gap: 9px;
  line-height: 1.5;
}
.hero-copy .eyebrow {
  letter-spacing: 0.03em;
  text-transform: none;
  font-size: 14px;
}
.status-dot {
  display: inline-block;
  flex-shrink: 0;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #527957;
  box-shadow: 0 0 0 4px #52795712;
}
.hero h1 {
