  margin: 15px 0 12px;
}
.feature-card p {
  color: var(--muted);
  font-size: 15px;
  line-height: 1.7;
}
.mini-checkin,
.mini-budget,
.mini-chart {
  display: block;
  height: 65px;
  width: 100%;
  margin: 5px 0 28px;
}
.mini-checkin {
