  #print-view td {
    border-bottom: 1px solid #bbb;
    padding: 3pt 5pt;
    text-align: left;
    vertical-align: top;
  }
  #print-view tr {
    break-inside: avoid;
  }
  #print-view .small-print {
    font-size: 9pt;
    color: #444;
    margin-top: 14pt;
  }
}
