/* Ordered settings: one stable row layout, generous touch handles, clear drag/drop feedback. */
.ordered-list {
  display: grid;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
}
.order-row {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  border: 1px solid var(--line);
  border-radius: 0.65rem;
  background: var(--surface);
  padding: 0.45rem;
}
.order-row > input[type="text"] {
  min-width: 0;
  flex: 1;
  width: 0;
}
.order-row .order-cost {
  width: 4.5rem;
  flex: 0 0 4.5rem;
}
.drag-handle {
  min-width: 44px;
  min-height: 44px;
  padding: 0.25rem;
  cursor: grab;
  touch-action: none;
  font-size: 1.6rem;
  color: var(--accent);
  background: transparent;
  border: 0;
  border-radius: 0.4rem;
}
.drag-handle:active {
  cursor: grabbing;
}
.order-actions {
  display: flex;
  gap: 0.15rem;
}
.order-actions button {
  min-height: 44px;
  min-width: 40px;
  padding: 0.25rem;
  font-size: 1rem;
  text-decoration: none;
  border-radius: 0.4rem;
}
.order-actions button:hover:not(:disabled) {
  background: var(--accent-soft);
  color: var(--accent);
}
.drop-placeholder {
  outline: 2px dashed var(--accent);
  opacity: 0.45;
}
.drag-preview {
  position: fixed;
  z-index: 10000;
  pointer-events: none;
  box-shadow: 0 12px 32px color-mix(in srgb, var(--fg) 25%, transparent);
  transform: rotate(1deg);
  opacity: 0.96;
}
[aria-invalid="true"] {
  outline: 2px solid var(--red);
  outline-offset: 2px;
}
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
.panel.recovery {
  border: 2px solid var(--red);
}
/* The status pill hangs below the header; with a refused change it has words in it, so leave room for them. */
#recovery:not([hidden]) {
