}
/* On a phone the preview is read as part of the page, with each row a small card, not a window onto a wide table. */
@media (max-width: 700px) {
  #summary-preview {
    max-height: none;
    overflow: visible;
  }
  #summary-preview table,
  #summary-preview tbody {
    display: block;
  }
