    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
  }
  #summary-preview tr {
    display: block;
    margin-bottom: 10px;
    border: 1px solid var(--line);
    border-radius: 8px;
    padding: 6px 8px;
  }
  #summary-preview td {
    display: grid;
    grid-template-columns: minmax(6.5rem, 38%) 1fr;
    gap: 8px;
    border: 0;
    padding: 3px 0;
    overflow-wrap: anywhere;
  }
  #summary-preview td::before {
    content: attr(data-label);
    color: var(--muted);
    font-weight: 700;
  }
  #summary-preview td:empty {
    display: none;
  }
}
#reveal-pw {
  display: block;
  margin: 12px 0;
  padding: 12px;
  border: 1px dashed var(--accent);
  border-radius: 10px;
  font-size: 1.05rem;
