/* Contextual help uses the same quiet visual language as the log. */
.label-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}
.label-row h2 {
  margin-bottom: 0;
}
.help-tip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 32px;
  width: 32px;
  height: 32px;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--accent-soft);
  color: var(--accent);
  font: 700 0.95rem var(--body);
  cursor: help;
}
.help-tip:hover {
  border-color: var(--accent);
}
.help-tip {
  position: relative;
}
.help-tip::after {
  content: "";
  position: absolute;
  inset: -6px;
}
.help-link {
  white-space: nowrap;
  min-height: 36px;
}
.help-eyebrow,
.help-category {
  color: var(--accent);
  font-size: 0.8rem;
  font-weight: 700;
}
.help-eyebrow {
  margin: 0 0 0.4rem;
}
.help-intro {
  background: linear-gradient(135deg, var(--surface), var(--accent-soft));
  padding: 1.3rem;
}
.help-intro h2 {
  font-size: 1.45rem;
}
.help-intro p {
  margin-top: 0.4rem;
}
.help-topic {
  border-top: 1px solid var(--line);
  margin-top: 0.35rem;
}
.help-topic summary {
  cursor: pointer;
  padding: 1rem 1.6rem 1rem 0;
  position: relative;
  list-style: none;
  display: grid;
  gap: 0.25rem;
  font-weight: 700;
}
.help-topic summary:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 6px;
}
.help-topic summary::-webkit-details-marker {
  display: none;
}
.help-topic summary::after {
  content: "+";
  position: absolute;
  right: 0.2rem;
  top: 1.2rem;
  color: var(--accent);
  font-size: 1.2rem;
}
.help-topic[open] summary::after {
  content: "−";
}
.help-topic[open] summary {
  color: var(--accent);
}
.help-answer {
  padding: 0 0 1.1rem;
  font-size: 0.95rem;
  line-height: 1.6;
}
.help-answer p:first-child {
  margin-top: 0;
}
.help-answer .warn {
  margin-bottom: 1rem;
}
.tooltip {
  position: fixed;
  z-index: 30;
  max-width: min(320px, calc(100vw - 24px));
  padding: 0.75rem 0.9rem;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--fg);
  color: var(--surface);
  box-shadow: 0 8px 28px #0003;
  font-size: 0.88rem;
  line-height: 1.5;
  overflow-wrap: anywhere;
  animation: tip-appear 0.12s ease-out;
}
@keyframes tip-appear {
  from {
    opacity: 0;
    transform: translateY(3px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@media (prefers-reduced-motion: reduce) {
  .tooltip {
    animation: none;
  }
}
@media print {
  #jiggered-tooltip {
    display: none !important;
  }
}

/* Panels stack their children with one consistent gap, so adjacent buttons never touch. */
.panel > h2,
.panel > .label-row h2 {
  margin-bottom: 0;
}
.panel > .x,
.panel > .secondary,
.panel > .primary {
  justify-self: start;
}
.panel .switch-row,
.panel .advice,
.panel .cells,
.panel .hint {
  margin-top: 0;
}
.panel .hint summary {
  cursor: pointer;
  color: var(--accent);
  font-weight: 700;
}
.panel details.hint {
  display: grid;
  gap: 8px;
}
.panel details.hint p {
  margin: 8px 0 0;
}
.gauge-head .big {
  margin-top: 6px;
}
@media (max-width: 480px) {
  .panel > .secondary,
  .panel > .primary {
    justify-self: stretch;
  }
  .row > .secondary,
  .row > .primary {
    flex: 1 1 100%;
  }
  .checkin {
    gap: 6px;
  }
  .checkin button b {
    font-size: 0.95rem;
  }
  .acts {
    gap: 12px;
  }
  .act-groups {
    gap: 20px;
  }
  .act-group,
  .act-fav {
    gap: 12px;
  }
  .group-filter {
    gap: 12px;
  }
  .chips {
    gap: 10px 8px;
  }
  .chip span {
    padding: 10px 14px;
  }
  .chip-search {
    margin-bottom: 8px;
  }
  #setform .row {
    gap: 12px;
    margin-top: 14px;
  }
  #setform [data-gap] {
    margin-bottom: 4px;
  }
}

/* Long lists: search, favourites, groups and paging. Short lists never show any of this. */
.act-search input {
  font-weight: 400;
}
.act-groups {
  display: grid;
  gap: 14px;
}
.act-fav,
.act-group {
  display: grid;
  gap: 8px;
}
.act-fav h3 {
  margin: 0;
}
.act-group > summary {
  cursor: pointer;
  font-weight: 700;
  list-style: none;
  padding: 6px 0;
  display: flex;
  gap: 8px;
  align-items: baseline;
}
.act-group > summary::-webkit-details-marker {
  display: none;
}
.act-group > summary::before {
  content: "▸";
  color: var(--accent);
}
.act-group[open] > summary::before {
  content: "▾";
}
.act-group > .secondary {
  justify-self: start;
}
.chip.fav span {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--line));
}
.chip-search {
  margin-bottom: 2px;
}
.chips[data-empty="1"]::after {
  content: "Nothing matches. Clear the search to see them all.";
  color: var(--muted);
  font-size: 0.9rem;
}
@media (max-width: 480px) {
  .order-row .order-group {
    flex: 1 1 100%;
    width: 100%;
    margin-left: 48px;
    max-width: calc(100% - 48px);
  }
}
.order-row .order-group {
  flex: 0 1 8rem;
  min-width: 0;
}

/* Calm interaction: nothing below the header may move when a save starts or finishes. */
.sync[data-state="saved"] {
  opacity: 0;
}
.sync[data-state="attention"] {
  opacity: 1;
}
.sync.err {
  color: var(--red);
  font-weight: 700;
}
.checkin button,
.cell,
.act {
  transition:
    background-color 0.18s ease,
    border-color 0.18s ease,
    color 0.18s ease,
    transform 0.1s ease;
}
.cell {
  transition:
    background-color 0.25s ease,
    border-color 0.25s ease;
}
@media (prefers-reduced-motion: reduce) {
  .sync,
  .checkin button,
  .cell,
  .act {
    transition: none !important;
  }
}

/* Group filter on Today, and the shared-defaults notice */
.group-filter {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin: 4px 0 16px;
}
.group-filter[hidden] {
  display: none;
}
.pill {
  font: inherit;
  font-size: 0.9rem;
  white-space: nowrap;
  flex: none;
  min-height: 44px;
  padding: 6px 14px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: var(--bg);
  color: var(--fg);
  cursor: pointer;
  display: inline-flex;
  gap: 6px;
  align-items: center;
}
.pill .meta {
  font-variant-numeric: tabular-nums;
}
.pill:hover {
  border-color: var(--accent);
}
.pill[aria-pressed="true"] {
  background: var(--accent-soft);
  border-color: var(--accent);
  font-weight: 700;
}
.pill:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.defaults-notice {
  border-left: 4px solid var(--accent);
}
.defaults-notice {
  padding-block: 12px;
}
.defaults-notice p {
  margin: 0 0 10px;
  font-size: 0.9rem;
  line-height: 1.45;
}
.defaults-notice p .meta {
  font-size: inherit;
  font-weight: 700;
}
.defaults-notice .row {
  flex-wrap: wrap;
  gap: 8px;
}
.defaults-notice .small {
  min-height: 44px;
}

/* Symptom and trigger lists: status line above the chips */
.chip-status {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  min-height: 32px;
  margin: 2px 0 10px;
  font-size: 0.85rem;
  color: var(--muted);
}
.chip-status[hidden] {
  display: none;
}
.chip-status .x {
  min-height: 36px;
  padding: 6px 8px;
  white-space: nowrap;
}
#ep-sym-more,
#ep-trig-more {
  width: 100%;
  min-height: 44px;
  margin-top: 12px;
}

/* Morning check-in: status dot and name, a one-word feel, and what it costs as its own badge */
.checkin button b::before {
  content: "";
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--dot);
  flex: none;
}
.checkin button[data-s="green"] {
  --dot: var(--green);
}
.checkin button[data-s="amber"] {
  --dot: var(--amber);
}
.checkin button[data-s="red"] {
  --dot: var(--red);
}
.checkin button .mood {
  color: var(--muted);
  font-size: 0.85rem;
  line-height: 1.2;
}
.checkin button .cost {
  font-size: 0.75rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  padding: 3px 9px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--fg) 8%, transparent);
  color: var(--fg);
}
.checkin button[aria-pressed="true"] b::before {
  content: "✓";
  width: auto;
  height: auto;
  background: none;
  color: var(--dot);
  font-weight: 800;
  line-height: 1;
}
.checkin button[aria-pressed="true"] .mood {
  color: var(--fg);
}
.checkin button[aria-pressed="true"] .cost {
