  .history-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }
  .history-visuals,
  .patterns-grid,
  .history-records {
    grid-template-columns: minmax(0, 1fr);
  }
  .history-visuals .chart-card + .chart-card {
    border-top: 1px solid var(--line);
    padding-top: 20px;
  }
  .metric {
    padding: 12px;
    gap: 8px;
  }
  .metric b {
    font-size: 1.8rem;
  }
  .metric .label {
    font-size: 0.68rem;
  }
  .history-intro,
  .profile-hero {
    padding: 18px;
  }
  .profile-hero h2 {
    font-size: 1.5rem;
  }
  .profile-avatar {
    width: 56px;
    height: 56px;
    border-radius: 16px;
    font-size: 1.3rem;
  }
  .profile-heading {
    gap: 12px;
  }
  .chart-inspector .meta {
    min-height: 0;
  }
}
@media (max-width: 380px) {
  .history-filter-panel .filters,
  .row2:has(#profile-theme) {
    grid-template-columns: minmax(0, 1fr);
  }
  .history-filter-panel .filters label:has(#hist-query) {
    grid-column: auto;
  }
  .profile-stats {
    gap: 8px;
  }
  .profile-stats span {
    font-size: 0.74rem;
  }
}
@media (forced-colors: active) {
  .chart-used,
  .chart-allowance {
    stroke: CanvasText;
  }
  .chart-point,
  .chart-episode,
  .composition-green,
  .composition-amber,
  .composition-red {
    fill: CanvasText;
  }
  .chart-hit.is-inspected {
    stroke: Highlight;
    fill: transparent;
  }
  .chart-grid {
    stroke: GrayText;
  }
  .profile-avatar {
    border: 1px solid CanvasText;
  }
}
.history-intro p {
  margin: 0;
}
/* Calm History: one period, the calendar and one day before optional detail. */
.history-period-bar {
  display: flex;
  gap: 12px 16px;
  align-items: center;
  flex-wrap: wrap;
}
.history-period-bar > .field {
  display: flex;
  align-items: center;
  gap: 10px;
  white-space: nowrap;
}
.history-period-bar > .field select {
  width: auto;
  min-width: 130px;
}
.history-period-bar > .meta {
  flex: 1 1 220px;
  max-width: none;
}
.history-period-bar > .primary {
  margin-left: auto;
}
/* Shown only after narrowing the period to one day: a button, not a bar the width of the page. */
#history-return-period {
  justify-self: start;
}
/* The calendar and the selected day are two cards of one height: the calendar fills its card whatever the period, and
   the day's buttons dock to the bottom edge of theirs. */
.history-overview {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
  gap: 18px;
  align-items: stretch;
}
.history-overview > * {
  min-width: 0;
}
.matrix-overview {
  display: flex;
  flex-direction: column;
}
.matrix-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px 20px;
}
.matrix-title {
  flex: 1 1 240px;
  display: grid;
  gap: 4px;
  min-width: 0;
}
.matrix-title h2 {
  margin: 0;
}
.matrix-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 14px 24px;
  border-top: 1px solid var(--line);
  padding-top: 14px;
}
.matrix-facts {
  flex: 1 1 240px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}
.matrix-facts > div {
  display: grid;
  gap: 6px;
}
.matrix-facts b {
  font: 700 1.5rem var(--display);
}
.matrix-facts span {
  font-size: 0.8rem;
  color: var(--muted);
}
.history-disclosure > summary {
  list-style: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 44px;
  cursor: pointer;
}
.history-disclosure > summary::-webkit-details-marker {
  display: none;
}
.history-disclosure > summary h2::before {
  content: "▸ ";
  color: var(--accent);
}
.history-disclosure[open] > summary h2::before {
  content: "▾ ";
}
.history-disclosure > summary .meta {
  text-align: right;
  overflow-wrap: anywhere;
}
/* The heading's bottom margin would push the title off the summary's centre. */
.history-disclosure > summary h2,
.history-filter-panel > summary h2 {
  margin: 0;
}
.history-section-body {
  display: grid;
  gap: 18px;
  min-width: 0;
}
.history-section-body > * {
  min-width: 0;
}
.matrix-day-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}
.matrix-day-heading > div:first-child {
  display: grid;
  gap: 4px;
  min-width: 0;
}
.matrix-day-heading .row {
  flex: none;
  flex-wrap: nowrap;
  gap: 6px;
}
.matrix-day-heading button {
  min-width: 44px;
  min-height: 44px;
}
.matrix-day-heading .row > button {
  flex: 0 0 44px;
  padding-inline: 0;
}
.matrix-balance {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 4px 16px;
  padding: 14px 16px;
  background: var(--accent-soft);
  border-radius: 10px;
}
.matrix-balance > .label {
  grid-column: 1 / -1;
}
.matrix-balance > b {
  font: 700 2.5rem var(--display);
  line-height: 1;
}
.matrix-activities,
.matrix-episodes {
  list-style: none;
  padding: 0;
  margin: 8px 0 0;
}
.matrix-activities li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 8px 0;
  border-bottom: 1px solid var(--line);
}
.matrix-activities li > span {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 10px;
  overflow-wrap: anywhere;
  min-width: 0;
}
.matrix-activities b {
  white-space: nowrap;
}
.matrix-activities .recovery {
  color: var(--accent);
}
.matrix-episodes button {
  width: 100%;
  justify-content: space-between;
  gap: 12px;
  text-align: left;
}
.matrix-episodes button > span:first-child {
  display: grid;
  gap: 4px;
  overflow-wrap: anywhere;
}
.matrix-reading h4 {
  margin: 0;
  font-size: 0.9rem;
}
.matrix-reading .plan-history {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 14px 16px;
}
.matrix-reading .plan-history p {
  margin: 0;
}
.plan-history-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px 12px;
}
.matrix-mode {
  flex: 0 1 200px;
  min-width: 190px;
  font-size: 0.78rem;
}
.matrix-mode select {
  padding: 8px;
}
.matrix-period {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}
.matrix-period .meta {
  font-size: 0.8rem;
}
.matrix-period .row:has(button:not([hidden])) {
  min-height: 36px;
}

/* The days. data-layout is set in history-matrix.js (see matrixLayout): a list of rows for a week or less, a calendar
   for a few weeks, a heatmap with a column per week for more. Each fills the width of its card. A day's colours are
   the --tone variables, so a list row can colour only its chip while a calendar square or heatmap cell is the colour. */
.matrix-body {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 14px;
  min-width: 0;
}
.matrix-calendar {
  display: grid;
  gap: 8px 6px;
  min-width: 0;
}
.matrix-grid {
  display: grid;
  gap: 4px;
  min-width: 0;
  align-self: start;
}
/* A dot in the corner of a day that has an episode, whatever the calendar is coloured by. */
.matrix-ep {
  position: absolute;
  top: 3px;
  right: 3px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--fg);
  box-shadow: 0 0 0 2px var(--surface);
}
.matrix-ep-key {
  position: static;
  display: inline-block;
  width: 8px;
  height: 8px;
  margin-right: 6px;
  box-shadow: none;
}
.matrix-dense .matrix-cell .matrix-ep {
  display: none;
}
.matrix-cell {
  position: relative;
  --tone-bg: var(--spent);
  --tone-ink: var(--fg);
  min-width: 0;
  min-height: 0;
  width: 100%;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 4px;
  background: var(--tone-bg);
  color: var(--tone-ink);
  font: 700 0.68rem var(--body);
  cursor: pointer;
  display: grid;
  place-items: center;
}
.matrix-cell.green,
.matrix-cell.recovery {
  --tone-bg: var(--green);
  --tone-ink: #fff;
}
.matrix-cell.amber {
  --tone-bg: var(--amber);
  --tone-ink: #1d2624;
}
.matrix-cell.red {
  --tone-bg: var(--red);
  --tone-ink: #fff;
}
.matrix-cell.level-1,
.matrix-key.level-1 {
  --tone-bg: color-mix(in srgb, var(--accent) 20%, var(--surface));
}
.matrix-cell.level-2,
.matrix-key.level-2 {
  --tone-bg: color-mix(in srgb, var(--accent) 40%, var(--surface));
}
.matrix-cell.level-3,
.matrix-key.level-3 {
  --tone-bg: color-mix(in srgb, var(--accent) 85%, var(--surface));
  --tone-ink: var(--bg);
}
.matrix-cell.level-4,
.matrix-key.level-4 {
  --tone-bg: var(--accent);
  --tone-ink: var(--bg);
}
.matrix-cell.empty {
  --tone-bg: var(--bg);
  --tone-ink: var(--muted);
  border: 1px dashed color-mix(in srgb, var(--muted) 40%, transparent);
}
.matrix-blank {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: var(--bg);
  opacity: 0.4;
}
.matrix-cell[aria-pressed="true"] {
  outline: 2px solid var(--fg);
  outline-offset: 1px;
}
.matrix-cell:hover {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}
.matrix-mark {
  line-height: 1;
}

/* List: a row per day, each with its chip and a line saying what was recorded. */
.matrix-calendar[data-layout="list"] .matrix-months,
.matrix-calendar[data-layout="list"] .matrix-weekdays {
  display: none;
}
.matrix-calendar[data-layout="list"] .matrix-grid {
  grid-template-columns: minmax(0, 1fr);
  gap: 8px;
}
.matrix-calendar[data-layout="list"] .matrix-cell {
  grid-template-columns: 4.8rem 3.6rem minmax(0, 1fr);
  place-items: center start;
  column-gap: 14px;
  min-height: 56px;
  padding: 6px 16px 6px 14px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--bg);
  color: var(--fg);
  font: 400 0.9rem var(--body);
  text-align: left;
}
.matrix-calendar[data-layout="list"] .matrix-cell[aria-pressed="true"] {
  background: var(--accent-soft);
}
.matrix-calendar[data-layout="list"] .matrix-when {
  display: grid;
  gap: 2px;
  line-height: 1.2;
}
.matrix-calendar[data-layout="list"] .matrix-when b {
  font-size: 0.95rem;
}
.matrix-calendar[data-layout="list"] .matrix-when span {
  font-size: 0.8rem;
  color: var(--muted);
}
.matrix-calendar[data-layout="list"] .matrix-mark {
  justify-self: stretch;
  padding: 8px 6px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: var(--tone-bg);
  color: var(--tone-ink);
  font: 700 1rem var(--display);
  text-align: center;
}
.matrix-calendar[data-layout="list"] .matrix-cell.empty .matrix-mark {
  border: 1px dashed color-mix(in srgb, var(--muted) 40%, transparent);
}
.matrix-calendar[data-layout="list"] .matrix-note {
  color: var(--muted);
  line-height: 1.35;
  overflow-wrap: anywhere;
}

/* Calendar: Monday to Sunday across, a row per week, the date in each square. */
.matrix-calendar[data-layout="calendar"] {
  grid-template-columns: minmax(0, 1fr);
}
.matrix-calendar[data-layout="calendar"] .matrix-months {
  display: none;
}
.matrix-calendar[data-layout="calendar"] .matrix-weekdays {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 6px;
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 700;
  text-align: center;
}
.matrix-calendar[data-layout="calendar"] .matrix-grid {
  grid-template-columns: repeat(7, minmax(0, 1fr));
  grid-auto-rows: 58px;
  gap: 6px;
}
.matrix-calendar[data-layout="calendar"] .matrix-cell {
  grid-template-rows: auto 1fr;
  place-items: stretch;
  padding: 7px 9px;
  border-radius: 8px;
  text-align: left;
}
.matrix-calendar[data-layout="calendar"] .matrix-when {
  font-size: 0.72rem;
  line-height: 1.1;
}
.matrix-calendar[data-layout="calendar"] .matrix-mark {
  align-self: end;
  justify-self: end;
  font: 700 1.05rem var(--display);
}
.matrix-calendar[data-layout="calendar"] .matrix-blank {
  border-radius: 8px;
}

/* Heatmap: a column per week, weekday letters down the side. Cells share the width, so a longer period gets smaller
   cells rather than a smaller grid. */
.matrix-calendar[data-layout="heatmap"] {
  grid-template-columns: 18px minmax(0, 1fr);
}
.matrix-calendar[data-layout="heatmap"] .matrix-months {
  grid-column: 2;
  display: flex;
  justify-content: space-between;
  gap: 6px;
  color: var(--muted);
  font-size: 0.7rem;
  white-space: nowrap;
}
.matrix-calendar[data-layout="heatmap"] .matrix-weekdays {
  display: grid;
  grid-template-rows: repeat(7, minmax(0, 1fr));
  gap: 4px;
  font-size: 0.7rem;
  line-height: 1;
  color: var(--muted);
}
/* The letters add no height of their own, so they never stretch their column past the cells beside them; each is
   stretched to its row and centred in it, however small the cells are. */
.matrix-calendar[data-layout="heatmap"] .matrix-weekdays span {
  display: flex;
  align-items: center;
  contain: size;
}
.matrix-calendar[data-layout="heatmap"] .matrix-grid {
  grid-auto-flow: column;
  grid-template-rows: repeat(7, minmax(0, 1fr));
  grid-template-columns: repeat(var(--weeks), minmax(0, 1fr));
}
.matrix-calendar[data-layout="heatmap"] .matrix-cell,
.matrix-calendar[data-layout="heatmap"] .matrix-blank {
  aspect-ratio: 1;
  max-height: 48px;
}
.matrix-dense .matrix-calendar .matrix-mark {
  display: none;
}
.matrix-dense .matrix-calendar .matrix-grid,
.matrix-dense .matrix-calendar .matrix-weekdays {
  gap: 3px;
}
.matrix-dense .matrix-calendar .matrix-cell,
.matrix-dense .matrix-calendar .matrix-blank {
  border-radius: 2px;
}
.matrix-reading {
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 0;
}
.matrix-reading h3 {
  font: 700 1.25rem/1.2 var(--display);
  letter-spacing: -0.03em;
  margin: 0;
  overflow-wrap: anywhere;
}
.matrix-reading dl {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin: 0;
}
.matrix-reading dt {
  font-size: 0.74rem;
  color: var(--muted);
}
.matrix-reading dd {
  font-size: 0.86rem;
  margin: 4px 0 0;
  font-weight: 700;
  overflow-wrap: anywhere;
}
/* A day with nothing on it: the message fills the space the records would, and the button stays at the bottom. */
.matrix-reading > .empty {
  flex: 1 1 auto;
  display: grid;
  place-content: center;
  padding: 16px;
  border: 1px dashed var(--line);
  border-radius: 10px;
  text-align: center;
}
.matrix-reading > .row:last-child {
  margin-top: auto;
}
.matrix-reading > .row > button {
  flex: 1 1 auto;
}
.matrix-day {
  flex: 0 1 220px;
  font-size: 0.8rem;
}
.matrix-legend {
  margin-block: 0;
}
.matrix-legend .matrix-key {
  border-radius: 3px;
  width: 12px;
  height: 12px;
  background: var(--tone-bg);
}
@media (max-width: 700px) {
  #history-return-period {
    justify-self: stretch;
  }
  .history-overview {
    grid-template-columns: 1fr;
  }
  .history-period-bar {
    align-items: stretch;
    gap: 12px;
  }
  .history-period-bar > .field {
    flex: 1 1 100%;
    justify-content: space-between;
  }
  .history-period-bar > .field select {
    flex: 1 1 auto;
  }
  .history-period-bar > .meta {
    flex-basis: 100%;
    min-width: 0;
  }
  .history-period-bar > .primary {
    width: 100%;
  }
  .history-disclosure > summary {
    flex-wrap: wrap;
  }
  .history-disclosure > summary .meta {
    text-align: left;
  }
  .matrix-day {
    flex-basis: 100%;
  }
  .matrix-mode {
    flex: 1 1 100%;
    min-width: 0;
  }
  .matrix-calendar[data-layout="list"] .matrix-cell {
    grid-template-columns: 4.2rem 3.2rem minmax(0, 1fr);
    column-gap: 10px;
    padding-inline: 10px;
  }
}
@media (max-width: 700px) {
  /* A month of days is six columns: let the grid use the panel's edge so each day is a touch-sized target. */
  .matrix-calendar[data-layout="heatmap"] {
    grid-template-columns: 14px minmax(0, 1fr);
    gap: 8px 4px;
    width: calc(100% + 16px);
    margin-inline: -8px;
  }
  .matrix-calendar[data-layout="heatmap"] .matrix-grid {
    gap: 3px;
  }
  .matrix-calendar[data-layout="heatmap"] .matrix-weekdays {
    gap: 3px;
  }
  .matrix-dense .matrix-calendar .matrix-grid,
  .matrix-dense .matrix-calendar .matrix-weekdays {
    gap: 2px;
  }
  .matrix-calendar[data-layout="heatmap"] .matrix-months {
    font-size: 0.65rem;
  }
}
@media (forced-colors: active) {
  .matrix-cell {
    border: 1px solid CanvasText;
  }
  .matrix-cell[aria-pressed="true"] {
    outline-color: Highlight;
  }
  .matrix-dense .matrix-calendar .matrix-mark {
    display: inline;
  }
  .matrix-reading {
    border-color: CanvasText;
  }
}

/* The activity, symptom and trigger editors are sections that start closed, so the page is short until you open one. */
.list-section {
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--bg);
}
.list-section > summary {
  cursor: pointer;
  font-weight: 700;
  list-style: none;
  display: flex;
  gap: 8px;
  align-items: baseline;
  min-height: 44px;
  padding: 10px 12px;
  box-sizing: border-box;
  align-items: center;
}
.list-section > summary::-webkit-details-marker {
  display: none;
}
.list-section > summary::before {
  content: "▸";
  color: var(--accent);
  transition: transform 0.15s;
}
.list-section[open] > summary::before {
  transform: rotate(90deg);
}
.list-section[open] > summary {
  border-bottom: 1px solid var(--line);
}
.list-section > .list-body {
  display: grid;
  gap: 10px;
  padding: 12px;
}
.list-section > summary:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
  .list-section > summary::before {
    transition: none;
  }
}

/* Section shortcuts scroll a panel to the top; leave room for the sticky tab bar. */
#trends-panel,
#history-records,
#history-share,
#profile-panel,
#settings-panel,
#pw-panel {
  scroll-margin-top: 84px;
}
#history-records h2:focus,
#history-share h2:focus {
  outline: none;
}
#history-records h2:focus-visible,
#history-share h2:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

/* Touch targets: text-style buttons are at least 44px tall, without changing how they read. */
.x {
  min-height: 44px;
  padding: 0 6px;
  display: inline-flex;
  align-items: center;
  text-underline-offset: 3px;
}
.panel > .x {
  margin-inline: -6px;
}

/* Today: the check-in shrinks to one line once chosen, so the activities rise up the screen. */
.checkin-done {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 6px 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--bg);
}
.checkin-done .dot {
  margin-right: 8px;
}
.checkin-done b {
  font-family: var(--display);
}

/* First-run checklist */
.onboarding {
  border-left: 4px solid var(--accent);
}
.steps {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 10px;
}
.steps li {
  display: flex;
  gap: 10px;
  align-items: flex-start;
}
.steps .tick {
  flex: none;
  width: 22px;
  height: 22px;
  margin-top: 1px;
  border-radius: 50%;
  border: 2px solid var(--line);
  display: grid;
  place-items: center;
  font-size: 0.8rem;
  font-weight: 800;
  color: var(--surface);
}
.steps li.done .tick {
  background: var(--accent);
  border-color: var(--accent);
}
.steps li.done .tick::before {
  content: "✓";
}
.steps li.done > span:last-child {
  color: var(--muted);
  text-decoration: line-through;
}
#step-wording .tick {
  visibility: hidden; /* a choice, not a step to finish */
}
.step-wording-line {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 12px;
}
.step-wording {
  display: inline-flex;
