import { energyWords, energyAmount, energyCopy, themeOf, SPOON_PATH } from "./energy-theme.js";
import {
  $,
  html,
  setHTML,
  uid,
  fmtLongDay,
  signed,
  minus,
  confirmDialog,
  sheetMode,
} from "./util.js";
import {
  DAY,
  NEW_DUR,
  fromMinutes,
  scaleCost,
